    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_StopsAfterJsonArrayAppendExceedsPayloadLimit(bool sqlite)
    {
        const string input = "[{\"kind\":\"x\"},{\"kind\":\"must-not-run\"}]";
        var seedJson = JsonSerializer.Serialize(new[]
        {
            new string('x', WorkflowArrayLiteral.MaximumPayloadBytes - 10)
        });
        Assert.True(seedJson.Length < WorkflowArrayLiteral.MaximumPayloadBytes);
        Assert.True(seedJson.Length + 1 + "{\"kind\":\"x\"}".Length > WorkflowArrayLiteral.MaximumPayloadBytes);
        var revision = WorkflowRevision.Create(JsonArrayAppendItemBodyDefinition(seedJson),
            "production-body-json-array-append-limit-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var events = new List<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var result = await new WorkflowRunner().ExecuteProductionBodyActivationSequenceProofAsync(
            runStore.RunId, revision, input, "index", null, Record,
            arrayElementType: WorkflowDataTypes.Json);

        Assert.True(result.Failed);
        Assert.DoesNotContain(events, evt => evt.ScopeId == "array-loop/1");
        var failure = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeFailed && evt.NodeId == "append");
        Assert.Contains($"Typed array result exceeds {WorkflowArrayLiteral.MaximumPayloadBytes} UTF-8 bytes", failure.Data,
            StringComparison.Ordinal);
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.NodeFailed && evt.NodeId == "output" &&
            evt.ScopeId == "array-loop/0");
        AssertPersistedSequence(runStore, events, "failed");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("failed", reopened.Status);
        Assert.DoesNotContain(reopened.Events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
            evt.ScopeId == "array-loop/0");
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_EvaluatesGraphFunctionPerItem(bool sqlite)
    {
        const string input = "[\"alpha\",\"beta\"]";
        var revision = WorkflowRevision.Create(GraphFunctionValueBodyDefinition(),
            "production-body-graph-function-activation-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var events = new List<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var outcome = await new WorkflowRunner()
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record);

        Assert.False(outcome.Failed);
        Assert.Equal("alpha!;beta!", outcome.Output);
        AssertPersistedSequence(runStore, events, "completed");
        for (var index = 0; index < 2; index++)
        {
            var scopeId = $"array-loop/{index}";
            var evaluated = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.DataEvaluated &&
                evt.NodeId == "call" && evt.ScopeId == scopeId);
            Assert.Equal("data:call-output", evaluated.ConnectionId);
            using var payload = JsonDocument.Parse(evaluated.Data!);
            var expectedItem = index == 0 ? "alpha" : "beta";
            Assert.Equal(expectedItem + "!", payload.RootElement.GetProperty("value").GetString());
            Assert.Equal(expectedItem, payload.RootElement.GetProperty("function")
                .GetProperty("inputs").GetProperty("text").GetString());
            Assert.Contains(payload.RootElement.GetProperty("function").GetProperty("evaluatedValues")
                .EnumerateArray(), value => value.GetProperty("nodeId").GetString() == "concat" &&
                value.GetProperty("value").GetString() == expectedItem + "!");
        }

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Started && evt.NodeId is null);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Completed && evt.NodeId is null);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_CallsPinnedWorkflowPerItem(bool sqlite)
    {
        const string input = "[\"alpha\",\"beta\",\"gamma\"]";
        var childDefinition = new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "array-iteration-passthrough-child", "input",
            ImmutableSortedDictionary<string, NodeDefinition>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("input", new(NodeTypes.Input, "1.0.0"))
                .Add("output", new(NodeTypes.Output, "1.0.0")
                    { OutputDataType = WorkflowDataTypes.String }),
            ImmutableSortedDictionary<string, ConnectionDefinition>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("input-output", new(new("input", "out"), new("output", "in"), "data")))
        {
            ExecutionConnections = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("input-output", Edge("input", "then", "output", "execute"))
        };
        var child = WorkflowRevision.Create(childDefinition, "array-iteration-passthrough-child-proof");
        var nodes = ImmutableSortedDictionary<string, NodeDefinition>.Empty.WithComparers(StringComparer.Ordinal)
            .Add("input", new(NodeTypes.Input, "1.0.0"))
            .Add("call", new NodeDefinition(NodeTypes.WorkflowCall, "1.0.0")
            {
                WorkflowCall = new(child.Definition.WorkflowId, child.RevisionId, 1,
                    child.ContentHash, child.Definition)
            })
            .Add("output", new(NodeTypes.Output, "1.0.0")
                { OutputDataType = WorkflowDataTypes.String });
        var connections = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty.WithComparers(StringComparer.Ordinal)
            .Add("input-call", new(new("input", "out"), new("call", "in"), "data"))
            .Add("call-output", new(new("call", "out"), new("output", "in"), "data"));
        var execution = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty.WithComparers(StringComparer.Ordinal)
            .Add("input-call", Edge("input", "then", "call", "execute"))
            .Add("call-output", Edge("call", "out", "output", "execute"));
        var definition = new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "array-iteration-workflow-call-body-proof", "input", nodes, connections)
        {
            ExecutionConnections = execution,
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        WorkflowValidator.ThrowIfInvalid(definition);
        var revision = WorkflowRevision.Create(definition, "array-iteration-workflow-call-body-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var events = new List<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var result = await new WorkflowRunner()
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record);

        Assert.False(result.Failed);
        Assert.Equal("alpha;beta;gamma", result.Output);
        AssertPersistedSequence(runStore, events, "completed");
        foreach (var (item, index) in new[] { ("alpha", 0), ("beta", 1), ("gamma", 2) })
        {
            var activationScope = $"array-loop/{index}";
            var childScope = $"{activationScope}/call";
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SubworkflowStarted &&
                evt.ScopeId == childScope);
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SubworkflowCompleted &&
                evt.ScopeId == childScope && evt.Data == item);
            Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.SubworkflowEvidence &&
                evt.NodeId == "call" && evt.ScopeId == childScope));
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
                evt.ScopeId == activationScope);
        }

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("completed", reopened.Status);

        const string cancelledInput = "[\"alpha\",\"beta\"]";
        using var cancelledStore = new ProofRunStore(revision, cancelledInput, sqlite);
        using var cancellation = new CancellationTokenSource();
        var cancelledEvents = new List<ExecutionEvent>();

        ValueTask RecordCancelled(ExecutionEvent evt)
        {
            cancelledStore.Store.Append(cancelledStore.RunId, evt.Sequence - 1, [evt]);
            cancelledEvents.Add(evt);
            if (evt.Kind == ExecutionEventKinds.SubworkflowStarted && evt.ScopeId == "array-loop/0/call")
                cancellation.Cancel();
            return ValueTask.CompletedTask;
        }

        var cancelled = await new WorkflowRunner()
            .ExecuteProductionBodyActivationSequenceProofAsync(cancelledStore.RunId, revision, cancelledInput,
                "index", null, RecordCancelled, cancellation.Token);

        Assert.True(cancelled.Cancelled);
        Assert.False(cancelled.Failed);
        Assert.Single(cancelledEvents, evt => evt.Kind == ExecutionEventKinds.SubworkflowStarted &&
            evt.ScopeId == "array-loop/0/call");
        Assert.Single(cancelledEvents, evt => evt.Kind == ExecutionEventKinds.SubworkflowCancelled &&
            evt.ScopeId == "array-loop/0/call");
        Assert.Contains(cancelledEvents, evt => evt.Kind == ExecutionEventKinds.SubworkflowEvidence &&
            evt.ScopeId == "array-loop/0/call" &&
            WorkflowCallLifecycleEvidence.TryRead(evt.Data, out var evidence) &&
            evidence!.Lifecycle == ExecutionEventKinds.SubworkflowCancelled);
        Assert.Contains(cancelledEvents, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
            evt.ScopeId == "array-loop/0" && evt.Data!.Contains("cancelled", StringComparison.Ordinal));
        Assert.DoesNotContain(cancelledEvents, evt => evt.ScopeId == "array-loop/1" ||
            evt.ScopeId?.StartsWith("array-loop/1/", StringComparison.Ordinal) == true);
        Assert.Single(cancelledEvents, evt => evt.Kind == ExecutionEventKinds.Cancelled && evt.NodeId is null);
        AssertPersistedSequence(cancelledStore, cancelledEvents, "cancelled");

        var reopenedCancelled = cancelledStore.ReopenStore().Get(cancelledStore.RunId)!;
        Assert.Equal(cancelledEvents, reopenedCancelled.Events);
        Assert.Equal("cancelled", reopenedCancelled.Status);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_StopsAtFailedPinnedWorkflow(bool sqlite)
    {
        var childDefinition = new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "array-iteration-failing-child", "input",
            ImmutableSortedDictionary<string, NodeDefinition>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("input", new(NodeTypes.Input, "1.0.0"))
                .Add("parse", new(NodeTypes.StringToInteger, "1.0.0"))
                .Add("format", new(NodeTypes.IntegerToString, "1.0.0"))
                .Add("output", new(NodeTypes.Output, "1.0.0")
                    { OutputDataType = WorkflowDataTypes.String }),
            ImmutableSortedDictionary<string, ConnectionDefinition>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("input-parse", new(new("input", "out"), new("parse", "in"), "data"))
                .Add("parse-format", new(new("parse", "out"), new("format", "in"), "data"))
                .Add("format-output", new(new("format", "out"), new("output", "in"), "data")))
        {
            ExecutionConnections = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("input-output", Edge("input", "then", "output", "execute"))
        };
        var child = WorkflowRevision.Create(childDefinition, "array-iteration-failing-child-proof");
        var nodes = ImmutableSortedDictionary<string, NodeDefinition>.Empty.WithComparers(StringComparer.Ordinal)
            .Add("input", new(NodeTypes.Input, "1.0.0"))
            .Add("call", new NodeDefinition(NodeTypes.WorkflowCall, "1.0.0")
            {
                WorkflowCall = new(child.Definition.WorkflowId, child.RevisionId, 1,
                    child.ContentHash, child.Definition)
            })
            .Add("output", new(NodeTypes.Output, "1.0.0")
                { OutputDataType = WorkflowDataTypes.String });
        var data = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty.WithComparers(StringComparer.Ordinal)
            .Add("input-call", new(new("input", "out"), new("call", "in"), "data"))
            .Add("call-output", new(new("call", "out"), new("output", "in"), "data"));
        var definition = new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "array-iteration-failing-workflow-call-proof", "input", nodes, data)
        {
            ExecutionConnections = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("input-call", Edge("input", "then", "call", "execute"))
                .Add("call-output", Edge("call", "out", "output", "execute")),
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        WorkflowValidator.ThrowIfInvalid(definition);
        var revision = WorkflowRevision.Create(definition, "array-iteration-failing-workflow-call-proof");
        const string input = "[\"invalid\",\"13\"]";
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var events = new List<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var result = await new WorkflowRunner()
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record);

        Assert.True(result.Failed);
        Assert.False(result.OutcomeUnknown);
        AssertPersistedSequence(runStore, events, "failed");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SubworkflowStarted &&
            evt.ScopeId == "array-loop/0/call");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SubworkflowFailed &&
            evt.ScopeId == "array-loop/0/call");
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.NodeFailed &&
            evt.NodeId == "parse" && evt.ScopeId == "array-loop/0/call");
        Assert.DoesNotContain(events, evt => evt.ScopeId == "array-loop/1" ||
            evt.ScopeId?.StartsWith("array-loop/1/", StringComparison.Ordinal) == true);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("failed", reopened.Status);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_CallsPinnedWorkflowInterfacePerItem(bool sqlite)
    {
        var revision = PinnedWorkflowInterfaceBodyRevision();
        const string input = "[\"alpha\",\"beta\",\"gamma\"]";
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var events = new List<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var result = await new WorkflowRunner()
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record);

        Assert.False(result.Failed);
        Assert.Equal("alpha;beta;gamma", result.Output);
        AssertPersistedSequence(runStore, events, "completed");
        foreach (var (item, index) in new[] { ("alpha", 0), ("beta", 1), ("gamma", 2) })
        {
            var scopeId = $"array-loop/{index}/call";
            var childEvents = events.Where(evt => evt.ScopeId == scopeId).ToArray();
            Assert.Single(childEvents, evt => evt.Kind == ExecutionEventKinds.SubworkflowStarted);
            Assert.Single(childEvents, evt => evt.Kind == ExecutionEventKinds.SubworkflowCompleted);
            Assert.Single(childEvents, evt => evt.Kind == ExecutionEventKinds.SubworkflowEvidence &&
                WorkflowCallLifecycleEvidence.TryRead(evt.Data, out var evidence) &&
                evidence!.Lifecycle == ExecutionEventKinds.SubworkflowStarted);
            Assert.Single(childEvents, evt => evt.Kind == ExecutionEventKinds.SubworkflowEvidence &&
                WorkflowCallLifecycleEvidence.TryRead(evt.Data, out var evidence) &&
                evidence!.Lifecycle == ExecutionEventKinds.SubworkflowCompleted);
            var childInput = Assert.Single(childEvents, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
                evt.NodeId == "input");
            using var packed = JsonDocument.Parse(childInput.Data!);
            Assert.Equal(item, packed.RootElement.GetProperty("value").GetString());
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
                evt.ScopeId == $"array-loop/{index}");
        }

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("completed", reopened.Status);
        Assert.True(WorkflowCallEvidence.TryReconstructPlayback(reopened.Events, out var calls));
        Assert.Equal(3, calls!.Calls.Count);
        Assert.All(calls.Calls, call => Assert.Equal("completed", call.State));
    }

