        Assert.False(result.Failed);
        Assert.Equal(new[]
        {
            "continue-alpha", "{\"query\":\"continue-alpha\"}",
            "continue-beta", "{\"query\":\"continue-beta\"}"
        }, agents.Inputs);
        Assert.Contains("continue-alpha", result.Output, StringComparison.Ordinal);
        Assert.Contains("continue-beta", result.Output, StringComparison.Ordinal);
        Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
            evt.NodeId == "array-loop"));
        Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
            evt.NodeId == "array-loop"));
        Assert.Equal(4, events.Count(evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
            evt.NodeId == "loop"));
        Assert.Equal(4, events.Count(evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
            evt.NodeId == "loop"));
        var stoppedLoops = events.Where(evt => evt.Kind == ExecutionEventKinds.LoopStopped &&
            evt.NodeId == "loop").ToArray();
        var stoppedScopes = stoppedLoops.Select(evt => evt.ScopeId).ToArray();
        Assert.True(new[] { "array-loop/0/loop/2", "array-loop/1/loop/2" }.SequenceEqual(stoppedScopes),
            string.Join("\n", events.Where(evt => evt.Kind.StartsWith("loop.", StringComparison.Ordinal))
                .Select(evt => $"{evt.Kind} | {evt.NodeId} | {evt.ScopeId}")));
        foreach (var stoppedLoop in stoppedLoops)
        {
            using var stopReason = JsonDocument.Parse(stoppedLoop.Data!);
            Assert.Equal("maximum-iterations", stopReason.RootElement.GetProperty("reason").GetString());
        }
        AssertPersistedSequence(runStore, events, "completed");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        var playback = await RenderLoopActivations(reopened.Events, reopened.Status);
        Assert.Contains("Loop activations (6)", playback, StringComparison.Ordinal);
        Assert.Contains("loop · Iteration 2 · Completed", playback, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_ApprovesExactMcpActionPerArrayItem(bool sqlite)
    {
        const string input = "[\"search-alpha\",\"search-beta\"]";
        const string bindingId = "proof.array-approved-search";
        var revision = WorkflowRevision.Create(ApprovedMcpItemBodyDefinition(bindingId),
            "production-body-array-approval-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var events = new List<ExecutionEvent>();
        var gate = new CapturingIterationApprovalGate();
        var tools = new EchoToolBroker(recordToolDispatchEvents: true);

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var result = await new WorkflowRunner(tools: tools)
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record, itemParameterId: "item", arrayElementType: WorkflowDataTypes.String, gate: gate);

        Assert.False(result.Failed);
        Assert.Equal(["search-alpha", "search-beta"], tools.Queries);
        var actions = gate.Actions;
        Assert.Equal(2, actions.Length);
        Assert.Equal(new[] { "array-loop/0", "array-loop/1" }, actions.Select(action =>
            events.Single(evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
                evt.NodeId == action.ApprovalNodeId && evt.InvocationId == action.ApprovalInvocationId).ScopeId)
            .ToArray());
        Assert.Equal(new[] { "search-alpha", "search-beta" }, actions.Select(action =>
        {
            using var arguments = JsonDocument.Parse(action.Input);
            return arguments.RootElement.GetProperty("query").GetString();
        }));
        Assert.Equal(2, actions.Select(action => action.TargetInvocationId).Distinct().Count());
        Assert.All(actions.Select((action, index) => (action, index)), entry =>
        {
            var (action, index) = entry;
            Assert.Equal(runStore.RunId, action.RunId);
            Assert.Equal(revision.RevisionId, action.RevisionId);
            Assert.Equal("approval", action.ApprovalNodeId);
            Assert.Equal("tool", action.TargetNodeId);
            var permit = gate.Permits[index];
            Assert.NotEqual(Guid.Empty, permit.RequestId);
            Assert.Equal(action.ComputeHash(), permit.ActionHash);
            Assert.Equal(action.TargetInvocationId, permit.TargetInvocationId);
            var authorized = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolAuthorized &&
                evt.NodeId == action.TargetNodeId && evt.InvocationId == action.TargetInvocationId);
            Assert.Equal($"array-loop/{index}", authorized.ScopeId);
        });
        AssertPersistedSequence(runStore, events, "completed");
        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        var playback = await RenderPlayback(reopened);
        Assert.Contains("Latest run status: completed", playback, StringComparison.Ordinal);
        Assert.Contains("search-alpha", playback, StringComparison.Ordinal);
        Assert.Contains("search-beta", playback, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_CancellationWhileAwaitingItemApprovalStopsRun(bool sqlite)
    {
        const string input = "[\"search-alpha\",\"must-not-run\"]";
        var revision = WorkflowRevision.Create(ApprovedMcpItemBodyDefinition("proof.array-approved-search"),
            "production-body-array-approval-cancellation-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var events = new List<ExecutionEvent>();
        var gate = new BlockingIterationApprovalGate();
        var tools = new EchoToolBroker(recordToolDispatchEvents: true);
        using var cancellation = new CancellationTokenSource();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var run = new WorkflowRunner(tools: tools)
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record, cancellation.Token, itemParameterId: "item", arrayElementType: WorkflowDataTypes.String,
                gate: gate);
        var requestedAction = await gate.Requested.Task.WaitAsync(TimeSpan.FromSeconds(5));
        cancellation.Cancel();
        var result = await run.WaitAsync(TimeSpan.FromSeconds(5));

        Assert.True(result.Cancelled);
        Assert.Equal("search-alpha", JsonDocument.Parse(requestedAction.Input).RootElement
            .GetProperty("query").GetString());
        Assert.Empty(tools.Queries);
        Assert.DoesNotContain(events, evt => evt.ScopeId == "array-loop/1");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeCancelled && evt.NodeId == "approval" &&
            evt.ScopeId == "array-loop/0");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.ToolAuthorized);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Cancelled && evt.NodeId is null);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.Completed && evt.NodeId is null);
        AssertPersistedSequence(runStore, events, "cancelled");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("cancelled", reopened.Status);
        var playback = await RenderPlayback(reopened);
        Assert.Contains("Latest run status: cancelled", playback, StringComparison.Ordinal);
        Assert.Contains("Iteration 1 · Cancelled", playback, StringComparison.Ordinal);
    }

