    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_ComposesEveryTypedArrayOperationPerItem(bool sqlite)
    {
        const string input = "[\"alpha\",\"beta\"]";
        var revision = WorkflowRevision.Create(TypedArrayOperationsItemBodyDefinition(),
            "production-body-array-operations-per-item-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var events = new List<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var result = await new WorkflowRunner().ExecuteProductionBodyActivationSequenceProofAsync(
            runStore.RunId, revision, input, "index", null, Record,
            itemParameterId: "item", arrayElementType: WorkflowDataTypes.String);

        Assert.False(result.Failed);
        Assert.Equal("[\"alpha\",\"alpha\",\"tail\"];[\"beta\",\"beta\",\"tail\"]", result.Output);
        AssertPersistedSequence(runStore, events, "completed");

        foreach (var (scope, item) in new[] { ("array-loop/0", "alpha"), ("array-loop/1", "beta") })
        {
            var scopedEvents = events.Where(evt => evt.ScopeId == scope).ToArray();
            foreach (var connectionId in new[]
            {
                "data:append-array", "data:append-item", "data:length-array", "data:length-index",
                "data:index-offset", "data:get-array", "data:get-index", "data:insert-array",
                "data:insert-index", "data:insert-item", "data:replace-array", "data:replace-index",
                "data:replace-item", "data:remove-array", "data:remove-index", "data:concat-left",
                "data:concat-right", "data:set-value", "data:output-value"
            })
                Assert.Contains(scopedEvents, evt => evt.Kind == ExecutionEventKinds.DataEvaluated &&
                    evt.ConnectionId == connectionId);

            var write = Assert.Single(scopedEvents, evt => evt.Kind == ExecutionEventKinds.VariableWritten);
            using var writeData = JsonDocument.Parse(write.Data!);
            Assert.Equal("[\"seed\"]", writeData.RootElement.GetProperty("previousValue").GetRawText());
            Assert.Equal($"[\"{item}\",\"{item}\",\"tail\"]",
                writeData.RootElement.GetProperty("value").GetRawText());
        }

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        var playback = await RenderPlayback(reopened);
        Assert.Contains("Latest run status: completed", playback, StringComparison.Ordinal);
        Assert.Contains("Array concatenate", playback, StringComparison.Ordinal);
    }

