            var scopeId = $"array-loop/{index}";
            var scoped = events.Where(evt => evt.ScopeId == scopeId).ToArray();
            var evaluated = Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.DataEvaluated &&
                evt.NodeId == "input" && evt.ConnectionId == "data:input-tool-left");
            using (var argument = JsonDocument.Parse(evaluated.Data!))
            {
                Assert.Equal("tool-left", argument.RootElement.GetProperty("activatedByNodeId").GetString());
                Assert.Equal("redacted", argument.RootElement.GetProperty("payloadState").GetString());
                Assert.True(argument.RootElement.GetProperty("valueCharacters").GetInt32() > 0);
            }

            var toolStarted = Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
                evt.NodeId == "tool-left");
            using (var startedPayload = JsonDocument.Parse(toolStarted.Data!))
            {
                Assert.Equal("redacted", startedPayload.RootElement.GetProperty("payloadState").GetString());
                Assert.True(startedPayload.RootElement.GetProperty("valueCharacters").GetInt32() > 0);
            }
            var authorized = Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.ToolAuthorized &&
                evt.NodeId == "tool-left" && evt.InvocationId == toolStarted.InvocationId);
            var toolCompleted = Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.ToolCompleted &&
                evt.NodeId == "tool-left" && evt.InvocationId == toolStarted.InvocationId);
            using (var authorization = JsonDocument.Parse(authorized.Data!))
            {
                Assert.Equal("redacted", authorization.RootElement.GetProperty("payloadState").GetString());
                Assert.True(authorization.RootElement.GetProperty("inputCharacters").GetInt32() > 0);
            }
            using (var toolOutput = JsonDocument.Parse(toolCompleted.Data!))
            {
                Assert.Equal("redacted", toolOutput.RootElement.GetProperty("payloadState").GetString());
                Assert.True(toolOutput.RootElement.GetProperty("outputCharacters").GetInt32() > 0);
            }

            var agentStarted = Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
                evt.NodeId == "agent-right");
            Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
                evt.NodeId == "agent-right" && evt.InvocationId == agentStarted.InvocationId);
            var join = Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
                evt.NodeId == "join");
            using var joined = JsonDocument.Parse(join.Data!);
            Assert.Equal(item.ToUpperInvariant(), joined.RootElement.GetProperty("left").GetString());
            using var rightOutput = JsonDocument.Parse(joined.RootElement.GetProperty("right").GetString()!);
            Assert.Equal($"{item}-agent-right", rightOutput.RootElement.GetProperty("query").GetString());
            using var returned = JsonDocument.Parse(returnedItems[index]);
            Assert.Equal(item.ToUpperInvariant(), returned.RootElement.GetProperty("left").GetString());
            using var returnedRight = JsonDocument.Parse(returned.RootElement.GetProperty("right").GetString()!);
            Assert.Equal($"{item}-agent-right", returnedRight.RootElement.GetProperty("query").GetString());
            Assert.Equal(2, scoped.Count(evt => evt.Kind == ExecutionEventKinds.ParallelJoinProgress &&
                evt.NodeId == "join"));
        }

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        var playback = await RenderPlayback(reopened);
        Assert.Equal(2, CountOccurrences(playback, "Parallel join join · completed"));

        static int CountOccurrences(string text, string value) =>
            (text.Length - text.Replace(value, string.Empty, StringComparison.Ordinal).Length) / value.Length;
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_MixedAgentMcpFailureCancelsSiblingAndStopsLaterItems(
        bool sqlite)
    {
        const string input = "[\"first\",\"must-not-run\"]";
        var agents = new BlockingAgentExecutor("first");
        var definition = ParallelMcpDefinition() with
        {
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        var nodes = definition.Nodes.Remove("tool-review")
            .Add("agent-right", ParallelBodyDefinition().Nodes["agent-right"]);
        var connections = definition.Connections.Remove("input-tool-review")
            .Add("input-right", new(new("input", "out"), new("agent-right", "in"), "data"));
        var execution = definition.ExecutionConnections!
            .Remove("right-tool")
            .Remove("tool-review-join")
            .Add("right-agent", Edge("anchor-right", "then", "agent-right", "execute"))
            .Add("agent-right-join", Edge("agent-right", "out", "join", "branch.right"));
        definition = definition with
        {
            Nodes = nodes,
            Connections = connections,
            ExecutionConnections = execution
        };
        WorkflowValidator.ThrowIfInvalid(definition);
        var revision = WorkflowRevision.Create(definition,
            "production-body-mixed-agent-mcp-failure-per-item-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var broker = new ParallelMcpBroker(failNode: "tool-research", recordReservationIds: true,
            expectedCallCount: 1, waitBeforeOutcome: agents.Started.Task);
        var events = new List<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var result = await new WorkflowRunner(broker, agents)
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record, runBudget: StructuredRunBudget(maximumToolDispatches: 2))
            .WaitAsync(TimeSpan.FromSeconds(30));

        Assert.True(result.Failed);
        Assert.False(result.Cancelled);
        Assert.False(result.OutcomeUnknown);
        Assert.Equal(["first"], agents.Inputs);
        var toolStarted = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
            evt.NodeId == "tool-research" && evt.ScopeId == "array-loop/0");
        var toolFailed = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolFailed &&
            evt.NodeId == "tool-research" && evt.ScopeId == "array-loop/0");
        Assert.Equal(toolStarted.InvocationId, toolFailed.InvocationId);
        var authorized = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolAuthorized &&
            evt.NodeId == "tool-research" && evt.ScopeId == "array-loop/0");
        using (var authorization = JsonDocument.Parse(authorized.Data!))
        using (var failure = JsonDocument.Parse(toolFailed.Data!))
        {
            Assert.Equal(authorization.RootElement.GetProperty("toolCallId").GetString(),
                failure.RootElement.GetProperty("toolCallId").GetString());
            Assert.Equal("tool.host_failure", failure.RootElement.GetProperty("failureCode").GetString());
        }

        var agentStarted = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
            evt.NodeId == "agent-right" && evt.ScopeId == "array-loop/0");
        var agentCancelled = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeCancelled &&
            evt.NodeId == "agent-right" && evt.ScopeId == "array-loop/0");
        Assert.Equal(agentStarted.InvocationId, agentCancelled.InvocationId);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
            evt.NodeId is "tool-research" or "agent-right" or "join");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.ParallelJoinProgress &&
            evt.NodeId == "join");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted);
        Assert.DoesNotContain(events, evt => evt.ScopeId == "array-loop/1");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
        AssertPersistedSequence(runStore, events, "failed");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        var playback = await RenderPlayback(reopened);
        Assert.Contains("Latest run status: failed", playback, StringComparison.Ordinal);
        Assert.DoesNotContain("Parallel join join · completed", playback, StringComparison.Ordinal);
    }

