            ExecutionConnections = executionConnections
        };
        WorkflowValidator.ThrowIfInvalid(definition);
        var revision = WorkflowRevision.Create(definition,
            "production-body-mixed-agent-mcp-cancellation-per-item-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        using var cancellation = new CancellationTokenSource();
        var broker = new ParallelMcpBroker(holdUntilCancelled: true, recordReservationIds: true,
            expectedCallCount: 1, waitBeforeOutcome: agents.Started.Task, preserveHostCancellation: true);
        var events = new List<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var execution = new WorkflowRunner(broker, agents)
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record, cancellation.Token, runBudget: StructuredRunBudget(maximumToolDispatches: 2));
        await agents.Started.Task.WaitAsync(TimeSpan.FromSeconds(5));
        await broker.DispatchStarted.WaitAsync(TimeSpan.FromSeconds(5));
        cancellation.Cancel();
        var result = await execution.WaitAsync(TimeSpan.FromSeconds(10));

        Assert.True(result.Cancelled);
        Assert.False(result.Failed);
        Assert.False(result.OutcomeUnknown);
        Assert.Equal(["first"], agents.Inputs);
