    public async Task ProductionBodyActivationCoordinator_ParallelMcpFailureSuppressesJoinAndLaterItems(bool sqlite)
    {
        const string input = "[\"first\",\"must-not-run\"]";
        var definition = ParallelMcpDefinition() with
