        var definition = ParallelMcpDefinition() with
        {
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        var revision = WorkflowRevision.Create(definition,
            "production-body-parallel-mcp-mixed-host-cancellation-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var broker = new OrderedMixedOutcomeParallelMcpBroker(unknownFirst);
        using var cancellation = new CancellationTokenSource();
        var events = new List<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            if (evt.Kind == (unknownFirst ? ExecutionEventKinds.ToolUncertain : ExecutionEventKinds.ToolFailed))
                cancellation.Cancel();
            return ValueTask.CompletedTask;
        }

        var result = await new WorkflowRunner(broker)
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record, cancellation.Token, runBudget: StructuredRunBudget(maximumToolDispatches: 4))
            .WaitAsync(TimeSpan.FromSeconds(10));

        Assert.Equal(2, broker.Authorizations);
        var uncertain = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolUncertain &&
            evt.NodeId == "tool-review");
        var failed = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolFailed &&
            evt.NodeId == "tool-research");
        Assert.Equal(unknownFirst, uncertain.Sequence < failed.Sequence);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "join");
        Assert.DoesNotContain(events, evt => evt.ScopeId == "array-loop/1");

        foreach (var nodeId in new[] { "tool-research", "tool-review" })
        {
            var authorized = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolAuthorized &&
                evt.NodeId == nodeId);
            var outcome = Assert.Single(events, evt => evt.Kind is
                ExecutionEventKinds.ToolFailed or ExecutionEventKinds.ToolUncertain && evt.NodeId == nodeId);
            using var authorizedPayload = JsonDocument.Parse(authorized.Data!);
            using var outcomePayload = JsonDocument.Parse(outcome.Data!);
            Assert.Equal(authorizedPayload.RootElement.GetProperty("toolCallId").GetString(),
                outcomePayload.RootElement.GetProperty("toolCallId").GetString());
        }

        Assert.True(result.Cancelled || result.Failed || result.OutcomeUnknown);
        var snapshot = runStore.Store.Get(runStore.RunId)!;
        Assert.Contains(snapshot.Status, new[] { "cancelled", "failed", "outcome-unknown" });
        AssertPersistedSequence(runStore, events, snapshot.Status);
        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(snapshot.Status, reopened.Status);
        Assert.Equal(events, reopened.Events);
        AssertMixedToolReconciliation(reopened, "tool-research", "tool-review");
        var playback = await RenderPlayback(reopened);
        Assert.Contains($"Latest run status: {snapshot.Status}", playback, StringComparison.Ordinal);
        Assert.Contains(ExecutionEventKinds.ToolFailed, playback, StringComparison.Ordinal);
        Assert.Contains(ExecutionEventKinds.ToolUncertain, playback, StringComparison.Ordinal);
        Assert.DoesNotContain("Parallel join join · completed", playback, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(true, false)]
    [InlineData(false, true)]
    [InlineData(true, true)]
    public async Task StructuredSequenceBreakDrainsMixedMcpOutcomes(bool sqlite, bool unknownFirst)
    {
        var revision = WorkflowRevision.CreateProofOnly(SequenceMixedMcpBreakDefinition(),
            "sequence-break-mixed-mcp-outcome-proof");
        var projection = revision.Definition with
        {
            Nodes = revision.Definition.Nodes.SetItem("quality-tool",
                new(NodeTypes.Agent, "1.0.0", Agent: new("proof.break", null, "Private Break projection", [])))
        };
        Assert.Empty(WorkflowValidator.Validate(projection));
        using var runStore = new ProofRunStore(revision, "[\"first\",\"must-not-run\"]", sqlite);
        var broker = new OrderedMixedOutcomeParallelMcpBroker(unknownFirst, holdOutcomes: true,
            researchNodeId: "inventory-tool", reviewNodeId: "architecture-tool");
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var breakCompleted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var qualitySkipped = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);

        ValueTask Record(ExecutionEvent evt)
        {
            recorder.Append(evt);
            if (evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "quality-tool")
                breakCompleted.TrySetResult();
            if (evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
                SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "archive")
                qualitySkipped.TrySetResult();
            return ValueTask.CompletedTask;
        }

        var execution = new WorkflowRunner(tools: broker).ExecuteStructuredActivationSequenceProofAsync(
            runStore.RunId, revision, "[\"first\",\"must-not-run\"]", "index", null, Record);
        try
        {
            await Task.WhenAll(broker.BothAuthorized, breakCompleted.Task, qualitySkipped.Task)
                .WaitAsync(TimeSpan.FromSeconds(10));
            Assert.False(execution.IsCompleted,
                "The Sequence must drain already-authorized MCP work before settling its failed output.");
        }
        catch (TimeoutException exception)
        {
            var trace = string.Join(" | ", recorder.Snapshot().Select(evt =>
                $"{evt.Sequence}:{evt.NodeId ?? "root"}:{evt.Kind}:{evt.Data}"));
            throw new Xunit.Sdk.XunitException(
                $"Sequence Break mixed-outcome gate timed out (authorizations={broker.Authorizations}). {trace} {exception.Message}");
        }
        finally
        {
            broker.ReleaseOutcomes.TrySetResult();
        }

        var executionError = await Xunit.Record.ExceptionAsync(() => execution.WaitAsync(TimeSpan.FromSeconds(10)));
        Assert.IsType<ToolInvocationException>(executionError);
        var events = recorder.Snapshot();
        Assert.Equal(2, broker.Authorizations);
        var uncertain = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolUncertain &&
            evt.NodeId == "architecture-tool");
        var failed = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolFailed &&
            evt.NodeId == "inventory-tool");
        Assert.Equal(unknownFirst, uncertain.Sequence < failed.Sequence);
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "quality-tool");
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
            SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "archive");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputDispatched &&
            SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "archive");
        Assert.DoesNotContain(events, evt => evt.ScopeId == "array-loop/1");
        foreach (var nodeId in new[] { "inventory-tool", "architecture-tool" })
        {
            var authorized = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolAuthorized &&
                evt.NodeId == nodeId);
            var outcome = Assert.Single(events, evt => evt.Kind is
                ExecutionEventKinds.ToolFailed or ExecutionEventKinds.ToolUncertain && evt.NodeId == nodeId);
            using var authorizedPayload = JsonDocument.Parse(authorized.Data!);
            using var outcomePayload = JsonDocument.Parse(outcome.Data!);
            Assert.Equal(authorizedPayload.RootElement.GetProperty("toolCallId").GetString(),
                outcomePayload.RootElement.GetProperty("toolCallId").GetString());
        }

        var snapshot = runStore.Store.Get(runStore.RunId)!;
        Assert.Contains(snapshot.Status, new[] { "failed", "outcome-unknown" });
        AssertPersistedSequence(runStore, events, snapshot.Status);
        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(snapshot.Status, reopened.Status);
        Assert.Equal(events, reopened.Events);
        AssertMixedToolReconciliation(reopened, "inventory-tool", "architecture-tool");
        var sequenceEvents = reopened.Events.Where(evt => SequenceEvidence.IsLifecycleEvent(evt.Kind)).ToArray();
        Assert.True(SequenceEvidence.TryReconstructPlayback(sequenceEvents, out var sequencePlayback));
        Assert.Equal("array-loop/0", sequencePlayback!.ScopeId);
        Assert.Equal("failed", sequencePlayback.Status);
        Assert.Contains(sequencePlayback.Outputs, output => output.State == "failed");
        var playback = await RenderPlayback(reopened);
        Assert.Contains(ExecutionEventKinds.ToolFailed, playback, StringComparison.Ordinal);
        Assert.Contains(ExecutionEventKinds.ToolUncertain, playback, StringComparison.Ordinal);
        Assert.DoesNotContain("Latest run status: completed", playback, StringComparison.Ordinal);
    }

    private static RunReconciliation AssertMixedToolReconciliation(RunSnapshot snapshot,
        params string[] expectedNodeIds)
    {
        var report = WorkflowRunReconciliation.Assess(snapshot, null);
        Assert.Equal(snapshot.Status, report.Status);
        Assert.Equal(RunRecoveryDisposition.UnresolvedWork, report.Disposition);
        Assert.Equal(expectedNodeIds.Length, report.TotalUnresolvedWork);
        Assert.Equal(expectedNodeIds.Length, report.UnresolvedWork.Length);
        Assert.False(report.HasIncompleteCorrelation);
        Assert.Equal(expectedNodeIds.Order(StringComparer.Ordinal),
            report.UnresolvedWork.Select(item => item.NodeId).Order(StringComparer.Ordinal));
        Assert.All(report.UnresolvedWork, item =>
        {
            Assert.Equal(UnresolvedWorkKind.Tool, item.Kind);
            Assert.Equal(UnresolvedWorkState.OutcomeUnknown, item.State);
            Assert.NotNull(item.CallId);
        });
        return report;
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_HostCancellationUnsettlesParallelProductionMcpCalls(bool sqlite)
    {
        const string input = "[\"first\",\"must-not-run\"]";
        var registrations = CreateDemoMcpRegistrations();
        var discovery = new McpToolBroker(registrations, new DemoToolPolicy());
        var binding = Assert.Single(await discovery.ListBindingsAsync(), item => item.BindingId == "demo.slow");
        var configuredTool = new ToolBindingRequest(binding.BindingId, binding.ContractHash)
        {
            DescriptionHash = binding.DescriptionHash
        };
        var definition = ParallelMcpDefinition() with
        {
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        var nodes = definition.Nodes;
        foreach (var nodeId in new[] { "tool-research", "tool-review" })
            nodes = nodes.SetItem(nodeId, nodes[nodeId] with
            {
                Tool = configuredTool,
                McpArgumentsJson = "{}"
            });
        definition = definition with { Nodes = nodes };
        WorkflowValidator.ThrowIfInvalid(definition);
        var revision = WorkflowRevision.Create(definition,
            "production-body-parallel-real-mcp-host-cancellation-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var broker = CreateSynchronizedDemoMcpBroker(registrations, expectedConnections: 2);
        using var cancellation = new CancellationTokenSource();
        var events = new List<ExecutionEvent>();
        var authorizedCalls = 0;

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            if (evt.Kind == ExecutionEventKinds.ToolAuthorized &&
                Interlocked.Increment(ref authorizedCalls) == 2)
                cancellation.Cancel();
            return ValueTask.CompletedTask;
        }

        var result = await new WorkflowRunner(broker)
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record, cancellation.Token, runBudget: StructuredRunBudget(maximumToolDispatches: 4))
            .WaitAsync(TimeSpan.FromSeconds(20));

        Assert.True(result.Cancelled);
        Assert.False(result.Failed);
        Assert.False(result.OutcomeUnknown);
        Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.ToolAuthorized));
        Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.ToolUncertain));
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.ToolCompleted);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "join");
        Assert.DoesNotContain(events, evt => evt.ScopeId == "array-loop/1");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Cancelled && evt.NodeId is null);
        AssertPersistedSequence(runStore, events, "cancelled");

        foreach (var nodeId in new[] { "tool-research", "tool-review" })
        {
            var authorized = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolAuthorized &&
                evt.NodeId == nodeId);
            var uncertain = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolUncertain &&
                evt.NodeId == nodeId && evt.InvocationId == authorized.InvocationId);
            using var authorizationPayload = JsonDocument.Parse(authorized.Data!);
            using var uncertaintyPayload = JsonDocument.Parse(uncertain.Data!);
            Assert.Equal(authorizationPayload.RootElement.GetProperty("toolCallId").GetString(),
                uncertaintyPayload.RootElement.GetProperty("toolCallId").GetString());
        }

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal("cancelled", reopened.Status);
        Assert.Equal(events, reopened.Events);
        var playback = await RenderPlayback(reopened);
        Assert.Contains("Latest run status: cancelled", playback, StringComparison.Ordinal);
        Assert.Contains(ExecutionEventKinds.ToolUncertain, playback, StringComparison.Ordinal);
        Assert.DoesNotContain("Parallel join join · completed", playback, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_HostCancellationSettlesParallelAgents(bool sqlite)
    {
        const string input = "[\"first\",\"must-not-run\"]";
        var definition = ParallelBodyDefinition() with
        {
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        var revision = WorkflowRevision.Create(definition,
            "production-body-parallel-agent-host-cancellation-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        using var cancellation = new CancellationTokenSource();
        var agents = new TwoBranchBlockingAgentExecutor();
        var events = new List<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var execution = new WorkflowRunner(agents: agents)
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record, cancellation.Token);
        await agents.BothBranchesStarted.Task.WaitAsync(TimeSpan.FromSeconds(5));
        cancellation.Cancel();
        var result = await execution.WaitAsync(TimeSpan.FromSeconds(10));

        Assert.True(result.Cancelled);
        Assert.False(result.Failed);
        Assert.Equal(["agent-left", "agent-right"], events
            .Where(evt => evt.Kind == ExecutionEventKinds.NodeStarted && evt.ScopeId == "array-loop/0")
            .Where(evt => evt.NodeId is "agent-left" or "agent-right")
            .Select(evt => evt.NodeId).Order(StringComparer.Ordinal));
        foreach (var nodeId in new[] { "agent-left", "agent-right" })
        {
            var started = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
                evt.NodeId == nodeId && evt.ScopeId == "array-loop/0");
            var cancelled = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeCancelled &&
                evt.NodeId == nodeId && evt.ScopeId == "array-loop/0");
            Assert.Equal(started.InvocationId, cancelled.InvocationId);
        }

        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
            evt.NodeId is "agent-left" or "agent-right" or "join");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.ParallelJoinProgress &&
            evt.NodeId == "join");
        var iterationSettlement = Assert.Single(events, evt =>
            evt.Kind == ExecutionEventKinds.LoopIterationCompleted && evt.ScopeId == "array-loop/0");
        using (var settlement = JsonDocument.Parse(iterationSettlement.Data!))
            Assert.Equal("cancelled", settlement.RootElement.GetProperty("outcome").GetString());
        Assert.DoesNotContain(events, evt => evt.ScopeId == "array-loop/1");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Cancelled && evt.NodeId is null);
        Assert.DoesNotContain(events, evt => evt.NodeId is null && evt.Kind is
            (ExecutionEventKinds.Failed or ExecutionEventKinds.Completed));
        AssertPersistedSequence(runStore, events, "cancelled");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        var playback = await RenderPlayback(reopened);
        Assert.Contains("Latest run status: cancelled", playback, StringComparison.Ordinal);
        Assert.DoesNotContain("Parallel join join · completed", playback, StringComparison.Ordinal);
    }

