        Assert.DoesNotContain("Parallel join join · completed", playback, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false, false, false)]
    [InlineData(true, false, false)]
    [InlineData(false, true, false)]
    [InlineData(true, true, false)]
    [InlineData(false, false, true)]
    [InlineData(true, false, true)]
    [InlineData(false, true, true)]
    [InlineData(true, true, true)]
    public async Task ProductionBodyActivationCoordinator_ProductionMcpFailureCancelsSiblingAndPreservesEvidence(
        bool sqlite, bool classifyProtocolFailure, bool rejectSiblingUncertainty = false)
    {
        const string input = "[\"first\",\"must-not-run\"]";
        var registrations = CreateDemoMcpRegistrations("demo.protocol-failure")
            .Concat(CreateDemoMcpRegistrations("demo.slow"))
            .Select(registration => classifyProtocolFailure && registration.BindingId == "demo.protocol-failure"
                ? registration with
                {
                    AllowModelRecoveryAfterFailure = true,
                    IsDefinitiveToolFailure = exception => exception is ModelContextProtocol.McpProtocolException
                }
                : registration)
            .ToArray();
        var discovery = new McpToolBroker(registrations, new DemoToolPolicy());
        var bindings = (await discovery.ListBindingsAsync()).ToDictionary(binding => binding.BindingId);
        var definition = ParallelMcpDefinition() with
        {
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        var nodes = definition.Nodes;
        nodes = nodes.SetItem("tool-research", nodes["tool-research"] with
        {
            Tool = new(bindings["demo.protocol-failure"].BindingId, bindings["demo.protocol-failure"].ContractHash)
            {
                DescriptionHash = bindings["demo.protocol-failure"].DescriptionHash
            },
            McpArgumentsJson = "{}"
        });
        nodes = nodes.SetItem("tool-review", nodes["tool-review"] with
        {
            Tool = new(bindings["demo.slow"].BindingId, bindings["demo.slow"].ContractHash)
            {
                DescriptionHash = bindings["demo.slow"].DescriptionHash
            },
            McpArgumentsJson = "{}"
        });
        definition = definition with { Nodes = nodes };
        WorkflowValidator.ThrowIfInvalid(definition);
        var revision = WorkflowRevision.Create(definition,
            "production-body-parallel-real-mcp-failure-cancels-sibling-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite,
            rejectedAppendPredicate: evt => rejectSiblingUncertainty &&
                evt.Kind == ExecutionEventKinds.ToolUncertain && evt.NodeId == "tool-review");
        var broker = CreateSynchronizedDemoMcpBroker(registrations, expectedConnections: 2);
        var events = new List<ExecutionEvent>();
        var appendAttempts = new ConcurrentQueue<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            appendAttempts.Enqueue(evt);
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var result = await new WorkflowRunner(broker)
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record, runBudget: StructuredRunBudget(maximumToolDispatches: 4))
            .WaitAsync(TimeSpan.FromSeconds(20));

        Assert.Equal(!classifyProtocolFailure, result.OutcomeUnknown);
        Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.ToolAuthorized));
        Assert.Equal((classifyProtocolFailure ? 0 : 1) + (rejectSiblingUncertainty ? 0 : 1),
            events.Count(evt => evt.Kind == ExecutionEventKinds.ToolUncertain));
        Assert.Equal(classifyProtocolFailure ? 1 : 0,
            events.Count(evt => evt.Kind == ExecutionEventKinds.ToolFailed));
        if (classifyProtocolFailure)
        {
            var classifiedFailure = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolFailed &&
                evt.NodeId == "tool-research");
            using var failurePayload = JsonDocument.Parse(classifiedFailure.Data!);
            Assert.Equal("host.classified_failure",
                failurePayload.RootElement.GetProperty("failureCode").GetString());
            Assert.Equal(ToolInvocationFailureDisposition.RecoverableFeedback.ToString(),
                failurePayload.RootElement.GetProperty("disposition").GetString());
        }
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.ToolCompleted);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "join");
        if (classifyProtocolFailure)
            Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted);
        else
        {
            var iterationCompleted = Assert.Single(events,
                evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted);
            using var iterationOutcome = JsonDocument.Parse(iterationCompleted.Data!);
            Assert.Equal("outcome-unknown", iterationOutcome.RootElement.GetProperty("outcome").GetString());
        }
        Assert.DoesNotContain(events, evt => evt.ScopeId == "array-loop/1");
        Assert.Single(events, evt => evt.Kind == (classifyProtocolFailure
            ? ExecutionEventKinds.Failed
            : ExecutionEventKinds.OutcomeUnknown) && evt.NodeId is null);
        var expectedStatus = classifyProtocolFailure ? "failed" : "outcome-unknown";
        AssertPersistedSequence(runStore, events, expectedStatus);

        foreach (var nodeId in new[] { "tool-research", "tool-review" })
        {
            var started = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
                evt.NodeId == nodeId);
            var authorized = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolAuthorized &&
                evt.NodeId == nodeId && evt.InvocationId == started.InvocationId);
            using var authorizationPayload = JsonDocument.Parse(authorized.Data!);
            var expectedToolEvent = nodeId == "tool-research"
                ? classifyProtocolFailure ? ExecutionEventKinds.ToolFailed : ExecutionEventKinds.ToolUncertain
                : ExecutionEventKinds.ToolUncertain;
            var matchingToolEvents = events.Where(evt => evt.Kind == expectedToolEvent && evt.NodeId == nodeId &&
                evt.InvocationId == started.InvocationId).ToArray();
            if (nodeId == "tool-review" && rejectSiblingUncertainty)
            {
                Assert.Empty(matchingToolEvents);
                var rejectedAttempt = Assert.Single(appendAttempts, evt => evt.Kind == ExecutionEventKinds.ToolUncertain &&
                    evt.NodeId == nodeId && evt.InvocationId == started.InvocationId);
                using var rejectedPayload = JsonDocument.Parse(rejectedAttempt.Data!);
                Assert.Equal(authorizationPayload.RootElement.GetProperty("toolCallId").GetString(),
                    rejectedPayload.RootElement.GetProperty("toolCallId").GetString());
            }
            else
            {
                var terminalToolEvent = Assert.Single(matchingToolEvents);
                using var terminalPayload = JsonDocument.Parse(terminalToolEvent.Data!);
                Assert.Equal(authorizationPayload.RootElement.GetProperty("toolCallId").GetString(),
                    terminalPayload.RootElement.GetProperty("toolCallId").GetString());
            }
        }

        var failedCallOutcome = Assert.Single(events, evt => evt.Kind == (classifyProtocolFailure
                ? ExecutionEventKinds.ToolFailed
                : ExecutionEventKinds.ToolUncertain) && evt.NodeId == "tool-research");
        var cancelledSiblingUncertainty = appendAttempts.Single(evt => evt.Kind == ExecutionEventKinds.ToolUncertain &&
            evt.NodeId == "tool-review");
        Assert.True(failedCallOutcome.Sequence < cancelledSiblingUncertainty.Sequence);
        if (rejectSiblingUncertainty)
            Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeCancelled &&
                evt.NodeId == "tool-review");
        else
            Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.NodeCancelled && evt.NodeId == "tool-review");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(expectedStatus, reopened.Status);
        Assert.Equal(events, reopened.Events);
        var playback = await RenderPlayback(reopened);
        Assert.Contains($"Latest run status: {expectedStatus}", playback, StringComparison.Ordinal);
        if (events.Any(evt => evt.Kind == ExecutionEventKinds.ToolUncertain))
        {
            Assert.Contains(ExecutionEventKinds.ToolUncertain, playback, StringComparison.Ordinal);
            Assert.Contains("MCP outcome is unknown:", playback, StringComparison.Ordinal);
        }
        else
        {
            Assert.Contains(ExecutionEventKinds.ToolAuthorized, playback, StringComparison.Ordinal);
            Assert.DoesNotContain(ExecutionEventKinds.ToolUncertain, playback, StringComparison.Ordinal);
            Assert.Contains("An MCP call was authorized, but no outcome event was recorded.", playback,
                StringComparison.Ordinal);
            Assert.Contains("Its external effect may be unknown.", playback, StringComparison.Ordinal);
            Assert.DoesNotContain("Execution failed without a recorded detail.", playback, StringComparison.Ordinal);
        }
        if (classifyProtocolFailure)
            Assert.Contains("MCP call failed:", playback, StringComparison.Ordinal);
        Assert.DoesNotContain("Parallel join join · completed", playback, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyActivationCoordinator_SequenceFailureCancelsSiblingAndStopsLaterItems(bool sqlite)
    {
        var definition = SequenceBodyDefinition() with
        {
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        var revision = WorkflowRevision.Create(definition,
            "production-body-sequence-failure-proof");
        const string input = "[\"first\",\"must-not-run\"]";
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var tools = new FailSequenceOutputToolBroker("proof.inventory", "proof.architecture");
        var events = new List<ExecutionEvent>();

        ValueTask Record(ExecutionEvent evt)
        {
            runStore.Store.Append(runStore.RunId, evt.Sequence - 1, [evt]);
            events.Add(evt);
            return ValueTask.CompletedTask;
        }

        var outcome = await new WorkflowRunner(tools)
            .ExecuteProductionBodyActivationSequenceProofAsync(runStore.RunId, revision, input, "index", null,
                Record, runBudget: StructuredRunBudget(maximumToolDispatches: 4))
            .WaitAsync(TimeSpan.FromSeconds(10));

        Assert.True(outcome.Failed);
        Assert.False(outcome.OutcomeUnknown);
        Assert.True(tools.FailingOutputReachedSibling);
        Assert.True(tools.SiblingObservedCancellation);
        var scoped = events.Where(evt => evt.ScopeId == "array-loop/0").ToArray();
        Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.SequenceStarted);
        Assert.Equal(2, scoped.Count(evt => evt.Kind == ExecutionEventKinds.SequenceOutputDispatched));
        Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.SequenceOutputFailed);
        Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.SequenceOutputCancelled);
        Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.SequenceFailed);
        Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.ToolUncertain);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
            evt.ScopeId == "array-loop/0");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeFailed &&
            evt.NodeId == "array-loop");
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.NodeFailed &&
            revision.Definition.Nodes.ContainsKey(evt.NodeId!));
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
            evt.ScopeId == "array-loop/0");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
            evt.ScopeId == "array-loop/1");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.OutcomeUnknown && evt.NodeId is null);

        AssertPersistedSequence(runStore, events, "failed");
        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("failed", reopened.Status);
        Assert.True(reopened.IsTerminal);
        var playback = await RenderPlayback(reopened);
        Assert.Contains("Latest run status: failed", playback, StringComparison.Ordinal);
        Assert.Contains("Iteration 1 · Incomplete &#xB7; run ended", playback, StringComparison.Ordinal);
        Assert.DoesNotContain("Iteration 1 · Completed", playback, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyNestedBreak_StopsInnerLoopAndContinuesOuterLoop(bool sqlite)
    {
        var body = StructuredBreakProofDefinition();
        var definition = body with
        {
            Parameters = body.Parameters!
                .Add("outerIndex", new("Outer array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        var revision = WorkflowRevision.CreateProofOnly(definition,
            "production-body-nested-break-continuation-proof");
        using var runStore = new ProofRunStore(revision, "[\"outer-a\",\"outer-b\"]", sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);

        var result = await new WorkflowRunner().ExecuteProductionNestedBodyBreakSequenceProofAsync(
            runStore.RunId, revision, "[\"outer-a\",\"outer-b\"]",
            "[\"continue\",\"stop\",\"must-not-run\"]", "outerIndex", "index", null,
            evt =>
            {
                recorder.Append(evt);
                return ValueTask.CompletedTask;
            });

        Assert.False(result.Failed, string.Join("\n", recorder.Snapshot().Select(evt =>
            $"{evt.Sequence} {evt.Kind} {evt.NodeId} {evt.ScopeId} {evt.Data}")));
        Assert.False(result.Terminated);
        Assert.Equal("outer-a:continue:0;outer-b:continue:0", result.Output);
        var events = recorder.Snapshot();
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Started && evt.NodeId is null);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Completed && evt.NodeId is null);
        Assert.Equal(Enumerable.Range(1, events.Length).Select(sequence => (long)sequence),
            events.Select(evt => evt.Sequence));
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
            evt.NodeId == "outer-loop" && evt.ScopeId == "outer-loop/1");
        Assert.DoesNotContain(events, evt => evt.ScopeId is
            "outer-loop/0/inner-loop/2" or "outer-loop/1/inner-loop/2");

        foreach (var outerIndex in new[] { 0, 1 })
        {
            var scope = $"outer-loop/{outerIndex}/inner-loop/1";
            var bodyBreak = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
                evt.NodeId == "proof-break" && evt.ScopeId == scope);
            using var requestData = JsonDocument.Parse(bodyBreak.Data!);
            var sourceFrameId = requestData.RootElement.GetProperty("sourceFrameId").GetGuid();
            Assert.Equal(scope, requestData.RootElement.GetProperty("scopeId").GetString());
            var outerScope = $"outer-loop/{outerIndex}";
            var outerStarted = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
                evt.NodeId == "outer-loop" && evt.ScopeId == outerScope);
            var innerStarted = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
                evt.NodeId == "inner-loop" && evt.ScopeId == scope);
            var previousIteration = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
                evt.NodeId == "inner-loop" && evt.ScopeId == $"{outerScope}/inner-loop/0");
            Assert.Equal(sourceFrameId, innerStarted.InvocationId);
            var outerFrame = new WorkflowRunner.StructuredActivationFrame(outerStarted.InvocationId!.Value,
                null, "outer-loop", outerIndex, outerIndex == 0 ? "outer-a" : "outer-b",
                ImmutableSortedDictionary<string, string>.Empty);
            var sourceFrame = new WorkflowRunner.StructuredActivationFrame(sourceFrameId, outerFrame,
                "inner-loop", 1, "stop", ImmutableSortedDictionary<string, string>.Empty);
            var request = new WorkflowRunner.StructuredActivationBreakRequest(
                requestData.RootElement.GetProperty("sourceNodeId").GetString()!, sourceFrameId, scope);
            var allowedSources = new HashSet<string>(["proof-break"], StringComparer.Ordinal);
            var accepted = WorkflowRunner.ConsumeProductionBodyBreakRequestProof(sourceFrame, request,
                allowedSources);
            Assert.Equal(sourceFrameId, accepted.TargetFrameId);

            Assert.Throws<InvalidOperationException>(() =>
                WorkflowRunner.ConsumeProductionBodyBreakRequestProof(sourceFrame,
                    request with { SourceFrameId = previousIteration.InvocationId!.Value }, allowedSources));
            Assert.Throws<InvalidOperationException>(() =>
                WorkflowRunner.ConsumeProductionBodyBreakRequestProof(sourceFrame,
                    request with { ScopeId = previousIteration.ScopeId! }, allowedSources));
            Assert.Throws<InvalidOperationException>(() =>
                WorkflowRunner.ConsumeProductionBodyBreakRequestProof(sourceFrame,
                    request with { SourceNodeId = "unadmitted-break" }, allowedSources));

            var otherOuterIndex = outerIndex == 0 ? 1 : 0;
            var otherOuterScope = $"outer-loop/{otherOuterIndex}";
            var otherBreakScope = $"{otherOuterScope}/inner-loop/1";
            var otherBreak = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
                evt.NodeId == "proof-break" && evt.ScopeId == otherBreakScope);
            using var otherBreakData = JsonDocument.Parse(otherBreak.Data!);
            var foreignRequest = new WorkflowRunner.StructuredActivationBreakRequest(
                otherBreakData.RootElement.GetProperty("sourceNodeId").GetString()!,
                otherBreakData.RootElement.GetProperty("sourceFrameId").GetGuid(), otherBreakScope);
            Assert.Throws<InvalidOperationException>(() =>
                WorkflowRunner.ConsumeProductionBodyBreakRequestProof(sourceFrame, foreignRequest, allowedSources));

            var consumed = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
                evt.NodeId == "inner-loop" && evt.ScopeId == scope);
            using var consumedData = JsonDocument.Parse(consumed.Data!);
            Assert.Equal(sourceFrameId,
                consumedData.RootElement.GetProperty("targetFrameId").GetGuid());
        }

        AssertPersistedSequence(runStore, events, "completed");
        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);

        var breakDispatch = Assert.Single(reopened.Events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
            evt.NodeId == "proof-break" && evt.ScopeId == "outer-loop/0/inner-loop/1");
        var beforeCoordinatorConsumption = reopened with
        {
            Events = reopened.Events.TakeWhile(evt => evt.Sequence <= breakDispatch.Sequence).ToImmutableArray()
        };
        var incompleteHtml = await RenderPlayback(beforeCoordinatorConsumption);
        Assert.Contains("Loop activations", incompleteHtml, StringComparison.Ordinal);
        Assert.Contains("In progress", incompleteHtml, StringComparison.Ordinal);
        Assert.DoesNotContain("· Break", incompleteHtml, StringComparison.Ordinal);

        var playbackHtml = await RenderPlayback(reopened);
        Assert.Contains("outer-loop/0/inner-loop/1", playbackHtml, StringComparison.Ordinal);
        Assert.Contains("· Break", playbackHtml, StringComparison.Ordinal);
        Assert.Contains("outer-loop/1", playbackHtml, StringComparison.Ordinal);
        Assert.Equal("completed", reopened.Status);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyCoordinator_ComposesTypedPinsAgentMcpAndNestedBreak(bool sqlite)
    {
        var revision = WorkflowRevision.CreateProofOnly(IntegratedNestedAgentMcpBreakDefinition(),
            "production-body-integrated-typed-pins-agent-mcp-break-proof");
        const string outerItems = "[\"outer-a\",\"outer-b\"]";
        const string innerItems = "[\"continue\",\"break\",\"must-not-run\"]";
        using var runStore = new ProofRunStore(revision, outerItems, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var agents = new EchoAgentExecutor();
        var tools = new EchoToolBroker(query => $"echo:{query}");

        var result = await new WorkflowRunner(tools, agents)
            .ExecuteProductionNestedBodyBreakSequenceProofAsync(runStore.RunId, revision,
                outerItems, innerItems, "outerIndex", "index", null,
                evt =>
                {
                    recorder.Append(evt);
                    return ValueTask.CompletedTask;
                }, itemParameterId: "item", runBudget: StructuredRunBudget(maximumToolDispatches: 4) with
                {
                    MaximumModelDispatches = 4
                });

        Assert.False(result.Failed, string.Join("\n", recorder.Snapshot().Select(evt =>
            $"{evt.Sequence} {evt.Kind} {evt.NodeId} {evt.ScopeId} {evt.Data}")));
        Assert.Equal("outer-a:echo:CONTINUE:0/0;outer-b:echo:CONTINUE:0/1", result.Output);
        Assert.Equal(["CONTINUE:0/0", "BREAK:1/0", "CONTINUE:0/1", "BREAK:1/1"], agents.Inputs);
        Assert.Equal(agents.Inputs, tools.Queries);

        var events = recorder.Snapshot();
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Started && evt.NodeId is null);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Completed && evt.NodeId is null);
        Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
            evt.NodeId == "proof-break"));
        Assert.DoesNotContain(events, evt => evt.ScopeId is "outer-loop/0/inner-loop/2" or
            "outer-loop/1/inner-loop/2");

        foreach (var (scopeId, item, index, outerIndex) in new[]
        {
            ("outer-loop/0/inner-loop/0", "continue", 0, 0),
            ("outer-loop/0/inner-loop/1", "break", 1, 0),
            ("outer-loop/1/inner-loop/0", "continue", 0, 1),
            ("outer-loop/1/inner-loop/1", "break", 1, 1)
        })
        {
            Assert.Equal(item, ReadStringEvaluation(events, scopeId, "data:item-pin-set"));
            Assert.Equal(index, ReadIntegerEvaluation(events, scopeId, "data:index-text-value"));
            Assert.Equal(outerIndex, ReadIntegerEvaluation(events, scopeId, "data:outer-index-text"));

            if (item == "break")
            {
                var requestEvent = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
                    evt.NodeId == "proof-break" && evt.ScopeId == scopeId);
                using var request = JsonDocument.Parse(requestEvent.Data!);
                Assert.Equal("proof-break", request.RootElement.GetProperty("sourceNodeId").GetString());
                Assert.False(request.RootElement.TryGetProperty("targetFrameId", out _));
                var activationStart = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
                    evt.NodeId == "inner-loop" && evt.ScopeId == scopeId);
                Assert.Equal(activationStart.InvocationId, request.RootElement.GetProperty("sourceFrameId").GetGuid());
                var consumed = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
                    evt.NodeId == "inner-loop" && evt.ScopeId == scopeId);
                using var consumedData = JsonDocument.Parse(consumed.Data!);
                Assert.Equal(activationStart.InvocationId, consumedData.RootElement.GetProperty("targetFrameId").GetGuid());
            }
        }

        AssertPersistedSequence(runStore, events, "completed");
        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("completed", reopened.Status);
        var playback = await RenderPlayback(reopened);
        Assert.Contains("· Break", playback, StringComparison.Ordinal);
        Assert.Contains("Latest run status: completed", playback, StringComparison.Ordinal);

        static string ReadStringEvaluation(IEnumerable<ExecutionEvent> events, string scopeId, string connectionId)
        {
            var evt = Assert.Single(events, item => item.Kind == ExecutionEventKinds.DataEvaluated &&
                item.ScopeId == scopeId && item.ConnectionId == connectionId);
            using var payload = JsonDocument.Parse(evt.Data!);
            return payload.RootElement.GetProperty("value").GetString()!;
        }

        static int ReadIntegerEvaluation(IEnumerable<ExecutionEvent> events, string scopeId, string connectionId)
        {
            var evt = Assert.Single(events, item => item.Kind == ExecutionEventKinds.DataEvaluated &&
                item.ScopeId == scopeId && item.ConnectionId == connectionId);
            using var payload = JsonDocument.Parse(evt.Data!);
            return payload.RootElement.GetProperty("value").GetInt32();
        }
    }

    [Theory]
    [InlineData(false, ControlledToolOutcome.Success)]
    [InlineData(true, ControlledToolOutcome.Success)]
    [InlineData(false, ControlledToolOutcome.Failure)]
    [InlineData(true, ControlledToolOutcome.Failure)]
    [InlineData(false, ControlledToolOutcome.Unknown)]
    [InlineData(true, ControlledToolOutcome.Unknown)]
    public async Task ProductionBodyNestedBreak_SettlesAdmittedMcpOutcomeBeforeRootTerminal(
        bool sqlite, ControlledToolOutcome outcome)
    {
        var body = ParallelMcpDefinition();
        var definition = body with
        {
            Nodes = body.Nodes.SetItem("tool-research",
                new NodeDefinition(WorkflowRunner.StructuredProofBreakNodeType, "proof-only")),
            ExecutionConnections = body.ExecutionConnections!.SetItem("tool-research-join",
                Edge("tool-research", "out", "join", "branch.left")),
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .Add("outerIndex", new("Outer array index", "0") { Type = WorkflowDataTypes.Integer })
                .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        var revision = WorkflowRevision.CreateProofOnly(definition,
            $"production-body-nested-break-{outcome.ToString().ToLowerInvariant()}-tool-proof");
        const string outerItems = "[\"outer-a\"]";
        const string innerItems = "[\"break\",\"must-not-run\"]";
        using var runStore = new ProofRunStore(revision, outerItems, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var tools = new ControlledSettlementToolBroker("proof.parallel-tool", outcome);
        var breakCompleted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);

        ValueTask Record(ExecutionEvent evt)
        {
            recorder.Append(evt);
            if (evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "tool-research")
                breakCompleted.TrySetResult();
            return ValueTask.CompletedTask;
        }

        var execution = new WorkflowRunner(tools: tools)
            .ExecuteProductionNestedBodyBreakSequenceProofAsync(runStore.RunId, revision,
                outerItems, innerItems, "outerIndex", "index", null,
                Record, runBudget: StructuredRunBudget(maximumToolDispatches: 1) with
                {
                    MaximumModelDispatches = 1
                }, itemParameterId: null);

        try
        {
            try
            {
                await breakCompleted.Task.WaitAsync(TimeSpan.FromSeconds(5));
                await tools.DispatchStarted.Task.WaitAsync(TimeSpan.FromSeconds(5));
            }
            catch (TimeoutException exception)
            {
                var summary = string.Join("\n", recorder.Snapshot().Select(evt =>
                    $"{evt.Sequence}:{evt.NodeId ?? "root"}:{evt.Kind}:{evt.ScopeId ?? "root"}"));
                throw new Xunit.Sdk.XunitException(
                    $"Nested Break/MCP settlement did not reach its gate (task={execution.Status}, error={execution.Exception}): " +
                    $"{summary}\n{exception.Message}");
            }
            Assert.False(execution.IsCompleted,
                "The nested coordinator must wait for the admitted MCP outcome after Break.");
        }
        finally
        {
            tools.ReleaseOutcome.TrySetResult();
        }

        var result = await execution.WaitAsync(TimeSpan.FromSeconds(5));
        var events = recorder.Snapshot();
        var expectedToolOutcome = outcome switch
        {
            ControlledToolOutcome.Success => ExecutionEventKinds.ToolCompleted,
            ControlledToolOutcome.Failure => ExecutionEventKinds.ToolFailed,
            ControlledToolOutcome.Unknown => ExecutionEventKinds.ToolUncertain,
            _ => throw new ArgumentOutOfRangeException(nameof(outcome))
        };
        var expectedRunOutcome = outcome switch
        {
            ControlledToolOutcome.Success => ExecutionEventKinds.Completed,
            ControlledToolOutcome.Failure => ExecutionEventKinds.Failed,
            ControlledToolOutcome.Unknown => ExecutionEventKinds.OutcomeUnknown,
            _ => throw new ArgumentOutOfRangeException(nameof(outcome))
        };
        var expectedRunStatus = outcome switch
        {
            ControlledToolOutcome.Success => "completed",
            ControlledToolOutcome.Failure => "failed",
            ControlledToolOutcome.Unknown => "outcome-unknown",
            _ => throw new ArgumentOutOfRangeException(nameof(outcome))
        };
        Assert.Equal(outcome != ControlledToolOutcome.Success, result.Failed);
        Assert.Equal(outcome == ControlledToolOutcome.Unknown, result.OutcomeUnknown);
        Assert.Equal(outcome == ControlledToolOutcome.Success, result.HasOutput);
        var toolOutcome = Assert.Single(events, evt => evt.Kind == expectedToolOutcome && evt.NodeId == "tool-review");
        var breakEvent = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
            evt.NodeId == "tool-research");
        Assert.True(breakEvent.Sequence < toolOutcome.Sequence,
            "The admitted MCP operation must settle after the graph Break request.");
        Assert.DoesNotContain(events, evt => evt.ScopeId == "outer-loop/1");
        Assert.DoesNotContain(events, evt => evt.ScopeId == "outer-loop/0/inner-loop/1");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "join");
        Assert.Single(events, evt => evt.Kind == expectedRunOutcome && evt.NodeId is null);
        Assert.Single(events, evt => evt.NodeId is null && evt.Kind is ExecutionEventKinds.Completed or
            ExecutionEventKinds.Failed or ExecutionEventKinds.Cancelled or ExecutionEventKinds.Terminated or
            ExecutionEventKinds.OutcomeUnknown);

        AssertPersistedSequence(runStore, events, expectedRunStatus);
        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal(expectedRunStatus, reopened.Status);
        var playback = await RenderPlayback(reopened);
        Assert.Contains($"Latest run status: {expectedRunStatus}", playback, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyNestedBreak_ComposesRealMcpCompletionWithBreak(bool sqlite)
    {
        const string outerItems = "[\"outer-a\"]";
        const string innerItems = "[\"break\",\"must-not-run\"]";
        var toolAuthorized = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var sourceRegistration = Assert.Single(CreateDemoMcpRegistrations("demo.slow"));
        var discovery = new McpToolBroker([sourceRegistration], new DemoToolPolicy());
        var binding = Assert.Single(await discovery.ListBindingsAsync(), item => item.BindingId == "demo.slow");
        var definition = ParallelBodyDefinition() with
        {
            Nodes = ParallelBodyDefinition().Nodes
                .SetItem("agent-left", new(NodeTypes.Agent, "1.0.0",
                    Agent: new("proof.authorization-barrier", null, "Wait for tool authorization", [])))
                .SetItem("agent-right", new(NodeTypes.McpTool, "1.0.0",
                    new ToolBindingRequest(binding.BindingId, binding.ContractHash)
                    {
                        DescriptionHash = binding.DescriptionHash
                    })
                {
                    McpArgumentsJson = "{}"
                })
                .Add("proof-break", new(WorkflowRunner.StructuredProofBreakNodeType, "proof-only")),
            Connections = ParallelBodyDefinition().Connections
                .Remove("input-right")
                .Add("left-break", new(new("agent-left", "out"), new("proof-break", "in"), "data")),
            ExecutionConnections = ParallelBodyDefinition().ExecutionConnections!
                .Remove("left-join")
                .Remove("right-agent")
                .Remove("right-join")
                .Add("left-break", Edge("agent-left", "out", "proof-break", "execute"))
                .Add("break-join", Edge("proof-break", "out", "join", "branch.left"))
                .Add("right-tool", Edge("anchor-right", "then", "agent-right", "execute"))
                .Add("tool-join", Edge("agent-right", "then", "join", "branch.right")),
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .Add("outerIndex", new("Outer array index", "0") { Type = WorkflowDataTypes.Integer })
                .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer })
                .Add("item", new("Array item", "") { Type = WorkflowDataTypes.String })
        };
        var revision = WorkflowRevision.CreateProofOnly(definition,
            "production-body-nested-break-production-mcp-drain-proof");
        using var runStore = new ProofRunStore(revision, outerItems, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var agents = new AuthorizationBarrierAgentExecutor(toolAuthorized.Task);

        ValueTask Record(ExecutionEvent evt)
        {
            recorder.Append(evt);
            if (evt.Kind == ExecutionEventKinds.ToolAuthorized && evt.NodeId == "agent-right")
                toolAuthorized.TrySetResult();
            return ValueTask.CompletedTask;
        }

        var tools = new ProofRevisionProjectionToolBroker(
            new McpToolBroker([sourceRegistration], new DemoToolPolicy(), TimeSpan.FromSeconds(20)), revision);
        var result = await new WorkflowRunner(tools, agents)
            .ExecuteProductionNestedBodyBreakSequenceProofAsync(runStore.RunId, revision, outerItems, innerItems,
                "outerIndex", "index", null, Record,
                runBudget: StructuredRunBudget(maximumToolDispatches: 2), itemParameterId: "item")
            .WaitAsync(TimeSpan.FromSeconds(20));

        Assert.False(result.Failed, string.Join("\n", recorder.Snapshot().Select(evt =>
            $"{evt.Sequence}:{evt.NodeId ?? "root"}:{evt.Kind}:{evt.Data ?? ""}")));
        Assert.False(result.Cancelled);
        Assert.False(result.OutcomeUnknown);
        Assert.True(result.HasOutput);
        var authorization = Assert.Single(recorder.Snapshot(), evt =>
            evt.Kind == ExecutionEventKinds.ToolAuthorized && evt.NodeId == "agent-right");
        var completedTool = Assert.Single(recorder.Snapshot(), evt =>
            evt.Kind == ExecutionEventKinds.ToolCompleted && evt.NodeId == "agent-right");
        var breakCompleted = Assert.Single(recorder.Snapshot(), evt =>
            evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "proof-break");
        Assert.True(authorization.Sequence < completedTool.Sequence);
        Assert.True(completedTool.Sequence < breakCompleted.Sequence,
            "Agent Framework settles this direct MCP node before advancing the fork to Break.");
        Assert.DoesNotContain(recorder.Snapshot(), evt => evt.Kind == ExecutionEventKinds.ToolUncertain);
        Assert.DoesNotContain(recorder.Snapshot(), evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
            evt.NodeId == "join");
        Assert.DoesNotContain(recorder.Snapshot(), evt => evt.ScopeId == "outer-loop/0/inner-loop/1");
        Assert.Contains(recorder.Snapshot(), evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
            evt.NodeId == "inner-loop" && evt.ScopeId == "outer-loop/0/inner-loop/0" &&
            evt.Data?.Contains("\"outcome\":\"break\"", StringComparison.Ordinal) == true);
        AssertPersistedSequence(runStore, recorder.Snapshot(), "completed");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(recorder.Snapshot(), reopened.Events);
        Assert.Equal("completed", reopened.Status);
        var playback = await RenderPlayback(reopened);
        Assert.Contains("Latest run status: completed", playback, StringComparison.Ordinal);
        Assert.Contains(ExecutionEventKinds.ToolCompleted, playback, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyNestedBranchSequenceBreak_ResolvesNearestFrameAndReopensPlayback(bool sqlite)
    {
        var revision = NestedBranchSequenceBreakDefinition();
        const string outerItems = "[\"outer-a\",\"outer-b\"]";
        const string innerItems = "[\"continue\",\"break\",\"must-not-run\"]";
        using var runStore = new ProofRunStore(revision, outerItems, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var runner = new WorkflowRunner();
        var sequencePlan = new WorkflowRunner.SequenceProductionPlan("sequence", [
            new("decision", 0, "branch", "sequence", "then.decision", "sequence-branch"),
            new("suffix", 1, "suffix-output", "sequence", "then.suffix", "sequence-suffix")
        ], null, SequenceTerminalState.Completed);

        var result = await runner.ExecuteProductionNestedBodyBreakSequenceProofAsync(runStore.RunId, revision,
            outerItems, innerItems, "outerIndex", "index", null, evt =>
            {
                recorder.Append(evt);
                return ValueTask.CompletedTask;
            }, itemParameterId: "item", sequencePlan: sequencePlan);

        Assert.False(result.Failed, string.Join("\n", recorder.Snapshot().Select(evt =>
            $"{evt.Sequence}:{evt.NodeId ?? "root"}:{evt.Kind}:{evt.Data ?? ""}")));
        Assert.True(result.HasOutput);
        Assert.Equal("outer-a:continue;outer-b:continue", result.Output);
        var events = recorder.Snapshot();
        var breakIterations = events.Where(evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
            evt.NodeId == "inner-loop" && evt.Data?.Contains("\"outcome\":\"break\"", StringComparison.Ordinal) == true)
            .ToArray();
        Assert.Equal(2, breakIterations.Length);
        foreach (var breakIteration in breakIterations)
        {
            var started = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
                evt.NodeId == "inner-loop" && evt.ScopeId == breakIteration.ScopeId);
            using var outcome = JsonDocument.Parse(breakIteration.Data!);
            Assert.Equal(started.InvocationId, outcome.RootElement.GetProperty("targetFrameId").GetGuid());
        }
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
            evt.NodeId == "inner-loop" && evt.ScopeId?.EndsWith("/inner-loop/2", StringComparison.Ordinal) == true);
        Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
            evt.NodeId == "outer-loop"));
        Assert.Equal(6, events.Count(evt => evt.Kind == ExecutionEventKinds.SequenceOutputCompleted &&
            evt.NodeId == "sequence"));
        Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
            evt.NodeId == "sequence"));
        AssertPersistedSequence(runStore, events, "completed");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("completed", reopened.Status);
        var playback = await RenderPlayback(reopened);
        Assert.Contains("Latest run status: completed", playback, StringComparison.Ordinal);
        Assert.Contains(ExecutionEventKinds.SequenceBreakCompleted, playback, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyNestedBranchSequenceBreak_SelectedBranchFailureWinsAndReopens(bool sqlite)
    {
        const string bindingId = "proof.sequence-branch-tool";
        var revision = NestedBranchSequenceBreakWithFailingToolDefinition(bindingId);
        const string outerItems = "[\"outer-a\",\"outer-b\"]";
        const string innerItems = "[\"break\",\"must-not-run\"]";
        using var runStore = new ProofRunStore(revision, outerItems, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var tools = new ControlledSettlementToolBroker(bindingId, ControlledToolOutcome.Failure);
        var sequencePlan = new WorkflowRunner.SequenceProductionPlan("sequence", [
            new("decision", 0, "branch", "sequence", "then.decision", "sequence-branch"),
            new("suffix", 1, "suffix-output", "sequence", "then.suffix", "sequence-suffix")
        ], null, SequenceTerminalState.Completed);

        var execution = new WorkflowRunner(tools: tools).ExecuteProductionNestedBodyBreakSequenceProofAsync(
            runStore.RunId, revision, outerItems, innerItems, "outerIndex", "index", null, evt =>
        {
            recorder.Append(evt);
            return ValueTask.CompletedTask;
        }, itemParameterId: "item", sequencePlan: sequencePlan);

        try
        {
            await tools.DispatchStarted.Task.WaitAsync(TimeSpan.FromSeconds(5));
            tools.ReleaseOutcome.TrySetResult();
            var result = await execution.WaitAsync(TimeSpan.FromSeconds(5));
            var events = recorder.Snapshot();

            Assert.True(result.Failed);
            Assert.False(result.Cancelled);
            Assert.False(result.HasOutput);
            Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.ToolFailed &&
                evt.NodeId == "tool" && evt.ScopeId == "outer-loop/0/inner-loop/0");
            Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputFailed &&
                evt.NodeId == "sequence" && SequenceEvidence.TryRead(evt, out var evidence) &&
                evidence?.OutputId == "decision");
            Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
                evt.NodeId == "sequence" && SequenceEvidence.TryRead(evt, out var evidence) &&
                evidence?.OutputId == "suffix");
            Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakCompleted);
            Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
                evt.NodeId == "inner-loop" && evt.ScopeId == "outer-loop/0/inner-loop/1");
            Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
                evt.NodeId == "outer-loop" && evt.ScopeId == "outer-loop/1");
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
            AssertPersistedSequence(runStore, events, "failed");

            var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
            Assert.Equal(events, reopened.Events);
            Assert.True(SequenceEvidence.TryReconstructPlayback(reopened.Events, out var sequencePlayback));
            Assert.Equal("failed", sequencePlayback!.Status);
            Assert.Equal(["failed", "skipped"], sequencePlayback.Outputs.Select(output => output.State));
            Assert.Contains("Latest run status: failed", await RenderPlayback(reopened), StringComparison.Ordinal);
        }
        finally
        {
            tools.ReleaseOutcome.TrySetResult();
            if (!execution.IsCompleted) await execution.WaitAsync(TimeSpan.FromSeconds(5));
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyNestedConditionalBreak_RecordsSchedulingBoundaryWithHeldAgent(bool sqlite)
    {
        var revision = NestedConditionalSequenceBreakWithHeldAgent();
        using var runStore = new ProofRunStore(revision, "[\"outer-a\",\"outer-b\"]", sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var agents = new ControlledSettlementAgentExecutor("agent");
        var branchCompleted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var breakStarted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var breakSettled = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var sequencePlan = new WorkflowRunner.SequenceProductionPlan("sequence", [
            new("decision", 0, "branch", "sequence", "then.decision", "sequence-break"),
            new("sibling", 1, "agent", "sequence", "then.sibling", "sequence-sibling")
        ], null, SequenceTerminalState.Completed);
        var execution = new WorkflowRunner(agents: agents).ExecuteProductionNestedBodyBreakSequenceProofAsync(
            runStore.RunId, revision, "[\"outer-a\",\"outer-b\"]", "[\"inner\"]", "outerIndex", "index", null,
            evt =>
            {
                recorder.Append(evt);
                if (evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "branch")
                    branchCompleted.TrySetResult();
                if (evt.Kind == ExecutionEventKinds.NodeStarted && evt.NodeId == "break")
                    breakStarted.TrySetResult();
                if (evt.Kind == ExecutionEventKinds.SequenceOutputCompleted &&
                    SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "decision")
                    breakSettled.TrySetResult();
                return ValueTask.CompletedTask;
            }, itemParameterId: "item", proofBreakNodeIds: new HashSet<string>(["break"], StringComparer.Ordinal),
            sequencePlan: sequencePlan, maximumConcurrentSequenceOutputs: 2)
            .WaitAsync(TimeSpan.FromSeconds(10));
        try
        {
            await agents.Started.Task.WaitAsync(TimeSpan.FromSeconds(5));
            await branchCompleted.Task.WaitAsync(TimeSpan.FromSeconds(5));
            Assert.False(ReferenceEquals(breakStarted.Task,
                await Task.WhenAny(breakStarted.Task, Task.Delay(TimeSpan.FromSeconds(1)))),
                "Break should remain unobserved before the held sibling is released in this diagnostic fixture.");
            agents.Release.TrySetResult();
            try
            {
                await breakStarted.Task.WaitAsync(TimeSpan.FromSeconds(5));
                await breakSettled.Task.WaitAsync(TimeSpan.FromSeconds(5));
            }
            catch (TimeoutException)
            {
                throw new Xunit.Sdk.XunitException("Conditional Branch Break did not progress after Agent release. Events: " +
                    string.Join(" | ", recorder.Snapshot().Select(evt =>
                        $"{evt.Sequence}:{evt.Kind}:{evt.NodeId}:{evt.Data}")));
            }
            var result = await execution;
            var events = recorder.Snapshot();
            Assert.False(result.Failed);
            Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.SequenceBreakCompleted));
            var firstAgentCompleted = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
                evt.NodeId == "agent" && evt.ScopeId == "outer-loop/0/inner-loop/0");
            var firstBreakStarted = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
                evt.NodeId == "break" && evt.ScopeId == "outer-loop/0/inner-loop/0");
            Assert.True(firstAgentCompleted.Sequence < firstBreakStarted.Sequence,
                "The queued Branch-to-Break hop should become runnable only after the sibling settles.");
            AssertPersistedSequence(runStore, events, "completed");
            var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
            Assert.Equal(events, reopened.Events);
        }
        finally
        {
            agents.Release.TrySetResult();
            if (!execution.IsCompleted) await execution.WaitAsync(TimeSpan.FromSeconds(5));
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyNestedConditionalBreak_DoesNotMaskHeldAgentFailure(bool sqlite)
    {
        var revision = NestedConditionalSequenceBreakWithHeldAgent();
        using var runStore = new ProofRunStore(revision, "[\"outer-a\"]", sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var agents = new ControlledSettlementAgentExecutor("agent", failAfterRelease: true);
        var branchCompleted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var breakStarted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var sequencePlan = new WorkflowRunner.SequenceProductionPlan("sequence", [
            new("decision", 0, "branch", "sequence", "then.decision", "sequence-break"),
            new("sibling", 1, "agent", "sequence", "then.sibling", "sequence-sibling")
        ], null, SequenceTerminalState.Completed);

        var execution = new WorkflowRunner(agents: agents).ExecuteProductionNestedBodyBreakSequenceProofAsync(
            runStore.RunId, revision, "[\"outer-a\"]", "[\"inner\"]", "outerIndex", "index", null,
            evt =>
            {
                recorder.Append(evt);
                if (evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "branch")
                    branchCompleted.TrySetResult();
                if (evt.Kind == ExecutionEventKinds.NodeStarted && evt.NodeId == "break")
                    breakStarted.TrySetResult();
                return ValueTask.CompletedTask;
            }, itemParameterId: "item", proofBreakNodeIds: new HashSet<string>(["break"], StringComparer.Ordinal),
            sequencePlan: sequencePlan, maximumConcurrentSequenceOutputs: 2)
            .WaitAsync(TimeSpan.FromSeconds(10));

        try
        {
            await agents.Started.Task.WaitAsync(TimeSpan.FromSeconds(5));
            await branchCompleted.Task.WaitAsync(TimeSpan.FromSeconds(5));
            Assert.NotSame(breakStarted.Task,
                await Task.WhenAny(breakStarted.Task, Task.Delay(TimeSpan.FromSeconds(1))));

            agents.Release.TrySetResult();
            var result = await execution;
            var events = recorder.Snapshot();

            Assert.True(result.Failed);
            Assert.False(result.Cancelled);
            Assert.False(result.HasOutput);
            Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.NodeFailed && evt.NodeId == "agent");
            Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputFailed &&
                evt.NodeId == "sequence" && SequenceEvidence.TryRead(evt, out var evidence) &&
                evidence?.OutputId == "sibling");
            Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakAccepted);
            Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakCompleted);
            Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeStarted && evt.NodeId == "break");
            AssertPersistedSequence(runStore, events, "failed");

            var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
            Assert.Equal(events, reopened.Events);
            Assert.True(SequenceEvidence.TryReconstructPlayback(reopened.Events, out var playback));
            Assert.Equal("failed", playback!.Status);
            Assert.Equal(["cancelled", "failed"], playback.Outputs.Select(output => output.State));
            Assert.Contains("Latest run status: failed", await RenderPlayback(reopened), StringComparison.Ordinal);
        }
        finally
        {
            agents.Release.TrySetResult();
            if (!execution.IsCompleted) await execution.WaitAsync(TimeSpan.FromSeconds(5));
        }
    }

