            tools.ReleaseOutcome.TrySetResult();
            failure = await Xunit.Record.ExceptionAsync(() => execution.WaitAsync(TimeSpan.FromSeconds(5)));
        }
        finally
        {
            tools.ReleaseOutcome.TrySetResult();
        }
        var events = recorder.Snapshot();

        Assert.IsType<IOException>(failure);
        Assert.Contains(ExecutionEventKinds.Failed, failure!.Message, StringComparison.Ordinal);
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.ToolFailed && evt.NodeId == "tool");
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputFailed &&
            evt.NodeId == "sequence" && SequenceEvidence.TryRead(evt, out var evidence) &&
            evidence?.OutputId == "decision");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
        AssertPersistedSequence(runStore, events, "running");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("running", reopened.Status);
        var sequenceEvents = reopened.Events.Where(evt => SequenceEvidence.IsLifecycleEvent(evt.Kind));
        Assert.True(SequenceEvidence.TryReconstructPlayback(sequenceEvents, out var playback));
        Assert.Equal("failed", playback!.Status);
        Assert.Equal(["failed", "completed"], playback.Outputs.Select(output => output.State));
    }

    [Theory]
    [InlineData(false, ExecutionEventKinds.SequenceBreakAccepted, "")]
    [InlineData(true, ExecutionEventKinds.SequenceBreakAccepted, "")]
    [InlineData(false, ExecutionEventKinds.SequenceBreakCompleted, "")]
    [InlineData(true, ExecutionEventKinds.SequenceBreakCompleted, "")]
    [InlineData(false, ExecutionEventKinds.Completed, "")]
    [InlineData(true, ExecutionEventKinds.Completed, "")]
    [InlineData(false, ExecutionEventKinds.NodeCompleted, "break")]
    [InlineData(true, ExecutionEventKinds.NodeCompleted, "break")]
    [InlineData(false, ExecutionEventKinds.LoopIterationCompleted, "inner-loop")]
    [InlineData(true, ExecutionEventKinds.LoopIterationCompleted, "inner-loop")]
    public async Task ProductionBodyNestedConditionalBreak_ProcessLossPreservesCommittedPrefix(bool sqlite,
        string stopAfterEvent, string stopAfterNodeId)
    {
        var directory = Path.Combine(Path.GetTempPath(), $"vaw-array-break-process-loss-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        var storePath = sqlite ? Path.Combine(directory, "runs.sqlite3") : Path.Combine(directory, "runs");
        var readyPath = Path.Combine(directory, "checkpoint.json");
        try
        {
            using var process = Process.Start(CreateNestedBreakProcessProbeStartInfo(storePath, readyPath, sqlite,
                stopAfterEvent, stopAfterNodeId))!;
            var stdoutTask = process.StandardOutput.ReadToEndAsync();
            var stderrTask = process.StandardError.ReadToEndAsync();
            for (var attempt = 0; attempt < 250 && !File.Exists(readyPath) && !process.HasExited; attempt++)
                await Task.Delay(20);

            if (!File.Exists(readyPath))
            {
                if (!process.HasExited)
                {
                    process.Kill(entireProcessTree: true);
                    await process.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(10));
                }
                Assert.Fail($"The child process did not commit {stopAfterEvent}. stdout={await stdoutTask}; stderr={await stderrTask}");
            }
            var runId = Guid.Parse(JsonDocument.Parse(await File.ReadAllTextAsync(readyPath))
                .RootElement.GetProperty("runId").GetString()!);
            process.Kill(entireProcessTree: true);
            await process.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(10));
            await stdoutTask;
            await stderrTask;

            IWorkflowRunStore reopenedStore = sqlite
                ? new SqliteWorkflowRunStore(storePath)
                : new FileRunJournal(storePath);
            var reopened = reopenedStore.Get(runId)!;
            Assert.DoesNotContain(reopened.Events, evt => evt.Kind is ExecutionEventKinds.SequenceCompleted or
                ExecutionEventKinds.Failed or ExecutionEventKinds.Cancelled);
            Assert.True(SequenceEvidence.TryReconstructPlayback(
                reopened.Events.Where(evt => SequenceEvidence.IsLifecycleEvent(evt.Kind)), out var playback));
            if (stopAfterEvent == ExecutionEventKinds.NodeCompleted)
            {
                Assert.Equal("running", reopened.Status);
                Assert.Single(reopened.Events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
                    evt.NodeId == "break");
                Assert.DoesNotContain(reopened.Events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakAccepted);
                Assert.Equal("running", playback!.Status);
                Assert.Null(playback.BreakAcceptance);
            }
            else if (stopAfterEvent == ExecutionEventKinds.SequenceBreakAccepted)
            {
                Assert.Contains(reopened.Events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakAccepted);
                Assert.NotNull(playback!.BreakAcceptance);
                Assert.Equal("running", reopened.Status);
                Assert.Equal("running", playback.Status);
                Assert.DoesNotContain(reopened.Events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakCompleted);
                Assert.Equal(["dispatched", "completed"], playback.Outputs.Select(output => output.State));
            }
            else if (stopAfterEvent == ExecutionEventKinds.SequenceBreakCompleted)
            {
                Assert.Contains(reopened.Events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakAccepted);
                Assert.NotNull(playback!.BreakAcceptance);
                Assert.Equal("running", reopened.Status);
                Assert.Contains(reopened.Events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakCompleted);
                Assert.Equal("break-completed", playback.Status);
                Assert.NotEmpty(playback.Outputs);
            }
            else if (stopAfterEvent == ExecutionEventKinds.LoopIterationCompleted)
            {
                Assert.Contains(reopened.Events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakAccepted);
                Assert.NotNull(playback!.BreakAcceptance);
                Assert.Equal("running", reopened.Status);
                var innerSettlement = Assert.Single(reopened.Events, evt =>
                    evt.Kind == ExecutionEventKinds.LoopIterationCompleted && evt.NodeId == "inner-loop");
                using var innerOutcome = JsonDocument.Parse(innerSettlement.Data!);
                Assert.Equal("break", innerOutcome.RootElement.GetProperty("outcome").GetString());
                Assert.DoesNotContain(reopened.Events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
                    evt.NodeId == "outer-loop");
                Assert.DoesNotContain(reopened.Events, evt => evt.Kind == ExecutionEventKinds.Completed &&
                    evt.NodeId is null);
                Assert.Equal("break-completed", playback.Status);
            }
            else
            {
                Assert.Contains(reopened.Events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakAccepted);
                Assert.NotNull(playback!.BreakAcceptance);
                Assert.Equal(ExecutionEventKinds.Completed, stopAfterEvent);
                Assert.Equal("completed", reopened.Status);
                Assert.Contains(reopened.Events, evt => evt.Kind == ExecutionEventKinds.Completed);
                Assert.Equal("break-completed", playback.Status);
            }
        }
        finally
        {
            if (Directory.Exists(directory)) Directory.Delete(directory, recursive: true);
        }
    }

    [Fact]
    public async Task Fresh_process_nested_array_break_probe()
    {
        var storePath = Environment.GetEnvironmentVariable("VAW_ARRAY_BREAK_PROBE_STORE");
        if (string.IsNullOrWhiteSpace(storePath)) return;
        var sqlite = Environment.GetEnvironmentVariable("VAW_ARRAY_BREAK_PROBE_SQLITE") == "1";
        var readyPath = Environment.GetEnvironmentVariable("VAW_ARRAY_BREAK_PROBE_READY")!;
        var stopAfterEvent = Environment.GetEnvironmentVariable("VAW_ARRAY_BREAK_PROBE_STOP_AFTER")!;
        var stopAfterNodeId = Environment.GetEnvironmentVariable("VAW_ARRAY_BREAK_PROBE_STOP_NODE");
        IWorkflowRunStore store = sqlite
            ? new SqliteWorkflowRunStore(storePath)
            : new FileRunJournal(storePath);
        var revision = NestedBranchSequenceBreakDefinition();
        var run = store.Create(revision, "[\"outer-a\"]");
        long expectedSequence = 0;
        var sequencePlan = new WorkflowRunner.SequenceProductionPlan("sequence", [
            new("decision", 0, "branch", "sequence", "then.decision", "sequence-branch"),
            new("suffix", 1, "suffix-output", "sequence", "then.suffix", "sequence-suffix")
        ], null, SequenceTerminalState.Completed);

        await new WorkflowRunner().ExecuteProductionNestedBodyBreakSequenceProofAsync(run.Header.RunId,
            revision, "[\"outer-a\"]", "[\"break\"]", "outerIndex", "index", null,
            async evt =>
            {
                var persisted = evt with { Sequence = ++expectedSequence };
                store.Append(run.Header.RunId, expectedSequence - 1, [persisted]);
                if (evt.Kind == stopAfterEvent &&
                    (string.IsNullOrEmpty(stopAfterNodeId) || evt.NodeId == stopAfterNodeId))
                {
                    var readyContents = JsonSerializer.Serialize(new { runId = run.Header.RunId });
                    var temporaryReadyPath = readyPath + ".tmp";
                    await File.WriteAllTextAsync(temporaryReadyPath, readyContents);
                    File.Move(temporaryReadyPath, readyPath);
                    await Task.Delay(Timeout.InfiniteTimeSpan);
                }
            }, itemParameterId: "item",
            proofBreakNodeIds: new HashSet<string>(["break"], StringComparer.Ordinal),
            sequencePlan: sequencePlan, maximumConcurrentSequenceOutputs: 2);
    }

    private static ProcessStartInfo CreateNestedBreakProcessProbeStartInfo(string storePath, string readyPath,
        bool sqlite, string stopAfterEvent, string stopAfterNodeId)
    {
        var project = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,
            "../../../../VisualAgentWorkflow.AgentFramework.Tests/VisualAgentWorkflow.AgentFramework.Tests.csproj"));
        var startInfo = new ProcessStartInfo("dotnet")
        {
            WorkingDirectory = Directory.GetCurrentDirectory(),
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false
        };
        startInfo.ArgumentList.Add("test");
        startInfo.ArgumentList.Add(project);
        startInfo.ArgumentList.Add("--no-build");
        startInfo.ArgumentList.Add("--no-restore");
        startInfo.ArgumentList.Add("--filter");
        startInfo.ArgumentList.Add("FullyQualifiedName~Fresh_process_nested_array_break_probe");
        startInfo.Environment["VAW_ARRAY_BREAK_PROBE_STORE"] = storePath;
        startInfo.Environment["VAW_ARRAY_BREAK_PROBE_SQLITE"] = sqlite ? "1" : "0";
        startInfo.Environment["VAW_ARRAY_BREAK_PROBE_READY"] = readyPath;
        startInfo.Environment["VAW_ARRAY_BREAK_PROBE_STOP_AFTER"] = stopAfterEvent;
        startInfo.Environment["VAW_ARRAY_BREAK_PROBE_STOP_NODE"] = stopAfterNodeId;
        return startInfo;
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task IteratorCandidates_NestedConditionalBreakSchedulingMatchesFreshSubworkflow(bool sqlite)
    {
        var revision = NestedConditionalSequenceBreakWithHeldAgent();
        var production = await RunCandidateAsync(freshSubworkflow: false);
        var subworkflow = await RunCandidateAsync(freshSubworkflow: true);

        Assert.Equal(ProductionSequenceShape(production.Events), ProductionSequenceShape(subworkflow.Events));

        async Task<(ExecutionEvent[] Events, string Status)> RunCandidateAsync(bool freshSubworkflow)
        {
            using var runStore = new ProofRunStore(revision, "[\"outer-a\",\"outer-b\"]", sqlite);
            var recorder = new ProofRecorder(runStore, startRoot: false);
            var agents = new ControlledSettlementAgentExecutor("agent");
            var branchCompleted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
            var breakStarted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
            var sequencePlan = new WorkflowRunner.SequenceProductionPlan("sequence", [
                new("decision", 0, "branch", "sequence", "then.decision", "sequence-break"),
                new("sibling", 1, "agent", "sequence", "then.sibling", "sequence-sibling")
            ], null, SequenceTerminalState.Completed);
            ValueTask Record(ExecutionEvent evt)
            {
                recorder.Append(evt);
                if (evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "branch")
                    branchCompleted.TrySetResult();
                if (evt.Kind == ExecutionEventKinds.NodeStarted && evt.NodeId == "break")
                    breakStarted.TrySetResult();
                return ValueTask.CompletedTask;
            }

            var execution = freshSubworkflow
                ? ExecuteFreshNestedBreakCandidateAsync(runStore.RunId, revision, recorder, agents,
                    sequencePlan, Record)
                : new WorkflowRunner(agents: agents).ExecuteProductionNestedBodyBreakSequenceProofAsync(
                    runStore.RunId, revision, "[\"outer-a\",\"outer-b\"]", "[\"inner\"]",
                    "outerIndex", "index", null, Record,
                    itemParameterId: "item", proofBreakNodeIds: new HashSet<string>(["break"], StringComparer.Ordinal),
                    sequencePlan: sequencePlan, maximumConcurrentSequenceOutputs: 2);

            try
            {
                await agents.Started.Task.WaitAsync(TimeSpan.FromSeconds(5));
                await branchCompleted.Task.WaitAsync(TimeSpan.FromSeconds(5));
                var earlyBreak = await Task.WhenAny(breakStarted.Task, Task.Delay(TimeSpan.FromSeconds(1)));
                Assert.NotSame(breakStarted.Task, earlyBreak);
                agents.Release.TrySetResult();
                var result = await execution.WaitAsync(TimeSpan.FromSeconds(10));
                var events = recorder.Snapshot();
                Assert.False(result.Failed, string.Join("\n", events.Select(evt =>
                    $"{evt.Sequence} {evt.Kind} {evt.NodeId} scope={evt.ScopeId} {evt.Data}")));
                Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.SequenceBreakCompleted));
                AssertPersistedSequence(runStore, events, "completed");
                var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
                Assert.Equal(events, reopened.Events);
                var sequenceGroups = reopened.Events.Where(evt => SequenceEvidence.IsLifecycleEvent(evt.Kind))
                    .GroupBy(evt =>
                    {
                        if (SequenceBreakAcceptanceEvidence.TryRead(evt, out var accepted))
                            return accepted!.SequenceInvocationId;
                        Assert.True(SequenceEvidence.TryRead(evt, out var evidence));
                        return evidence!.SequenceInvocationId;
                    });
                foreach (var sequenceGroup in sequenceGroups)
                {
                    Assert.True(SequenceEvidence.TryReconstructPlayback(sequenceGroup, out var playback),
                        $"Could not reconstruct {sequenceGroup.Key}: {string.Join(" | ", sequenceGroup.Select(evt => evt.Kind))}");
                    Assert.Equal("break-completed", playback!.Status);
                }
                return (events, "completed");
            }
            finally
            {
                agents.Release.TrySetResult();
            }
        }
    }

    private static async Task<WorkflowExecutionResult> ExecuteFreshNestedBreakCandidateAsync(Guid runId,
        WorkflowRevision revision, ProofRecorder recorder, IAgentNodeExecutor agents,
        WorkflowRunner.SequenceProductionPlan sequencePlan, Func<ExecutionEvent, ValueTask> record)
    {
        var breakNodeIds = new HashSet<string>(["break"], StringComparer.Ordinal);
        var baseParameters = WorkflowParameters.Resolve(revision.Definition, null)
            ?? ImmutableSortedDictionary<string, string>.Empty.WithComparers(StringComparer.Ordinal);
        await record(new ExecutionEvent(runId, revision.RevisionId, 0, DateTimeOffset.UtcNow,
            ExecutionEventKinds.Started));

        for (var outerIndex = 0; outerIndex < 2; outerIndex++)
        {
            var outerFrame = new WorkflowRunner.StructuredActivationFrame(Guid.NewGuid(), null,
                "outer-loop", outerIndex, $"outer-{(char)('a' + outerIndex)}", baseParameters);
            outerFrame = outerFrame with
            {
                Parameters = outerFrame.BindIteratorValues(revision.Definition, null, "outerIndex")
            };
            recorder.Append(ExecutionEventKinds.LoopIterationStarted, "outer-loop", outerFrame.Id,
                outerFrame.ScopeId);

            var innerBreaks = new ConcurrentQueue<LoopProofBreakDispatch>();
            await RunFreshSubworkflowLoopProofAsync(runId, revision, recorder, "inner-loop", ["inner"],
                outerFrame, "index", innerBreaks, async innerFrame =>
                {
                    var (child, workflow) = BuildFreshVawBodyWorkflow();
                    var bodyInput = new FreshVawBodyInput(async cancellationToken =>
                    {
                        var connectionIds = sequencePlan.Outputs.ToDictionary(output => output.OutputId,
                            output => output.ConnectionId, StringComparer.Ordinal);
                        var coordinator = new SequenceRuntimeCoordinator(Guid.NewGuid(), sequencePlan.SequenceNodeId,
                            sequencePlan.Outputs.Select(output => output.OutputId).ToArray(), connectionIds,
                            sequencePlan.AllowSingleOutput, scopeId: innerFrame.ScopeId);
                        var sequenceSession = new WorkflowRunner.SequenceProductionDispatchSession(coordinator,
                            innerFrame, breakNodeIds, maximumConcurrentOutputs: 2);
                        ValueTask RecordBodyEvent(ExecutionEvent evt) => record(evt with
                        {
                            ScopeId = evt.ScopeId ?? innerFrame.ScopeId
                        });
                        var outcome = await new WorkflowRunner(agents: agents).ExecuteBodyForActivationProofAsync(
                            runId, revision, innerFrame.Item, innerFrame.Parameters, RecordBodyEvent, cancellationToken,
                            activationFrame: innerFrame, proofBreakNodeIds: breakNodeIds,
                            sequencePlan: sequencePlan, sequenceDispatchSession: sequenceSession);
                        if (outcome.Disposition == WorkflowBodyProofDisposition.BreakRequested &&
                            outcome.BreakRequest is { } request)
                        {
                            var signal = WorkflowRunner.ConsumeProductionBodyBreakRequestProof(innerFrame,
                                request, breakNodeIds);
                            recorder.Append(new ExecutionEvent(runId, revision.RevisionId, 0, DateTimeOffset.UtcNow,
                                ExecutionEventKinds.LoopIterationCompleted, "inner-loop", innerFrame.Id)
                            {
                                ScopeId = innerFrame.ScopeId,
                                Data = JsonSerializer.Serialize(new { outcome = "break", signal.SourceNodeId,
                                    signal.TargetFrameId }, new JsonSerializerOptions(JsonSerializerDefaults.Web))
                            });
                            return new LoopProofBreak(signal.SourceNodeId, signal.SourceFrameId,
                                signal.TargetFrameId, signal.ScopeId);
                        }

                        if (outcome.Disposition != WorkflowBodyProofDisposition.Succeeded || outcome.Output is null)
                            throw new InvalidOperationException($"Fresh-subworkflow body ended as {outcome.Disposition}.");
                        recorder.Append(new ExecutionEvent(runId, revision.RevisionId, 0, DateTimeOffset.UtcNow,
                            ExecutionEventKinds.LoopIterationCompleted, "inner-loop", innerFrame.Id)
                            { ScopeId = innerFrame.ScopeId });
                        return new ActivationLoopProofValue(outcome.Output);
                    });

                    await using var run = await InProcessExecution.Concurrent.RunStreamingAsync(workflow, bodyInput);
                    LoopProofResult? result = null;
                    await foreach (var evt in run.WatchStreamAsync())
                        if (evt is WorkflowOutputEvent { Data: LoopProofResult proofResult }) result = proofResult;
                    _ = child;
                    return result ?? throw new InvalidOperationException("Fresh subworkflow produced no body outcome.");
                });
            Assert.Single(innerBreaks);
            recorder.Append(ExecutionEventKinds.LoopIterationCompleted, "outer-loop", outerFrame.Id,
                outerFrame.ScopeId);
        }

        recorder.CompleteRoot();
        return new WorkflowExecutionResult(null, Terminated: false, HasOutput: false);
    }

    private static (string Kind, string? NodeId, string? ConnectionId, string? ScopeId)[] ProductionSequenceShape(
        IEnumerable<ExecutionEvent> events) => events
        .Where(evt => evt.Kind.StartsWith("sequence.", StringComparison.Ordinal) ||
            evt.Kind is ExecutionEventKinds.BranchSelected or ExecutionEventKinds.LoopIterationStarted or
                ExecutionEventKinds.LoopIterationCompleted or ExecutionEventKinds.NodeStarted or
                ExecutionEventKinds.NodeCompleted)
        .Select(evt => (evt.Kind, evt.NodeId, evt.ConnectionId, evt.ScopeId)).ToArray();

    private static WorkflowRevision NestedBranchSequenceBreakDefinition()
    {
        var definition = WorkflowRunner.CreateSequenceBranchDecisionEvidenceProofRevision(true).Definition;
        var nodes = definition.Nodes
            .SetItem("outcome", new(NodeTypes.Condition, "1.0.0") { Condition = new("equals", "continue") })
            .Add("item", new(NodeTypes.WorkflowValue, "1.0.0")
                { ParameterId = "item", OutputDataType = WorkflowDataTypes.String });
        var connections = definition.Connections.Remove("outcome-condition")
            .Add("item-outcome", new(new("item", "out"), new("outcome", "in"), "data"))
            .Add("item-output", new(new("item", "out"), new("output", "in"), "data"))
            .Add("item-suffix-output", new(new("item", "out"), new("suffix-output", "in"), "data"));
        var parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
            .Add("item", new("Array item", "") { Type = WorkflowDataTypes.String })
            .Add("outerIndex", new("Outer array index", "0") { Type = WorkflowDataTypes.Integer })
            .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer });
        return WorkflowRevision.CreateProofOnly(definition with
        {
            Nodes = nodes,
            Connections = connections,
            Parameters = parameters
        }, "nested-branch-sequence-break-proof");
    }

    private static WorkflowRevision NestedBranchSequenceBreakWithFailingToolDefinition(string bindingId)
    {
        var revision = NestedBranchSequenceBreakDefinition();
        var definition = revision.Definition;
        var nodes = definition.Nodes
            .Add("tool", new NodeDefinition(NodeTypes.McpTool, "1.0.0",
                new ToolBindingRequest(bindingId, new string('a', 64))) { McpArgumentsJson = "{}" });
        var connections = definition.Connections.Add("item-tool",
            new(new("item", "out"), new("tool", "in"), "data"));
        var execution = definition.ExecutionConnections!
            .Remove("merge-outcome")
            .Add("merge-tool", Edge("merge", "then", "tool", "execute"))
            .Add("tool-outcome", Edge("tool", "then", "outcome", "execute"));
        return WorkflowRevision.CreateProofOnly(definition with
        {
            Nodes = nodes,
            Connections = connections,
            ExecutionConnections = execution
        }, "nested-branch-sequence-break-tool-failure-proof");
    }

    private static WorkflowRevision NestedConditionalSequenceBreakWithHeldAgent()
    {
        var nodes = new Dictionary<string, NodeDefinition>
        {
            ["input"] = new(NodeTypes.Input, "1.0.0"),
            ["sequence"] = new(NodeTypes.Sequence, "1.0.0")
            {
                Sequence = new([new("decision", "Break"), new("sibling", "Held sibling")])
            },
            ["condition"] = new(NodeTypes.BooleanConstant, "1.0.0")
            {
                BooleanConstant = new(true)
            },
            ["branch"] = new(NodeTypes.BooleanBranch, "1.0.0"),
            ["break"] = new(WorkflowRunner.StructuredProofBreakNodeType, "proof-only"),
            ["item"] = new(NodeTypes.WorkflowValue, "1.0.0")
            {
                ParameterId = "item", OutputDataType = WorkflowDataTypes.String
            },
            ["agent"] = new(NodeTypes.Agent, "1.0.0",
                Agent: new AgentConfiguration("proof.settlement", null, "Wait for release.", []) { MaxTurns = 1 }),
            ["output"] = new(NodeTypes.Output, "1.0.0")
        }.ToImmutableSortedDictionary(StringComparer.Ordinal);
        var definition = new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "nested-conditional-sequence-break-held-agent-proof", "input", nodes,
            new Dictionary<string, ConnectionDefinition>
            {
                ["branch-condition"] = new(new("condition", "out"), new("branch", "condition"), "data"),
                ["item-agent"] = new(new("item", "out"), new("agent", "in"), "data"),
                ["item-output"] = new(new("item", "out"), new("output", "in"), "data")
            }.ToImmutableSortedDictionary(StringComparer.Ordinal))
        {
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .Add("item", new("Item", "") { Type = WorkflowDataTypes.String })
                .Add("outerIndex", new("Outer index", "0") { Type = WorkflowDataTypes.Integer })
                .Add("index", new("Inner index", "0") { Type = WorkflowDataTypes.Integer }),
            ExecutionConnections = new Dictionary<string, ConnectionDefinition>
            {
                ["input-sequence"] = Edge("input", "then", "sequence", "execute"),
                ["sequence-break"] = Edge("sequence", "then.decision", "branch", "execute"),
                ["branch-true"] = Edge("branch", "true", "break", "execute"),
                ["branch-false"] = Edge("branch", "false", "output", "execute"),
                ["break-output"] = Edge("break", "out", "output", "execute"),
                ["sequence-sibling"] = Edge("sequence", "then.sibling", "agent", "execute"),
                ["agent-output"] = Edge("agent", "out", "output", "execute")
            }.ToImmutableSortedDictionary(StringComparer.Ordinal)
        };
        return WorkflowRevision.CreateProofOnly(definition, "nested-conditional-sequence-break-held-agent-proof");
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyNestedCoordinator_SharesModelBudgetAcrossOuterActivations(bool sqlite)
    {
        var revision = WorkflowRevision.Create(NestedBodyDefinition(),
            "production-body-nested-shared-model-budget-proof");
        const string outerItems = "[\"outer-a\",\"outer-b\"]";
        const string innerItems = "[\"inner\"]";
        using var runStore = new ProofRunStore(revision, outerItems, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var model = new SharedBudgetProofModel();
        var provider = new AgentProviderDescriptor("proof.echo-agent", "Proof model", "proof-chat-v1", true);
        var agents = new AgentNodeExecutor(
            [new AgentProviderRegistration(provider, () => new SharedBudgetProofChatClient(model))],
            new EchoToolBroker());
        var tools = new EchoToolBroker(recordToolDispatchEvents: true);

        var result = await new WorkflowRunner(tools, agents)
            .ExecuteProductionNestedBodyBreakSequenceProofAsync(runStore.RunId, revision,
                outerItems, innerItems, "outerIndex", "index", null, evt =>
                {
                    recorder.Append(evt);
                    return ValueTask.CompletedTask;
                }, runBudget: StructuredRunBudget(maximumToolDispatches: 2) with
                {
                    MaximumModelDispatches = 1
                }, itemParameterId: null);

        var events = recorder.Snapshot();
        Assert.True(result.Failed);
        Assert.Equal(1, model.Calls);
        Assert.Equal(["bounded"], tools.Queries);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ModelRequested);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ModelResponded);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolAuthorized);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolCompleted);
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted &&
            evt.ScopeId == "outer-loop/1");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
            evt.ScopeId == "outer-loop/1");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.Completed && evt.NodeId is null);

        AssertPersistedSequence(runStore, events, "failed");
        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("failed", reopened.Status);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyNestedCoordinator_ComposesForkJoinPerInnerActivation(bool sqlite)
    {
        var definition = ParallelBodyDefinition() with
        {
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .Add("item", new("Array item", "") { Type = WorkflowDataTypes.String })
                .Add("outerIndex", new("Outer array index", "0") { Type = WorkflowDataTypes.Integer })
                .Add("index", new("Inner array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        WorkflowValidator.ThrowIfInvalid(definition);
        var revision = WorkflowRevision.CreateProofOnly(definition,
            "nested-iteration-parallel-fork-join-production-body-proof");
        const string outerItems = "[\"north-region\",\"south-region\"]";
        const string innerItems = "[\"alpha\",\"beta\"]";
        using var runStore = new ProofRunStore(revision, outerItems, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var agents = new EchoAgentExecutor();

        var result = await new WorkflowRunner(agents: agents)
            .ExecuteProductionNestedBodyBreakSequenceProofAsync(runStore.RunId, revision, outerItems, innerItems,
                "outerIndex", "index", null, evt =>
                {
                    recorder.Append(evt);
                    return ValueTask.CompletedTask;
                }, itemParameterId: "item");

        var events = recorder.Snapshot();
        Assert.False(result.Failed, string.Join(" | ", events.Where(evt => evt.Kind == ExecutionEventKinds.NodeFailed)
            .Select(evt => $"{evt.NodeId}:{evt.Data}:{evt.ScopeId}")));
        Assert.False(result.Cancelled);
        Assert.True(result.HasOutput);
        Assert.Equal(8, agents.Inputs.Length);
        Assert.Equal(4, events.Count(evt => evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "join"));
        Assert.Equal(8, events.Count(evt => evt.Kind == ExecutionEventKinds.ParallelJoinProgress && evt.NodeId == "join"));
        Assert.Equal(4, events.Count(evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
            evt.NodeId == "inner-loop"));
        Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
            evt.NodeId == "outer-loop"));
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Completed && evt.NodeId is null);

        for (var outerIndex = 0; outerIndex < 2; outerIndex++)
        for (var innerIndex = 0; innerIndex < 2; innerIndex++)
        {
            var scopeId = $"outer-loop/{outerIndex}/inner-loop/{innerIndex}";
            var scoped = events.Where(evt => evt.ScopeId == scopeId).ToArray();
            foreach (var agentId in new[] { "agent-left", "agent-right" })
            {
                var started = Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
                    evt.NodeId == agentId);
                Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
                    evt.NodeId == agentId && evt.InvocationId == started.InvocationId);
            }
            Assert.Equal(2, scoped.Count(evt => evt.Kind == ExecutionEventKinds.ParallelJoinProgress &&
                evt.NodeId == "join"));
            Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "join");
            Assert.Single(scoped, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
                evt.NodeId == "inner-loop");
        }

        AssertPersistedSequence(runStore, events, "completed");
        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        var playback = await RenderPlayback(reopened);
        Assert.Equal(4, CountOccurrences(playback, "Parallel join join · completed"));

        static int CountOccurrences(string text, string value) =>
            (text.Length - text.Replace(value, string.Empty, StringComparison.Ordinal).Length) / value.Length;
    }

