    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyNestedCoordinator_CallsPinnedWorkflowInEachNestedActivation(bool sqlite)
    {
        var childDefinition = new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "nested-array-passthrough-child", "input",
            ImmutableSortedDictionary<string, NodeDefinition>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("input", new(NodeTypes.Input, "1.0.0"))
                .Add("parse", new(NodeTypes.StringToInteger, "1.0.0"))
                .Add("format", new(NodeTypes.IntegerToString, "1.0.0"))
                .Add("output", new(NodeTypes.Output, "1.0.0")
                    { OutputDataType = WorkflowDataTypes.String }),
            ImmutableSortedDictionary<string, ConnectionDefinition>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("input-parse", new(new("input", "out"), new("parse", "in"), "data"))
                .Add("parse-format", new(new("parse", "out"), new("format", "in"), "data"))
                .Add("format-output", new(new("format", "out"), new("output", "in"), "data")))
        {
            ExecutionConnections = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("input-output", Edge("input", "then", "output", "execute"))
        };
        var child = WorkflowRevision.Create(childDefinition, "nested-array-passthrough-child-proof");
        var definition = new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "nested-array-workflow-call-proof", "input",
            ImmutableSortedDictionary<string, NodeDefinition>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("input", new(NodeTypes.Input, "1.0.0"))
                .Add("call", new NodeDefinition(NodeTypes.WorkflowCall, "1.0.0")
                {
                    WorkflowCall = new(child.Definition.WorkflowId, child.RevisionId, 1,
                        child.ContentHash, child.Definition)
                })
                .Add("output", new(NodeTypes.Output, "1.0.0")
                    { OutputDataType = WorkflowDataTypes.String }),
            ImmutableSortedDictionary<string, ConnectionDefinition>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("input-call", new(new("input", "out"), new("call", "in"), "data"))
                .Add("call-output", new(new("call", "out"), new("output", "in"), "data")))
        {
            ExecutionConnections = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("input-call", Edge("input", "then", "call", "execute"))
                .Add("call-output", Edge("call", "out", "output", "execute")),
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("item", new("Array item", string.Empty) { Type = WorkflowDataTypes.String })
                .Add("outerIndex", new("Outer array index", "0") { Type = WorkflowDataTypes.Integer })
                .Add("index", new("Inner array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        WorkflowValidator.ThrowIfInvalid(definition);
        var revision = WorkflowRevision.CreateProofOnly(definition,
            "nested-array-workflow-call-proof");
        const string outerItems = "[\"outer-a\",\"outer-b\"]";
        const string innerItems = "[\"1\",\"2\"]";
        using var runStore = new ProofRunStore(revision, outerItems, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);

        var result = await new WorkflowRunner().ExecuteProductionNestedBodyBreakSequenceProofAsync(
            runStore.RunId, revision, outerItems, innerItems, "outerIndex", "index", null,
            evt =>
            {
                recorder.Append(evt);
                return ValueTask.CompletedTask;
            }, itemParameterId: "item", proofBreakNodeIds: new HashSet<string>(StringComparer.Ordinal));

        var events = recorder.Snapshot();
        Assert.False(result.Failed, string.Join("\n", events.Select(evt =>
            $"{evt.Sequence} {evt.Kind} {evt.NodeId} {evt.ScopeId} {evt.Data}")));
        Assert.Equal("outer-a:1;2;outer-b:1;2", result.Output);
        Assert.Equal(4, events.Count(evt => evt.Kind == ExecutionEventKinds.SubworkflowStarted));

        foreach (var (outerIndex, itemIndex, item) in new[]
        {
            (0, 0, "1"), (0, 1, "2"), (1, 0, "1"), (1, 1, "2")
        })
        {
            var activationScope = $"outer-loop/{outerIndex}/inner-loop/{itemIndex}";
            var childScope = $"{activationScope}/call";
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SubworkflowStarted &&
                evt.ScopeId == childScope);
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SubworkflowCompleted &&
                evt.ScopeId == childScope && evt.Data == item);
            Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.SubworkflowEvidence &&
                evt.NodeId == "call" && evt.ScopeId == childScope));
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
                evt.NodeId == "inner-loop" && evt.ScopeId == activationScope);
        }

        AssertPersistedSequence(runStore, events, "completed");
        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("completed", reopened.Status);

        using var cancelledStore = new ProofRunStore(revision, outerItems, sqlite);
        var cancelledRecorder = new ProofRecorder(cancelledStore, startRoot: false);
        using var cancellation = new CancellationTokenSource();
        ValueTask RecordCancelled(ExecutionEvent evt)
        {
            cancelledRecorder.Append(evt);
            if (evt.Kind == ExecutionEventKinds.SubworkflowStarted &&
                evt.ScopeId == "outer-loop/0/inner-loop/0/call")
                cancellation.Cancel();
            return ValueTask.CompletedTask;
        }

        var cancelled = await new WorkflowRunner().ExecuteProductionNestedBodyBreakSequenceProofAsync(
            cancelledStore.RunId, revision, outerItems, innerItems, "outerIndex", "index", null,
            RecordCancelled, cancellation.Token, itemParameterId: "item",
            proofBreakNodeIds: new HashSet<string>(StringComparer.Ordinal));
        var cancelledEvents = cancelledRecorder.Snapshot();
        Assert.True(cancelled.Cancelled);
        Assert.False(cancelled.Failed);
        Assert.Single(cancelledEvents, evt => evt.Kind == ExecutionEventKinds.SubworkflowCancelled &&
            evt.ScopeId == "outer-loop/0/inner-loop/0/call");
        Assert.Contains(cancelledEvents, evt => evt.Kind == ExecutionEventKinds.SubworkflowEvidence &&
            evt.NodeId == "call" && evt.ScopeId == "outer-loop/0/inner-loop/0/call" &&
            WorkflowCallLifecycleEvidence.TryRead(evt.Data, out var evidence) &&
            evidence!.Lifecycle == ExecutionEventKinds.SubworkflowCancelled);
        Assert.DoesNotContain(cancelledEvents, evt => evt.ScopeId is
            "outer-loop/0/inner-loop/1" or "outer-loop/1" ||
            evt.ScopeId?.StartsWith("outer-loop/1/", StringComparison.Ordinal) == true);
        Assert.Single(cancelledEvents, evt => evt.Kind == ExecutionEventKinds.Cancelled && evt.NodeId is null);
        AssertPersistedSequence(cancelledStore, cancelledEvents, "cancelled");

        var reopenedCancelled = cancelledStore.ReopenStore().Get(cancelledStore.RunId)!;
        Assert.Equal(cancelledEvents, reopenedCancelled.Events);
        Assert.Equal("cancelled", reopenedCancelled.Status);

        using var failedStore = new ProofRunStore(revision, outerItems, sqlite);
        var failedRecorder = new ProofRecorder(failedStore, startRoot: false);
        const string failingInnerItems = "[\"invalid\",\"2\"]";
        var failed = await new WorkflowRunner().ExecuteProductionNestedBodyBreakSequenceProofAsync(
            failedStore.RunId, revision, outerItems, failingInnerItems, "outerIndex", "index", null,
            evt =>
            {
                failedRecorder.Append(evt);
                return ValueTask.CompletedTask;
            }, itemParameterId: "item", proofBreakNodeIds: new HashSet<string>(StringComparer.Ordinal));
        var failedEvents = failedRecorder.Snapshot();
        Assert.True(failed.Failed);
        Assert.False(failed.Cancelled);
        Assert.Single(failedEvents, evt => evt.Kind == ExecutionEventKinds.SubworkflowFailed &&
            evt.ScopeId == "outer-loop/0/inner-loop/0/call");
        Assert.Contains(failedEvents, evt => evt.Kind == ExecutionEventKinds.SubworkflowEvidence &&
            evt.NodeId == "call" && evt.ScopeId == "outer-loop/0/inner-loop/0/call" &&
            WorkflowCallLifecycleEvidence.TryRead(evt.Data, out var evidence) &&
            evidence!.Lifecycle == ExecutionEventKinds.SubworkflowFailed);
        Assert.Contains(failedEvents, evt => evt.Kind == ExecutionEventKinds.NodeFailed &&
            evt.NodeId == "parse" && evt.ScopeId == "outer-loop/0/inner-loop/0/call");
        Assert.DoesNotContain(failedEvents, evt => evt.ScopeId is
            "outer-loop/0/inner-loop/1" or "outer-loop/1" ||
            evt.ScopeId?.StartsWith("outer-loop/1/", StringComparison.Ordinal) == true);
        Assert.Single(failedEvents, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
        AssertPersistedSequence(failedStore, failedEvents, "failed");

        var reopenedFailed = failedStore.ReopenStore().Get(failedStore.RunId)!;
        Assert.Equal(failedEvents, reopenedFailed.Events);
        Assert.Equal("failed", reopenedFailed.Status);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyNestedCoordinator_SettlesParallelPinnedChildPerActivation(bool sqlite)
    {
        var revision = NestedParallelWorkflowCallRevision();
        const string outerItems = "[\"outer-a\"]";
        const string innerItems = "[\"one\"]";
        using var runStore = new ProofRunStore(revision, outerItems, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var agents = new ControlledForkPathAgentExecutor();
        var leftAgentCompleted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var execution = new WorkflowRunner(agents: agents)
            .ExecuteProductionNestedBodyBreakSequenceProofAsync(runStore.RunId, revision,
                outerItems, innerItems, "outerIndex", "index", null, evt =>
                {
                    recorder.Append(evt);
                    if (evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "agent-left")
                        leftAgentCompleted.TrySetResult();
                    return ValueTask.CompletedTask;
                }, itemParameterId: "item",
                proofBreakNodeIds: new HashSet<string>(StringComparer.Ordinal));
        try
        {
            await Task.WhenAll(agents.RightStarted.Task, leftAgentCompleted.Task)
                .WaitAsync(TimeSpan.FromSeconds(5));
            Assert.False(execution.IsCompleted,
                "The nested WorkflowCall must remain open until its admitted parallel child settles.");
            var childScope = "outer-loop/0/inner-loop/0/call";
            Assert.DoesNotContain(recorder.Snapshot(), evt =>
                evt.Kind == ExecutionEventKinds.NodeCompleted && evt.NodeId == "agent-right" &&
                evt.ScopeId == childScope);
            Assert.DoesNotContain(recorder.Snapshot(), evt =>
                evt.Kind == ExecutionEventKinds.SubworkflowCompleted && evt.ScopeId == childScope);
            Assert.DoesNotContain(recorder.Snapshot(), evt =>
                evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
                evt.ScopeId == "outer-loop/0/inner-loop/0");
            agents.ReleaseRight.TrySetResult();
            var result = await execution;
            Assert.False(result.Failed, string.Join("\n", recorder.Snapshot().Select(evt =>
                $"{evt.Sequence} {evt.Kind} {evt.NodeId} {evt.ScopeId} {evt.Data}")));
        }
        finally
        {
            agents.ReleaseRight.TrySetResult();
            if (!execution.IsCompleted)
                await execution.WaitAsync(TimeSpan.FromSeconds(5));
        }

        var events = recorder.Snapshot();
        const string activationScope = "outer-loop/0/inner-loop/0";
        const string completedChildScope = activationScope + "/call";
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SubworkflowStarted &&
            evt.ScopeId == completedChildScope);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SubworkflowCompleted &&
            evt.ScopeId == completedChildScope);
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
            evt.NodeId == "agent-left" && evt.ScopeId == completedChildScope);
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
            evt.NodeId == "agent-right" && evt.ScopeId == completedChildScope);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
            evt.NodeId == "inner-loop" && evt.ScopeId == activationScope);

        AssertPersistedSequence(runStore, events, "completed");
        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Equal("completed", reopened.Status);
        Assert.True(WorkflowCallEvidence.TryReconstructPlayback(reopened.Events, out var calls));
        Assert.Equal(1, calls!.Calls.Count(call => call.State == "completed"));
    }

    private static WorkflowRevision NestedParallelWorkflowCallRevision()
    {
        var childDefinition = ParallelBodyDefinition() with
        {
            WorkflowId = "nested-array-parallel-child"
        };
        WorkflowValidator.ThrowIfInvalid(childDefinition);
        var child = WorkflowRevision.Create(childDefinition, "nested-array-parallel-child-proof");
        var nodes = ImmutableSortedDictionary<string, NodeDefinition>.Empty.WithComparers(StringComparer.Ordinal)
            .Add("input", new(NodeTypes.Input, "1.0.0"))
            .Add("call", new(NodeTypes.WorkflowCall, "1.0.0")
            {
                WorkflowCall = new(child.Definition.WorkflowId, child.RevisionId, 1,
                    child.ContentHash, child.Definition)
            })
            .Add("output", new(NodeTypes.Output, "1.0.0")
                { OutputDataType = WorkflowDataTypes.Json });
        var definition = new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "nested-array-parallel-workflow-call-proof", "input", nodes,
            ImmutableSortedDictionary<string, ConnectionDefinition>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("input-call", new(new("input", "out"), new("call", "in"), "data"))
                .Add("call-output", new(new("call", "out"), new("output", "in"), "data")))
        {
            ExecutionConnections = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("input-call", Edge("input", "then", "call", "execute"))
                .Add("call-output", Edge("call", "out", "output", "execute")),
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("item", new("Array item", string.Empty) { Type = WorkflowDataTypes.String })
                .Add("outerIndex", new("Outer array index", "0") { Type = WorkflowDataTypes.Integer })
                .Add("index", new("Inner array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        WorkflowValidator.ThrowIfInvalid(definition);
        return WorkflowRevision.CreateProofOnly(definition,
            "nested-array-parallel-workflow-call-proof");
    }

    private static WorkflowRevision NestedParallelWorkflowInterfaceCallRevision()
    {
        var childBody = ParallelBodyDefinition();
        var childNodes = childBody.Nodes
            .SetItem("input", childBody.Nodes["input"] with { InputDataType = WorkflowDataTypes.Json })
            .Add("select-left", new NodeDefinition(NodeTypes.JsonSelectString, "1.0.0")
                { JsonPropertySelection = new("/value") })
            .Add("select-right", new NodeDefinition(NodeTypes.JsonSelectString, "1.0.0")
                { JsonPropertySelection = new("/value") })
            .Add("project", new NodeDefinition(NodeTypes.JsonProject, "1.0.0")
            {
                JsonProjection = new([new JsonProjectionField("value", "/left")
                    { ValueType = WorkflowDataTypes.String }])
            });
        var childData = childBody.Connections
            .Remove("input-left")
            .Remove("input-right")
            .Remove("join-output")
            .Add("input-select-left", new(new("input", "out"), new("select-left", "in"), "data"))
            .Add("input-select-right", new(new("input", "out"), new("select-right", "in"), "data"))
            .Add("select-left-agent", new(new("select-left", "out"), new("agent-left", "in"), "data"))
            .Add("select-right-agent", new(new("select-right", "out"), new("agent-right", "in"), "data"))
            .Add("join-project", new(new("join", "out"), new("project", "in"), "data"))
            .Add("project-output", new(new("project", "out"), new("output", "in"), "data"));
        var childExecution = childBody.ExecutionConnections!;
        var childDefinition = childBody with
        {
            WorkflowId = "nested-array-parallel-interface-child",
            Nodes = childNodes,
            Connections = childData,
            ExecutionConnections = childExecution
        };
        WorkflowValidator.ThrowIfInvalid(childDefinition);
        var child = WorkflowRevision.Create(childDefinition, "nested-array-parallel-interface-child-proof");
        var operation = new WorkflowInterfaceOperation("Echo", WorkflowDataTypes.Json,
            WorkflowDataTypes.Json)
        {
            Inputs = [new("value", "Value", WorkflowDataTypes.String)],
            Outputs = [new("value", "Value", WorkflowDataTypes.String)]
        };
        var contract = WorkflowInterfaceRevision.Create(new WorkflowInterfaceDefinition(
            "array-iteration.parallel-echo", "Parallel echo", "Runs both parallel echo branches.",
            ImmutableSortedDictionary<string, WorkflowInterfaceOperation>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("echo", operation))
        { SchemaVersion = WorkflowInterfaceJson.FieldContractSchemaVersion });
        var implementation = WorkflowInterfaceImplementationRevision.Create(new WorkflowInterfaceImplementation(
            "array-iteration.parallel-echo-implementation", contract,
            ImmutableSortedDictionary<string, WorkflowInterfaceWorkflowPin>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("echo", WorkflowInterfaceWorkflowPin.From(new PublishedWorkflowRevision(1, child)))));
        var nodes = ImmutableSortedDictionary<string, NodeDefinition>.Empty.WithComparers(StringComparer.Ordinal)
            .Add("input", new(NodeTypes.Input, "1.0.0"))
            .Add("call", new NodeDefinition(NodeTypes.WorkflowInterfaceCall, "1.0.0")
            {
                WorkflowInterfaceCall = new(implementation, "echo")
            })
            .Add("output", new(NodeTypes.Output, "1.0.0")
                { OutputDataType = WorkflowDataTypes.String });
        var definition = new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "nested-array-parallel-interface-call-proof", "input", nodes,
            ImmutableSortedDictionary<string, ConnectionDefinition>.Empty.WithComparers(StringComparer.Ordinal)
                .Add("input-call", new(new("input", "out"), new("call", "value"), "data"))
                .Add("call-output", new(new("call", "value"), new("output", "in"), "data")))
        {
            ExecutionConnections = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("input-call", Edge("input", "then", "call", "execute"))
                .Add("call-output", Edge("call", "then", "output", "execute")),
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .WithComparers(StringComparer.Ordinal)
                .Add("item", new("Array item", string.Empty) { Type = WorkflowDataTypes.String })
                .Add("outerIndex", new("Outer array index", "0") { Type = WorkflowDataTypes.Integer })
                .Add("index", new("Inner array index", "0") { Type = WorkflowDataTypes.Integer })
        };
        WorkflowValidator.ThrowIfInvalid(definition);
        return WorkflowRevision.CreateProofOnly(definition,
            "nested-array-parallel-interface-call-proof");
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ProductionBodyNestedCoordinator_ParallelPinnedChildFailureStopsLaterActivations(bool sqlite)
    {
        var revision = NestedParallelWorkflowCallRevision();
        const string outerItems = "[\"outer-a\",\"outer-b\"]";
        const string innerItems = "[\"one\",\"two\"]";
        using var runStore = new ProofRunStore(revision, outerItems, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);

        var result = await new WorkflowRunner(agents: new EchoAgentExecutor(failNodeId: "agent-right"))
            .ExecuteProductionNestedBodyBreakSequenceProofAsync(runStore.RunId, revision,
                outerItems, innerItems, "outerIndex", "index", null, evt =>
                {
                    recorder.Append(evt);
                    return ValueTask.CompletedTask;
                }, itemParameterId: "item",
                proofBreakNodeIds: new HashSet<string>(StringComparer.Ordinal));

        var events = recorder.Snapshot();
        Assert.True(result.Failed);
        Assert.False(result.Cancelled);
        const string childScope = "outer-loop/0/inner-loop/0/call";
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SubworkflowFailed &&
            evt.ScopeId == childScope);
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.NodeFailed &&
            evt.NodeId == "agent-right" && evt.ScopeId == childScope);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.SubworkflowCompleted &&
            evt.ScopeId == childScope);
        Assert.DoesNotContain(events, evt => evt.ScopeId == "outer-loop/0/inner-loop/1" ||
            evt.ScopeId?.StartsWith("outer-loop/0/inner-loop/1/", StringComparison.Ordinal) == true ||
            evt.ScopeId == "outer-loop/1" ||
            evt.ScopeId?.StartsWith("outer-loop/1/", StringComparison.Ordinal) == true);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
        AssertPersistedSequence(runStore, events, "failed");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.True(WorkflowCallEvidence.TryReconstructPlayback(reopened.Events, out var calls));
        Assert.Equal("failed", calls!.Status);
        Assert.Equal("failed", Assert.Single(calls.Calls).State);
    }

