        Assert.Equal(2, baseline.ProviderCalls);
        Assert.Equal(2, baseline.Events.Count(evt => evt.Kind == ExecutionEventKinds.ModelResponded));
        Assert.Single(baseline.Events, evt => evt.Kind == ExecutionEventKinds.Completed && evt.NodeId is null);

        var secondRequest = requests[1];
        var prefix = baseline.Events.Where(evt => evt.Sequence < secondRequest.Sequence).ToArray();
        var prefixBytes = prefix.Sum(EventBytes);
        var iterationReservationBytes = prefix
            .Where(evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted)
            .Where(start => !prefix.Any(evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted &&
                evt.NodeId == start.NodeId && evt.InvocationId == start.InvocationId &&
                evt.ScopeId == start.ScopeId))
            .Sum(IterationSettlementReservationBytes);
        const long maximumOutcomeBytes = 32_000;
        const long reservedFailureBytes = 64_000;
        const long byteAdmissionMargin = 4_096;
        var maximumBytes = checked(prefixBytes + EventBytes(secondRequest) +
            (2 * maximumOutcomeBytes) + iterationReservationBytes + reservedFailureBytes - byteAdmissionMargin);

        var limited = await ExecuteAsync(maximumBytes);
        Assert.True(limited.Result.Failed);
        Assert.Equal(1, limited.ProviderCalls);
        Assert.Single(limited.Events, evt => evt.Kind == ExecutionEventKinds.ModelRequested);
        Assert.Single(limited.Events, evt => evt.Kind == ExecutionEventKinds.NodeFailed && evt.NodeId == "agent");
        Assert.Single(limited.Events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
        Assert.DoesNotContain(limited.Events, evt => evt.Kind == ExecutionEventKinds.Completed && evt.NodeId is null);
        Assert.Equal(2, limited.Events.Count(evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted));
        Assert.Contains("Latest run status: failed", limited.Playback, StringComparison.Ordinal);

        var reservationLimited = await ExecuteAsync(maximumBytes: 4_000_000,
            maximumConcurrentOutcomeReservations: 1);
        Assert.True(reservationLimited.Result.Failed);
        Assert.Equal(1, reservationLimited.ProviderCalls);
        Assert.Single(reservationLimited.Events, evt => evt.Kind == ExecutionEventKinds.ModelRequested);
        Assert.Single(reservationLimited.Events, evt => evt.Kind == ExecutionEventKinds.NodeFailed && evt.NodeId == "agent");
        Assert.Single(reservationLimited.Events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
        Assert.Contains("Latest run status: failed", reservationLimited.Playback, StringComparison.Ordinal);

        async Task<(ExecutionEvent[] Events, int ProviderCalls, WorkflowExecutionResult Result, string Playback)>
            ExecuteAsync(long maximumBytes, int maximumConcurrentOutcomeReservations = 2)
        {
            const string providerId = "proof.concurrent-model-byte-budget";
            const string input = "[\"first\",\"second\"]";
            const string response = "done";
            var definition = new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
                "concurrent-array-shared-model-byte-budget", "input",
                ImmutableSortedDictionary<string, NodeDefinition>.Empty
                    .Add("input", new(NodeTypes.Input, "1.0.0"))
                    .Add("agent", new(NodeTypes.Agent, "1.0.0",
                        Agent: new(providerId, null, "Return a short result.", [])))
                    .Add("output", new(NodeTypes.Output, "1.0.0")),
                ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
                    .Add("input-agent", new(new("input", "out"), new("agent", "in"), "data"))
                    .Add("agent-output", new(new("agent", "out"), new("output", "in"), "data")))
            {
                Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                    .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer }),
                ExecutionConnections = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
                    .Add("input-agent", Edge("input", "then", "agent", "execute"))
                    .Add("agent-output", Edge("agent", "out", "output", "execute"))
            };
            var revision = WorkflowRevision.CreateProofOnly(definition,
                "concurrent-array-shared-model-byte-budget-proof");
            using var store = new ProofRunStore(revision, input, sqlite);
            var recorder = new ProofRecorder(store, startRoot: false);
            var budgetRejected = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
            var model = new ConcurrentPromptModel(expectedConcurrentCalls: 2,
                releaseOnReservationRejected: budgetRejected.Task, responseText: response);
            var provider = new AgentProviderDescriptor(providerId, "Model byte reservation proof", "proof-chat-v1", true);
            var agents = new AgentNodeExecutor(
                [new AgentProviderRegistration(provider, () => new SynchronizedResponseChatClient(model))],
                new EchoToolBroker());

            ValueTask Record(ExecutionEvent evt)
            {
                recorder.Append(evt);
                if (evt.Kind == ExecutionEventKinds.NodeFailed && evt.NodeId == "agent")
                    budgetRejected.TrySetResult();
                return ValueTask.CompletedTask;
            }

            var result = await new WorkflowRunner(agents: agents)
                .ExecuteProductionConcurrentBodyBreakSequenceProofAsync(store.RunId, revision, input,
                    "index", null, Record, runBudget: StructuredRunBudget(maximumToolDispatches: 1) with
                    {
                        MaximumBytes = maximumBytes,
                        MaximumConcurrentOutcomeReservations = maximumConcurrentOutcomeReservations
                    });
            var events = recorder.Snapshot();
            Assert.True(events.Sum(EventBytes) <= maximumBytes);
            AssertPersistedSequence(store, events, result.Failed ? "failed" : "completed");
            var reopened = store.ReopenStore().Get(store.RunId)!;
            Assert.Equal(events, reopened.Events);
            return (events, model.Calls.Length, result, await RenderPlayback(reopened));
        }
    }

    [Theory]
    [InlineData(false, "events")]
    [InlineData(true, "events")]
    [InlineData(false, "bytes")]
    [InlineData(true, "bytes")]
    [InlineData(false, "admission")]
    [InlineData(true, "admission")]
    public async Task ConcurrentProductionBodyCoordinator_ReservesIterationSettlementBeforeBodyBudget(bool sqlite,
        string constrainedBudget)
    {
        var revision = WorkflowRevision.Create(BodyDefinition(includeVariableStore: true, includeIndexParameter: true),
            $"concurrent-production-array-settlement-reservation-{constrainedBudget}-proof");
        const string input = "[\"first\"]";
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var model = new SharedBudgetProofModel();
        var provider = new AgentProviderDescriptor("proof.echo-agent", "Proof model", "proof-chat-v1", true);
        var agents = new AgentNodeExecutor(
            [new AgentProviderRegistration(provider, () => new SharedBudgetProofChatClient(model))],
            new EchoToolBroker());
        var budget = StructuredRunBudget(maximumToolDispatches: 1) with
        {
            MaximumEvents = constrainedBudget switch { "events" => 12, "admission" => 10, _ => 512 },
            MaximumBytes = constrainedBudget == "bytes" ? 95_000 : 4_000_000
        };

        var result = await new WorkflowRunner(agents: agents)
            .ExecuteProductionConcurrentBodyBreakSequenceProofAsync(runStore.RunId, revision, input,
                "index", null, evt =>
                {
                    recorder.Append(evt);
                    return ValueTask.CompletedTask;
                }, runBudget: budget, maximumConcurrentBodies: 1);

        var events = recorder.Snapshot();
        Assert.True(result.Failed);
        Assert.Equal(0, model.Calls);
        if (constrainedBudget == "admission")
        {
            Assert.DoesNotContain(events, evt => evt.Kind is ExecutionEventKinds.LoopIterationStarted or
                ExecutionEventKinds.LoopIterationCompleted or ExecutionEventKinds.NodeStarted);
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
            AssertPersistedSequence(runStore, events, "failed");
            var rejected = runStore.ReopenStore().Get(runStore.RunId)!;
            Assert.Equal(events, rejected.Events);
            return;
        }

        var start = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted);
        var completion = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.LoopIterationCompleted);
        Assert.Equal(start.NodeId, completion.NodeId);
        Assert.Equal(start.InvocationId, completion.InvocationId);
        Assert.Equal(start.ScopeId, completion.ScopeId);
        using (var outcome = JsonDocument.Parse(completion.Data!))
            Assert.Equal("failed", outcome.RootElement.GetProperty("outcome").GetString());
        Assert.Contains(events, evt => evt.Kind == ExecutionEventKinds.NodeFailed && evt.ScopeId == start.ScopeId);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.ModelRequested);
        AssertPersistedSequence(runStore, events, "failed");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Contains("Iteration 1 · Failed", await RenderPlayback(reopened), StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(false, "tool-dispatches")]
    [InlineData(true, "tool-dispatches")]
    [InlineData(false, "outcome-reservations")]
    [InlineData(true, "outcome-reservations")]
    public async Task ConcurrentProductionBodyCoordinator_SharesToolAdmissionBudgets(bool sqlite,
        string constrainedBudget)
    {
        const string bindingId = "proof.concurrent-tool-budget";
        const string input = "[\"first\",\"second\",\"must-not-run\"]";
        var definition = new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "concurrent-array-shared-tool-budget", "input",
            ImmutableSortedDictionary<string, NodeDefinition>.Empty
                .Add("input", new(NodeTypes.Input, "1.0.0"))
                .Add("tool", new(NodeTypes.McpTool, "1.0.0",
                    new ToolBindingRequest(bindingId, new string('d', 64)))
                {
                    McpInputPorts = [new("arg.query", "query", WorkflowDataTypes.String, true)],
                    McpArgumentsJson = "{}"
                })
                .Add("output", new(NodeTypes.Output, "1.0.0")),
            ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
                .Add("input-query", new(new("input", "out"), new("tool", "arg.query"), "data"))
                .Add("tool-result", new(new("tool", "out"), new("output", "in"), "data")))
        {
            Parameters = ImmutableSortedDictionary<string, WorkflowParameterDefinition>.Empty
                .Add("index", new("Array index", "0") { Type = WorkflowDataTypes.Integer }),
            ExecutionConnections = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
                .Add("input-tool", Edge("input", "then", "tool", "execute"))
                .Add("tool-output", Edge("tool", "then", "output", "execute"))
        };
        Assert.Empty(WorkflowValidator.Validate(definition));
        var revision = WorkflowRevision.CreateProofOnly(definition,
            "concurrent-array-shared-tool-budget-proof");
        using var runStore = new ProofRunStore(revision, input, sqlite);
        var recorder = new ProofRecorder(runStore, startRoot: false);
        var broker = new ControlledSettlementToolBroker(bindingId, ControlledToolOutcome.Success);
        var budgetRejected = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);

        ValueTask Record(ExecutionEvent evt)
        {
            recorder.Append(evt);
            if (evt.Kind == ExecutionEventKinds.NodeFailed && evt.NodeId == "tool")
                budgetRejected.TrySetResult();
            return ValueTask.CompletedTask;
        }

        var budget = StructuredRunBudget(maximumToolDispatches:
            constrainedBudget == "tool-dispatches" ? 1 : 2) with
        {
            MaximumConcurrentOutcomeReservations = constrainedBudget == "outcome-reservations" ? 1 : 2
        };
        var execution = new WorkflowRunner(tools: broker)
            .ExecuteProductionConcurrentBodyBreakSequenceProofAsync(runStore.RunId, revision,
                input, "index", null, Record, runBudget: budget);
        try
        {
            await Task.WhenAll(broker.DispatchStarted.Task, budgetRejected.Task)
                .WaitAsync(TimeSpan.FromSeconds(5));
        }
        finally
        {
            broker.ReleaseOutcome.TrySetResult();
        }

        var result = await execution.WaitAsync(TimeSpan.FromSeconds(5));
        var events = recorder.Snapshot();
        var authorization = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolAuthorized &&
            evt.NodeId == "tool");
        var completion = Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.ToolCompleted &&
            evt.NodeId == "tool");
        Assert.Equal(authorization.ScopeId, completion.ScopeId);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeFailed && evt.NodeId == "tool" &&
            evt.ScopeId != authorization.ScopeId);
        Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.LoopIterationStarted));
        Assert.DoesNotContain(events, evt => evt.ScopeId == "array-loop/2");
        Assert.True(result.Failed);
        Assert.False(result.Cancelled);
        Assert.Equal(1, events.Count(evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null));
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.Completed && evt.NodeId is null);
        AssertPersistedSequence(runStore, events, "failed");

        var reopened = runStore.ReopenStore().Get(runStore.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.Contains("Latest run status: failed", await RenderPlayback(reopened), StringComparison.Ordinal);
    }

