    [Theory]
    [InlineData(false, true)]
    [InlineData(false, false)]
    [InlineData(true, true)]
    [InlineData(true, false)]
    public async Task SequenceBranchMergeBreakPlayback_ReopensSamePrefix(bool sqlite, bool condition)
    {
        var revision = WorkflowRunner.CreateSequenceBranchDecisionEvidenceProofRevision(condition);
        using var store = new ProofRunStore(revision, "route input", sqlite);
        var recorder = new ProofRecorder(store, startRoot: false);

        var result = await new WorkflowRunner().ExecuteSequenceBranchDecisionEvidenceProofAsync(
            store.RunId, revision, "route input", evt =>
            {
                recorder.Append(evt);
                return ValueTask.CompletedTask;
            });

        Assert.False(result.Failed);
        if (recorder.Snapshot().Last().Kind != ExecutionEventKinds.Completed)
            recorder.CompleteRoot();
        var events = recorder.Snapshot();
        var reopened = store.ReopenStore().Get(store.RunId)!;
        Assert.Equal("completed", reopened.Status);
        Assert.Equal(events, reopened.Events);
        Assert.Equal(Enumerable.Range(1, events.Length).Select(index => (long)index),
            events.Select(evt => evt.Sequence));
        Assert.True(SequenceEvidence.TryReconstructPlayback(reopened.Events, out var playback));
        Assert.Equal(condition ? "completed" : "break-completed", playback!.Status);
        var expectedStates = condition ? new[] { "completed", "completed" } : ["completed", "skipped"];
        Assert.Equal(expectedStates, playback.Outputs.Select(output => output.State));
    }

    [Theory]
    [InlineData(false, true, false)]
    [InlineData(false, false, false)]
    [InlineData(true, true, false)]
    [InlineData(true, false, false)]
    [InlineData(false, true, true)]
    [InlineData(false, false, true)]
    [InlineData(true, true, true)]
    [InlineData(true, false, true)]
    public async Task SequenceBranchMergeToolOutcomesCannotBeHiddenByLaterRoute(bool sqlite, bool condition,
        bool outcomeUnknown)
    {
        const string bindingId = "proof.sequence-branch-tool";
        var revision = WorkflowRunner.CreateSequenceBranchDecisionToolOutcomeProofRevision(condition);
        using var store = new ProofRunStore(revision, "route input", sqlite);
        var recorder = new ProofRecorder(store, startRoot: false);
        var tools = new ControlledSettlementToolBroker(bindingId,
            outcomeUnknown ? ControlledToolOutcome.Unknown : ControlledToolOutcome.Failure);
        var execution = new WorkflowRunner(tools: tools).ExecuteSequenceBranchDecisionToolOutcomeProofAsync(
            store.RunId, revision, "route input", evt =>
            {
                recorder.Append(evt);
                return ValueTask.CompletedTask;
            }).WaitAsync(TimeSpan.FromSeconds(10));

        WorkflowExecutionResult? result = null;
        try
        {
            await tools.DispatchStarted.Task.WaitAsync(TimeSpan.FromSeconds(5));
            tools.ReleaseOutcome.TrySetResult();
            try
            {
                result = await execution;
            }
            catch (InvalidOperationException exception) when (!outcomeUnknown &&
                exception.Message == "Executor tool failed.")
            {
                // Agent Framework reports a fatal executor exception through the run stream.
            }
        }
        finally
        {
            tools.ReleaseOutcome.TrySetResult();
            if (!execution.IsCompleted)
            {
                try { await execution.WaitAsync(TimeSpan.FromSeconds(5)); }
                catch (TimeoutException) { }
            }
        }

        var events = recorder.Snapshot();
        var expectedRunStatus = outcomeUnknown ? "outcome-unknown" : "failed";
        Assert.Equal(outcomeUnknown, result?.OutcomeUnknown == true);
        Assert.Contains(events, evt => evt.Kind == (outcomeUnknown
            ? ExecutionEventKinds.OutcomeUnknown
            : ExecutionEventKinds.Failed) && evt.NodeId is null);
        AssertPersistedSequence(store, events, expectedRunStatus);
        Assert.Single(events, evt => evt.Kind == (outcomeUnknown
            ? ExecutionEventKinds.ToolUncertain
            : ExecutionEventKinds.ToolFailed) && evt.NodeId == "tool");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.BranchSelected && evt.NodeId == "branch");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeStarted && evt.NodeId == "merge");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputFailed &&
            SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "decision");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
            SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "suffix");
        Assert.DoesNotContain(events, evt => evt.Kind is ExecutionEventKinds.SequenceOutputCompleted or
            ExecutionEventKinds.SequenceBreakCompleted or ExecutionEventKinds.SequenceCompleted);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
            evt.NodeId is "outcome" or "output" or "suffix-output");

        var reopened = store.ReopenStore().Get(store.RunId)!;
        Assert.Equal(expectedRunStatus, reopened.Status);
        Assert.Equal(events, reopened.Events);
        Assert.True(SequenceEvidence.TryReconstructPlayback(reopened.Events, out var playback));
        Assert.Equal("failed", playback!.Status);
        Assert.Equal(["failed", "skipped"], playback.Outputs.Select(output => output.State));
    }

    [Theory]
    [InlineData(false, true)]
    [InlineData(false, false)]
    [InlineData(true, true)]
    [InlineData(true, false)]
    public async Task SequenceBranchMergeHostCancellationCannotBeHiddenByLaterRoute(bool sqlite, bool condition)
    {
        var revision = WorkflowRunner.CreateSequenceBranchDecisionCancellationProofRevision(condition);
        using var store = new ProofRunStore(revision, "route input", sqlite);
        var recorder = new ProofRecorder(store, startRoot: false);
        var agents = new ControlledSettlementAgentExecutor("agent");
        using var cancellation = new CancellationTokenSource();
        var execution = new WorkflowRunner(agents: agents).ExecuteSequenceBranchDecisionCancellationProofAsync(
            store.RunId, revision, "route input", evt =>
            {
                recorder.Append(evt);
                return ValueTask.CompletedTask;
            }, cancellation.Token).WaitAsync(TimeSpan.FromSeconds(10));

        try
        {
            await agents.Started.Task.WaitAsync(TimeSpan.FromSeconds(5));
            var beforeCancellation = recorder.Snapshot();
            Assert.Contains(beforeCancellation, evt => evt.Kind == ExecutionEventKinds.BranchSelected && evt.NodeId == "branch");
            Assert.Contains(beforeCancellation, evt => evt.Kind == ExecutionEventKinds.NodeStarted && evt.NodeId == "merge");
            Assert.Contains(beforeCancellation, evt => evt.Kind == ExecutionEventKinds.NodeStarted && evt.NodeId == "agent");
            cancellation.Cancel();
            await Assert.ThrowsAnyAsync<OperationCanceledException>(async () => await execution);
        }
        finally
        {
            agents.Release.TrySetResult();
            if (!execution.IsCompleted)
            {
                try { await execution.WaitAsync(TimeSpan.FromSeconds(5)); }
                catch (OperationCanceledException) { }
                catch (TimeoutException) { }
            }
        }

        var events = recorder.Snapshot();
        AssertPersistedSequence(store, events, "cancelled");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.NodeCancelled && evt.NodeId == "agent");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Cancelled && evt.NodeId is null);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputCancelled &&
            SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "decision");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
            SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "suffix");
        Assert.DoesNotContain(events, evt => evt.Kind is ExecutionEventKinds.SequenceOutputCompleted or
            ExecutionEventKinds.SequenceBreakCompleted or ExecutionEventKinds.SequenceCompleted);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
            evt.NodeId is "outcome" or "output" or "suffix-output");

        var reopened = store.ReopenStore().Get(store.RunId)!;
        Assert.Equal("cancelled", reopened.Status);
        Assert.Equal(events, reopened.Events);
        Assert.True(SequenceEvidence.TryReconstructPlayback(reopened.Events, out var playback));
        Assert.Equal("cancelled", playback!.Status);
        Assert.Equal(["cancelled", "skipped"], playback.Outputs.Select(output => output.State));
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task SingleStreamSequenceProof_AdmitsBreakWhileEarlierAgentIsActive(bool sqlite)
    {
        var body = SequenceBodyDefinition();
        var nodes = body.Nodes
            .SetItem("sequence", body.Nodes["sequence"] with
            {
                Sequence = new([new("inventory", "Inventory"), new("architecture", "Architecture"),
                    new("quality", "Quality")])
            })
            .SetItem("inventory-tool", new NodeDefinition(NodeTypes.Agent, "1.0.0",
                Agent: new AgentConfiguration("proof.settlement", null, "Wait for release.", []) { MaxTurns = 1 }))
            .SetItem("architecture-tool", new(WorkflowRunner.StructuredProofBreakNodeType, "proof-only"))
            .Add("quality-tool", new(NodeTypes.McpTool, "1.0.0",
                new ToolBindingRequest("proof.quality", new string('c', 64)))
            { McpArgumentsJson = "{\"query\":\"must-not-run\"}" });
        var definition = body with
        {
            Nodes = nodes,
            ExecutionConnections = body.ExecutionConnections!
                .SetItem("inventory-output", Edge("inventory-tool", "out", "output", "execute"))
                .SetItem("architecture-output", Edge("architecture-tool", "out", "output", "execute"))
                .Add("sequence-quality", Edge("sequence", "then.quality", "quality-tool", "execute"))
                .Add("quality-output", Edge("quality-tool", "then", "output", "execute"))
        };
        var revision = WorkflowRevision.CreateProofOnly(definition, "single-stream-sequence-break-proof");
        using var store = new ProofRunStore(revision, "research", sqlite);
        var recorder = new ProofRecorder(store, startRoot: false);
        var agents = new ControlledSettlementAgentExecutor("inventory-tool");
        var breakAdmissionClosed = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        ValueTask Record(ExecutionEvent evt)
        {
            recorder.Append(evt);
            if (evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
                SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "quality")
                breakAdmissionClosed.TrySetResult();
            return ValueTask.CompletedTask;
        }

        var execution = new WorkflowRunner(tools: new EchoToolBroker(), agents: agents)
            .ExecuteSingleStreamSequenceBreakProofAsync(store.RunId, revision, "research", Record,
                new HashSet<string>(["architecture-tool"], StringComparer.Ordinal),
                cancellationToken: CancellationToken.None, maximumConcurrentOutputs: 2)
            .WaitAsync(TimeSpan.FromSeconds(10));
        try
        {
            try { await agents.Started.Task.WaitAsync(TimeSpan.FromSeconds(5)); }
            catch (TimeoutException)
            {
                var recorded = recorder.Snapshot();
                throw new Xunit.Sdk.XunitException("The first admitted Agent did not start. Execution completed: " +
                    execution.IsCompleted + ". Events: " + string.Join(" | ", recorded.Select(evt =>
                        $"{evt.Kind}:{evt.NodeId}:{evt.Data}")));
            }
            try { await breakAdmissionClosed.Task.WaitAsync(TimeSpan.FromSeconds(5)); }
            catch (TimeoutException)
            {
                throw new Xunit.Sdk.XunitException("Break admission did not close. Events: " +
                    string.Join(" | ", recorder.Snapshot().Select(evt => $"{evt.Kind}:{evt.NodeId}:{evt.Data}")));
            }
            var duringBreak = recorder.Snapshot();
            Assert.False(execution.IsCompleted,
                "The single production stream must stay open until the admitted Agent settles.");
            Assert.Equal(["inventory", "architecture"], duringBreak
                .Where(evt => evt.Kind == ExecutionEventKinds.SequenceOutputDispatched)
                .Select(evt => SequenceEvidence.TryRead(evt, out var evidence) ? evidence?.OutputId : null));
            Assert.Contains(duringBreak, evt => evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
                SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "quality");
            Assert.DoesNotContain(duringBreak, evt => evt.Kind == ExecutionEventKinds.NodeStarted &&
                evt.NodeId == "quality-tool");
            Assert.All(duringBreak, evt => Assert.Equal(revision.RevisionId, evt.RevisionId));
            Assert.Equal(duringBreak.Select(evt => evt.Sequence).Order().Distinct(),
                duringBreak.Select(evt => evt.Sequence));

            agents.Release.TrySetResult();
            var result = await execution;
            var events = recorder.Snapshot();
            Assert.False(result.Failed);
            Assert.Equal("{\"query\":\"research\"}", result.Output);
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakCompleted);
            Assert.Equal(2, events.Count(evt => evt.Kind == ExecutionEventKinds.SequenceOutputCompleted));
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputSkipped);
            Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Completed && evt.NodeId is null);
            AssertPersistedSequence(store, events, "completed");
            var reopened = store.ReopenStore().Get(store.RunId)!;
            Assert.Equal(events, reopened.Events);
            Assert.True(SequenceEvidence.TryReconstructPlayback(reopened.Events, out var playback),
                string.Join(" | ", reopened.Events.Where(evt => SequenceEvidence.IsLifecycleEvent(evt.Kind))
                    .Select(evt => $"{evt.Sequence}:{evt.Kind}:{evt.NodeId}:{evt.InvocationId}:{evt.ConnectionId}:{evt.Data}")));
            Assert.Equal("break-completed", playback!.Status);
            Assert.Equal(["inventory", "architecture", "quality"],
                playback.Outputs.Select(output => output.OutputId));
        }
        finally
        {
            agents.Release.TrySetResult();
            if (!execution.IsCompleted)
            {
                try { await execution.WaitAsync(TimeSpan.FromSeconds(5)); }
                catch (TimeoutException) { }
            }
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task SingleStreamSequenceProof_AdmissionWinsAgainstGraphBreakAndDrains(bool sqlite)
    {
        var body = SequenceBodyDefinition();
        var nodes = body.Nodes
            .SetItem("sequence", body.Nodes["sequence"] with
            {
                Sequence = new([new("inventory", "Inventory"), new("architecture", "Architecture"),
                    new("quality", "Quality"), new("archive", "Archive")])
            })
            .SetItem("inventory-tool", new NodeDefinition(NodeTypes.Agent, "1.0.0",
                Agent: new AgentConfiguration("proof.settlement", null, "Wait until released.", []) { MaxTurns = 1 }))
            .SetItem("architecture-tool", new(WorkflowRunner.StructuredProofBreakNodeType, "proof-only"))
            .Add("quality-tool", new NodeDefinition(NodeTypes.Agent, "1.0.0",
                Agent: new AgentConfiguration("proof.settlement", null, "Wait until released.", []) { MaxTurns = 1 }))
            .Add("archive-tool", new(NodeTypes.McpTool, "1.0.0",
                new ToolBindingRequest("proof.skipped-archive", new string('f', 64)))
            { McpArgumentsJson = "{\"query\":\"must-not-run\"}" });
        var definition = body with
        {
            Nodes = nodes,
            ExecutionConnections = body.ExecutionConnections!
                .SetItem("inventory-output", Edge("inventory-tool", "out", "output", "execute"))
                .SetItem("architecture-output", Edge("architecture-tool", "out", "output", "execute"))
                .Add("sequence-quality", Edge("sequence", "then.quality", "quality-tool", "execute"))
                .Add("quality-output", Edge("quality-tool", "out", "output", "execute"))
                .Add("sequence-archive", Edge("sequence", "then.archive", "archive-tool", "execute"))
                .Add("archive-output", Edge("archive-tool", "then", "output", "execute"))
        };
        var revision = WorkflowRevision.CreateProofOnly(definition, "single-stream-sequence-admission-wins-break-proof");
        using var store = new ProofRunStore(revision, "research", sqlite);
        var recorder = new ProofRecorder(store, startRoot: false);
        var agents = new ControlledSequenceRaceAgentExecutor();
        var breakNodeStarted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var suffixSkipped = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        ValueTask Record(ExecutionEvent evt)
        {
            recorder.Append(evt);
            if (evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
                SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "archive")
                suffixSkipped.TrySetResult();
            return ValueTask.CompletedTask;
        }
        ValueTask GateBreak(string nodeId, CancellationToken cancellationToken)
        {
            if (nodeId != "architecture-tool") return ValueTask.CompletedTask;
            breakNodeStarted.TrySetResult();
            return new(agents.AllowBreak.Task.WaitAsync(cancellationToken));
        }

        var execution = new WorkflowRunner(tools: new EchoToolBroker(), agents: agents)
            .ExecuteSingleStreamSequenceBreakProofAsync(store.RunId, revision, "research", Record,
                new HashSet<string>(["architecture-tool"], StringComparer.Ordinal),
                cancellationToken: CancellationToken.None, maximumConcurrentOutputs: 3,
                afterNodeStarted: GateBreak)
            .WaitAsync(TimeSpan.FromSeconds(10));
        try
        {
            try { await agents.InventoryStarted.Task.WaitAsync(TimeSpan.FromSeconds(5)); }
            catch (TimeoutException)
            {
                throw new Xunit.Sdk.XunitException("The initial Agent did not start. Execution completed: " +
                    execution.IsCompleted + ". Fault: " + execution.Exception?.GetBaseException() + ". Events: " + string.Join(" | ", recorder.Snapshot()
                        .Select(evt => $"{evt.Kind}:{evt.NodeId}:{evt.Data}")));
            }
            try { await breakNodeStarted.Task.WaitAsync(TimeSpan.FromSeconds(5)); }
            catch (TimeoutException)
            {
                throw new Xunit.Sdk.XunitException("The graph Break did not reach its pre-acceptance gate. Events: " +
                    string.Join(" | ", recorder.Snapshot().Select(evt => $"{evt.Kind}:{evt.NodeId}:{evt.Data}")));
            }
            try { await agents.QualityStarted.Task.WaitAsync(TimeSpan.FromSeconds(5)); }
            catch (TimeoutException)
            {
                throw new Xunit.Sdk.XunitException("The later Agent was not admitted while Break acceptance was held. Execution completed: " +
                    execution.IsCompleted + ". Fault: " + execution.Exception?.GetBaseException() + ". Events: " +
                    string.Join(" | ", recorder.Snapshot().Select(evt => $"{evt.Kind}:{evt.NodeId}:{evt.Data}")));
            }
            var beforeBreakAccepted = recorder.Snapshot();
            Assert.Contains(beforeBreakAccepted, evt => evt.Kind == ExecutionEventKinds.SequenceOutputDispatched &&
                SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "quality");
            Assert.DoesNotContain(beforeBreakAccepted, evt => evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
                SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "quality");
            Assert.False(execution.IsCompleted, "The graph-dispatched Break is held before acceptance while admitted Agents are active.");

            agents.AllowBreak.TrySetResult();
            await suffixSkipped.Task.WaitAsync(TimeSpan.FromSeconds(5));
            var afterBreak = recorder.Snapshot();
            var breakCompleted = Assert.Single(afterBreak, evt => evt.Kind == ExecutionEventKinds.NodeCompleted &&
                evt.NodeId == "architecture-tool");
            var qualityDispatch = Assert.Single(afterBreak, evt => evt.Kind == ExecutionEventKinds.SequenceOutputDispatched &&
                SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "quality");
            Assert.True(qualityDispatch.Sequence < breakCompleted.Sequence,
                "The racing output must be recorded as admitted before the Break request is accepted.");
            Assert.DoesNotContain(afterBreak, evt => evt.Kind == ExecutionEventKinds.NodeStarted && evt.NodeId == "archive-tool");
            Assert.False(execution.IsCompleted, "Break must drain output work admitted before Break acceptance.");
            Assert.DoesNotContain(afterBreak, evt => evt.Kind == ExecutionEventKinds.SequenceOutputCompleted &&
                SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "quality");

            agents.ReleaseInventory.TrySetResult();
            agents.ReleaseQuality.TrySetResult();
            var result = await execution;
            Assert.False(result.Failed);
        }
        finally
        {
            agents.ReleaseInventory.TrySetResult();
            agents.AllowBreak.TrySetResult();
            agents.ReleaseQuality.TrySetResult();
            if (!execution.IsCompleted)
            {
                try { await execution.WaitAsync(TimeSpan.FromSeconds(5)); }
                catch (TimeoutException) { }
            }
        }

        var events = recorder.Snapshot();
        AssertPersistedSequence(store, events, "completed");
        Assert.Equal(new[] { "architecture", "inventory", "quality" }.Order(StringComparer.Ordinal), events
            .Where(evt => evt.Kind == ExecutionEventKinds.SequenceOutputCompleted)
            .Select(evt => SequenceEvidence.TryRead(evt, out var evidence) ? evidence?.OutputId : null)
            .Order(StringComparer.Ordinal));
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakCompleted);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
            SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "archive");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputDispatched &&
            SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "archive");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Completed && evt.NodeId is null);
        var reopened = store.ReopenStore().Get(store.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.True(SequenceEvidence.TryReconstructPlayback(reopened.Events, out var playback));
        Assert.Equal("break-completed", playback!.Status);
        Assert.Equal(["inventory", "architecture", "quality", "archive"],
            playback.Outputs.Select(output => output.OutputId));
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task SingleStreamSequenceProof_AdmittedAgentFailureOverridesBreak(bool sqlite)
    {
        var body = SequenceBodyDefinition();
        var nodes = body.Nodes
            .SetItem("sequence", body.Nodes["sequence"] with
            {
                Sequence = new([new("inventory", "Inventory"), new("architecture", "Architecture"),
                    new("quality", "Quality")])
            })
            .SetItem("inventory-tool", new NodeDefinition(NodeTypes.Agent, "1.0.0",
                Agent: new AgentConfiguration("proof.settlement", null, "Wait, then fail.", []) { MaxTurns = 1 }))
            .SetItem("architecture-tool", new(WorkflowRunner.StructuredProofBreakNodeType, "proof-only"))
            .Add("quality-tool", new(NodeTypes.McpTool, "1.0.0",
                new ToolBindingRequest("proof.quality", new string('c', 64)))
            { McpArgumentsJson = "{\"query\":\"must-not-run\"}" });
        var definition = body with
        {
            Nodes = nodes,
            ExecutionConnections = body.ExecutionConnections!
                .SetItem("inventory-output", Edge("inventory-tool", "out", "output", "execute"))
                .SetItem("architecture-output", Edge("architecture-tool", "out", "output", "execute"))
                .Add("sequence-quality", Edge("sequence", "then.quality", "quality-tool", "execute"))
                .Add("quality-output", Edge("quality-tool", "then", "output", "execute"))
        };
        var revision = WorkflowRevision.CreateProofOnly(definition, "single-stream-sequence-failure-break-proof");
        using var store = new ProofRunStore(revision, "research", sqlite);
        var recorder = new ProofRecorder(store, startRoot: false);
        var agents = new ControlledSettlementAgentExecutor("inventory-tool", failAfterRelease: true);
        var suffixSkipped = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        ValueTask Record(ExecutionEvent evt)
        {
            recorder.Append(evt);
            if (evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
                SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "quality")
                suffixSkipped.TrySetResult();
            return ValueTask.CompletedTask;
        }

        var execution = new WorkflowRunner(tools: new EchoToolBroker(), agents: agents)
            .ExecuteSingleStreamSequenceBreakProofAsync(store.RunId, revision, "research", Record,
                new HashSet<string>(["architecture-tool"], StringComparer.Ordinal),
                cancellationToken: CancellationToken.None, maximumConcurrentOutputs: 2)
            .WaitAsync(TimeSpan.FromSeconds(10));
        try
        {
            await Task.WhenAll(agents.Started.Task, suffixSkipped.Task).WaitAsync(TimeSpan.FromSeconds(5));
            Assert.False(execution.IsCompleted, "The run must drain the admitted Agent after Break." );
            var acceptedPrefix = recorder.Snapshot();
            Assert.Single(acceptedPrefix, evt => evt.Kind == ExecutionEventKinds.SequenceBreakAccepted);
            Assert.DoesNotContain(acceptedPrefix, evt => evt.Kind == ExecutionEventKinds.SequenceBreakCompleted);
            agents.Release.TrySetResult();
            var result = await execution;
            Assert.True(result.Failed);
        }
        finally
        {
            agents.Release.TrySetResult();
            if (!execution.IsCompleted)
            {
                try { await execution.WaitAsync(TimeSpan.FromSeconds(5)); }
                catch (TimeoutException) { }
            }
        }

        var events = recorder.Snapshot();
        AssertPersistedSequence(store, events, "failed");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputFailed &&
            SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "inventory");
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.SequenceOutputSkipped &&
            SequenceEvidence.TryRead(evt, out var evidence) && evidence?.OutputId == "quality");
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.SequenceBreakCompleted);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.SequenceCompleted);
        Assert.Single(events, evt => evt.Kind == ExecutionEventKinds.Failed && evt.NodeId is null);
        Assert.DoesNotContain(events, evt => evt.Kind == ExecutionEventKinds.NodeStarted && evt.NodeId == "quality-tool");
        var reopened = store.ReopenStore().Get(store.RunId)!;
        Assert.Equal(events, reopened.Events);
        Assert.True(SequenceEvidence.TryReconstructPlayback(reopened.Events, out var playback));
        Assert.Equal("failed", playback!.Status);
        Assert.NotNull(playback.BreakAcceptance);
    }

