    private static WorkflowDefinition NestedParallelForkGraphDefinition()
    {
        var outerBranches = ImmutableArray.Create(
            new ParallelBranchDescriptor("left", "Outer left", "outer-anchor-left"),
            new ParallelBranchDescriptor("right", "Outer right", "outer-anchor-right"));
        var innerBranchesLeft = ImmutableArray.Create(
            new ParallelBranchDescriptor("a", "Inner A", "inner-anchor-left-a"),
            new ParallelBranchDescriptor("b", "Inner B", "inner-anchor-left-b"));
        var innerBranchesRight = ImmutableArray.Create(
            new ParallelBranchDescriptor("a", "Inner A", "inner-anchor-right-a"),
            new ParallelBranchDescriptor("b", "Inner B", "inner-anchor-right-b"));
        var nodes = ImmutableSortedDictionary<string, NodeDefinition>.Empty
            .Add("input", new(NodeTypes.Input, "1.0.0"))
            .Add("outer-fork", new(NodeTypes.ParallelFork, "1.0.0") { ParallelFork = new(outerBranches) })
            .Add("outer-anchor-left", new(NodeTypes.ParallelBranch, "1.0.0") { ParallelBranch = new("outer-fork", "left") })
            .Add("outer-anchor-right", new(NodeTypes.ParallelBranch, "1.0.0") { ParallelBranch = new("outer-fork", "right") })
            .Add("inner-fork-left", new(NodeTypes.ParallelFork, "1.0.0") { ParallelFork = new(innerBranchesLeft) })
            .Add("inner-fork-right", new(NodeTypes.ParallelFork, "1.0.0") { ParallelFork = new(innerBranchesRight) })
            .Add("inner-anchor-left-a", new(NodeTypes.ParallelBranch, "1.0.0") { ParallelBranch = new("inner-fork-left", "a") })
            .Add("inner-anchor-left-b", new(NodeTypes.ParallelBranch, "1.0.0") { ParallelBranch = new("inner-fork-left", "b") })
            .Add("inner-anchor-right-a", new(NodeTypes.ParallelBranch, "1.0.0") { ParallelBranch = new("inner-fork-right", "a") })
            .Add("inner-anchor-right-b", new(NodeTypes.ParallelBranch, "1.0.0") { ParallelBranch = new("inner-fork-right", "b") })
            .Add("inner-agent-left-a", new(NodeTypes.Agent, "1.0.0", Agent: new("proof.echo-agent", null, "Inner left A", [])))
            .Add("inner-agent-left-b", new(NodeTypes.Agent, "1.0.0", Agent: new("proof.echo-agent", null, "Inner left B", [])))
            .Add("inner-agent-right-a", new(NodeTypes.Agent, "1.0.0", Agent: new("proof.echo-agent", null, "Inner right A", [])))
            .Add("inner-agent-right-b", new(NodeTypes.Agent, "1.0.0", Agent: new("proof.echo-agent", null, "Inner right B", [])))
            .Add("outer-agent-left", new(NodeTypes.Agent, "1.0.0", Agent: new("proof.echo-agent", null, "Outer left", [])))
            .Add("outer-agent-right", new(NodeTypes.Agent, "1.0.0", Agent: new("proof.echo-agent", null, "Outer right", [])))
            .Add("inner-join-left", new(NodeTypes.ParallelJoin, "1.0.0")
            {
                ParallelJoin = new("inner-fork-left", ["a", "b"])
            })
            .Add("inner-join-right", new(NodeTypes.ParallelJoin, "1.0.0")
            {
                ParallelJoin = new("inner-fork-right", ["a", "b"])
            })
            .Add("outer-join", new(NodeTypes.ParallelJoin, "1.0.0")
            {
                ParallelJoin = new("outer-fork", ["left", "right"])
            })
            .Add("output", new(NodeTypes.Output, "1.0.0") { OutputDataType = WorkflowDataTypes.Json });
        var data = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
            .Add("input-inner-left-a", new(new("input", "out"), new("inner-agent-left-a", "in"), "data"))
            .Add("input-inner-left-b", new(new("input", "out"), new("inner-agent-left-b", "in"), "data"))
            .Add("input-inner-right-a", new(new("input", "out"), new("inner-agent-right-a", "in"), "data"))
            .Add("input-inner-right-b", new(new("input", "out"), new("inner-agent-right-b", "in"), "data"))
            .Add("inner-left-to-outer-agent", new(new("inner-join-left", "out"), new("outer-agent-left", "in"), "data"))
            .Add("inner-right-to-outer-agent", new(new("inner-join-right", "out"), new("outer-agent-right", "in"), "data"))
            .Add("outer-result", new(new("outer-join", "out"), new("output", "in"), "data"));
        var execution = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
            .Add("input-outer-fork", Edge("input", "then", "outer-fork", "execute"))
            .Add("outer-left", Edge("outer-fork", ParallelBranchLimits.PinId("left"), "outer-anchor-left", "execute"))
            .Add("outer-right", Edge("outer-fork", ParallelBranchLimits.PinId("right"), "outer-anchor-right", "execute"))
            .Add("left-inner-fork", Edge("outer-anchor-left", "then", "inner-fork-left", "execute"))
            .Add("right-inner-fork", Edge("outer-anchor-right", "then", "inner-fork-right", "execute"))
            .Add("inner-left-a", Edge("inner-fork-left", ParallelBranchLimits.PinId("a"), "inner-anchor-left-a", "execute"))
            .Add("inner-left-b", Edge("inner-fork-left", ParallelBranchLimits.PinId("b"), "inner-anchor-left-b", "execute"))
            .Add("inner-right-a", Edge("inner-fork-right", ParallelBranchLimits.PinId("a"), "inner-anchor-right-a", "execute"))
            .Add("inner-right-b", Edge("inner-fork-right", ParallelBranchLimits.PinId("b"), "inner-anchor-right-b", "execute"))
            .Add("inner-left-a-agent", Edge("inner-anchor-left-a", "then", "inner-agent-left-a", "execute"))
            .Add("inner-left-b-agent", Edge("inner-anchor-left-b", "then", "inner-agent-left-b", "execute"))
            .Add("inner-right-a-agent", Edge("inner-anchor-right-a", "then", "inner-agent-right-a", "execute"))
            .Add("inner-right-b-agent", Edge("inner-anchor-right-b", "then", "inner-agent-right-b", "execute"))
            .Add("inner-left-join-a", Edge("inner-agent-left-a", "out", "inner-join-left", "branch.a"))
            .Add("inner-left-join-b", Edge("inner-agent-left-b", "out", "inner-join-left", "branch.b"))
            .Add("inner-right-join-a", Edge("inner-agent-right-a", "out", "inner-join-right", "branch.a"))
            .Add("inner-right-join-b", Edge("inner-agent-right-b", "out", "inner-join-right", "branch.b"))
            .Add("inner-left-to-outer-agent", Edge("inner-join-left", "then", "outer-agent-left", "execute"))
            .Add("inner-right-to-outer-agent", Edge("inner-join-right", "then", "outer-agent-right", "execute"))
            .Add("outer-left-agent", Edge("outer-agent-left", "out", "outer-join", "branch.left"))
            .Add("outer-right-join", Edge("outer-agent-right", "out", "outer-join", "branch.right"))
            .Add("outer-join-output", Edge("outer-join", "then", "output", "execute"));
        return new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "nested-parallel-fork-proof", "input", nodes, data)
        {
            ExecutionConnections = execution
        };
    }

    private static WorkflowDefinition SharedNestedForkGraphDefinition()
    {
        var outerBranches = ImmutableArray.Create(
            new ParallelBranchDescriptor("left", "Outer left", "outer-anchor-left"),
            new ParallelBranchDescriptor("right", "Outer right", "outer-anchor-right"));
        var innerBranches = ImmutableArray.Create(
            new ParallelBranchDescriptor("a", "Inner A", "inner-anchor-a"),
            new ParallelBranchDescriptor("b", "Inner B", "inner-anchor-b"));
        var nodes = ImmutableSortedDictionary<string, NodeDefinition>.Empty
            .Add("input", new(NodeTypes.Input, "1.0.0"))
            .Add("outer-fork", new(NodeTypes.ParallelFork, "1.0.0") { ParallelFork = new(outerBranches) })
            .Add("outer-anchor-left", new(NodeTypes.ParallelBranch, "1.0.0") { ParallelBranch = new("outer-fork", "left") })
            .Add("outer-anchor-right", new(NodeTypes.ParallelBranch, "1.0.0") { ParallelBranch = new("outer-fork", "right") })
            .Add("parent-left", new(NodeTypes.Agent, "1.0.0", Agent: new("proof.shared-fork", null, "Left context", [])))
            .Add("parent-right", new(NodeTypes.Agent, "1.0.0", Agent: new("proof.shared-fork", null, "Right context", [])))
            .Add("left-context", new(NodeTypes.StringConstant, "1.0.0") { StringConstant = new("north") })
            .Add("right-context", new(NodeTypes.StringConstant, "1.0.0") { StringConstant = new("south") })
            .Add("shared-inner-fork", new(NodeTypes.ParallelFork, "1.0.0") { ParallelFork = new(innerBranches) })
            .Add("inner-anchor-a", new(NodeTypes.ParallelBranch, "1.0.0") { ParallelBranch = new("shared-inner-fork", "a") })
            .Add("inner-anchor-b", new(NodeTypes.ParallelBranch, "1.0.0") { ParallelBranch = new("shared-inner-fork", "b") })
            .Add("inner-agent-a", new(NodeTypes.Agent, "1.0.0", Agent: new("proof.shared-fork", null, "Inner A", [])))
            .Add("inner-agent-b", new(NodeTypes.Agent, "1.0.0", Agent: new("proof.shared-fork", null, "Inner B", [])))
            .Add("shared-inner-join", new(NodeTypes.ParallelJoin, "1.0.0")
                { ParallelJoin = new("shared-inner-fork", ["a", "b"]) })
            .Add("join-relay", new(NodeTypes.Agent, "1.0.0", Agent: new("proof.shared-fork", null, "Join relay", [])))
            .Add("output", new(NodeTypes.Output, "1.0.0"));
        var data = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
            .Add("left-context", new(new("left-context", "out"), new("parent-left", "in"), "data"))
            .Add("right-context", new(new("right-context", "out"), new("parent-right", "in"), "data"));
        var execution = ImmutableSortedDictionary<string, ConnectionDefinition>.Empty
            .Add("input-outer-fork", Edge("input", "then", "outer-fork", "execute"))
            .Add("outer-left", Edge("outer-fork", ParallelBranchLimits.PinId("left"), "outer-anchor-left", "execute"))
            .Add("outer-right", Edge("outer-fork", ParallelBranchLimits.PinId("right"), "outer-anchor-right", "execute"))
            .Add("left-parent", Edge("outer-anchor-left", "then", "parent-left", "execute"))
            .Add("right-parent", Edge("outer-anchor-right", "then", "parent-right", "execute"))
            .Add("left-shared-fork", Edge("parent-left", "out", "shared-inner-fork", "execute"))
            .Add("right-shared-fork", Edge("parent-right", "out", "shared-inner-fork", "execute"))
            .Add("inner-a", Edge("shared-inner-fork", ParallelBranchLimits.PinId("a"), "inner-anchor-a", "execute"))
            .Add("inner-b", Edge("shared-inner-fork", ParallelBranchLimits.PinId("b"), "inner-anchor-b", "execute"))
            .Add("anchor-a-agent", Edge("inner-anchor-a", "then", "inner-agent-a", "execute"))
            .Add("anchor-b-agent", Edge("inner-anchor-b", "then", "inner-agent-b", "execute"))
            .Add("agent-a-join", Edge("inner-agent-a", "out", "shared-inner-join", "branch.a"))
            .Add("agent-b-join", Edge("inner-agent-b", "out", "shared-inner-join", "branch.b"))
            .Add("join-relay", Edge("shared-inner-join", "then", "join-relay", "execute"))
            .Add("relay-output", Edge("join-relay", "out", "output", "execute"));
        return new WorkflowDefinition(WorkflowSchemaVersions.UnifiedWorkflowGraph,
            "nested-shared-parallel-fork-proof", "input", nodes, data)
        {
            ExecutionConnections = execution
        };
    }

    private sealed class SharedNestedForkAgentExecutor : IAgentNodeExecutor
    {
        private readonly ConcurrentQueue<string> joinRelayInputs = new();
        private int joinRelayStarts;

        public TaskCompletionSource BothJoinRelaysStarted { get; } =
            new(TaskCreationOptions.RunContinuationsAsynchronously);

        public string[] JoinRelayInputs => [.. joinRelayInputs];

        public Task<IReadOnlyList<AgentProviderDescriptor>> ListProvidersAsync() =>
            Task.FromResult<IReadOnlyList<AgentProviderDescriptor>>(
                [new("proof.shared-fork", "Shared fork proof", "proof", true)]);

        public async Task<string> ExecuteAsync(NodeInvocationContext invocation, string input,
            CancellationToken cancellationToken = default)
        {
            if (invocation.NodeId is "parent-left" or "parent-right") return input;
            if (invocation.NodeId is "inner-agent-a" or "inner-agent-b" or "inner-agent-unknown")
                return JsonSerializer.Serialize(new { parent = input, branch = invocation.NodeId });
            if (invocation.NodeId != "join-relay")
                throw new InvalidOperationException($"Unexpected shared-fork proof node '{invocation.NodeId}'.");

            joinRelayInputs.Enqueue(input);
            var start = Interlocked.Increment(ref joinRelayStarts);
            if (start == 2) BothJoinRelaysStarted.TrySetResult();
            if (start == 2)
            {
                await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken);
                throw new InvalidOperationException("A cancelled shared-fork relay unexpectedly resumed.");
            }
            cancellationToken.ThrowIfCancellationRequested();
            return input;
        }
    }

    private sealed class LateDuplicateNestedForkAgentExecutor : IAgentNodeExecutor
    {
        public TaskCompletionSource JoinCompleted { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public TaskCompletionSource LateDuplicateRejected { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);

        public Task<IReadOnlyList<AgentProviderDescriptor>> ListProvidersAsync() =>
            Task.FromResult<IReadOnlyList<AgentProviderDescriptor>>(
                [new("proof.shared-fork", "Shared fork proof", "proof", true)]);

        public async Task<string> ExecuteAsync(NodeInvocationContext invocation, string input,
            CancellationToken cancellationToken = default)
        {
            if (invocation.NodeId is "parent-left" or "parent-right") return input;
            if (invocation.NodeId is "inner-agent-a" or "inner-agent-b")
                return JsonSerializer.Serialize(new { parent = input, branch = invocation.NodeId });
            if (invocation.NodeId == "late-agent")
            {
                await JoinCompleted.Task.WaitAsync(cancellationToken);
                return input;
            }
            if (invocation.NodeId == "join-relay")
            {
                await LateDuplicateRejected.Task.WaitAsync(cancellationToken);
                return input;
            }
            throw new InvalidOperationException($"Unexpected late-duplicate proof node '{invocation.NodeId}'.");
        }
    }

    private sealed class ConcurrentDuplicateNestedForkAgentExecutor : IAgentNodeExecutor
    {
        private int racingArrivalCount;
        private readonly ConcurrentQueue<string> startedNodes = new();

        public TaskCompletionSource BothRacingArrivalsStarted { get; } =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        public TaskCompletionSource ReleaseRacingArrivals { get; } =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        public string[] StartedNodes => [.. startedNodes];

        public Task<IReadOnlyList<AgentProviderDescriptor>> ListProvidersAsync() =>
            Task.FromResult<IReadOnlyList<AgentProviderDescriptor>>(
                [new("proof.shared-fork", "Shared fork proof", "proof", true)]);

        public async Task<string> ExecuteAsync(NodeInvocationContext invocation, string input,
            CancellationToken cancellationToken = default)
        {
            startedNodes.Enqueue(invocation.NodeId);
            if (invocation.NodeId is "parent-left" or "parent-right") return input;
            if (invocation.NodeId == "inner-agent-a")
                return JsonSerializer.Serialize(new { parent = input, branch = invocation.NodeId });
            if (invocation.NodeId is "inner-agent-b" or "duplicate-agent")
            {
                if (Interlocked.Increment(ref racingArrivalCount) == 2)
                    BothRacingArrivalsStarted.TrySetResult();
                await ReleaseRacingArrivals.Task.WaitAsync(cancellationToken);
                return JsonSerializer.Serialize(new { parent = input, branch = invocation.NodeId });
            }
            if (invocation.NodeId == "join-relay") return input;
            throw new InvalidOperationException($"Unexpected concurrent-duplicate proof node '{invocation.NodeId}'.");
        }
    }

    private sealed class NestedForkSettlementAgentExecutor(bool blockAll) : IAgentNodeExecutor
    {
        private readonly ConcurrentDictionary<string, byte> startedNodes = new(StringComparer.Ordinal);
        private readonly TaskCompletionSource siblingSucceeded =
            new(TaskCreationOptions.RunContinuationsAsynchronously);

        public TaskCompletionSource AllInnerBranchesStarted { get; } =
            new(TaskCreationOptions.RunContinuationsAsynchronously);

        public Task<IReadOnlyList<AgentProviderDescriptor>> ListProvidersAsync() =>
            Task.FromResult<IReadOnlyList<AgentProviderDescriptor>>(
                [new("proof.nested-fork", "Nested fork proof", "proof", true)]);

        public async Task<string> ExecuteAsync(NodeInvocationContext invocation, string input,
            CancellationToken cancellationToken = default)
        {
            if (blockAll)
            {
                startedNodes.TryAdd(invocation.NodeId, 0);
                if (startedNodes.Count >= 4) AllInnerBranchesStarted.TrySetResult();
                await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken);
                throw new InvalidOperationException("A cancelled nested fork Agent unexpectedly resumed.");
            }

            if (invocation.NodeId == "inner-agent-left-a")
            {
                await siblingSucceeded.Task.WaitAsync(cancellationToken);
                throw new InvalidOperationException("The nested fork branch failed after its sibling completed.");
            }
            if (invocation.NodeId == "inner-agent-left-b") siblingSucceeded.TrySetResult();
            return JsonSerializer.Serialize(new { query = $"{input}-{invocation.NodeId}" });
        }
    }

    private sealed class ParallelActivationBarrier
    {
        private readonly object gate = new();
        private TaskCompletionSource pairReady = NewPair();
        private int arrivals;
        private int completedRequestPairs;

        public int CompletedPairs { get { lock (gate) return completedRequestPairs; } }

        public async Task WaitForConcurrentPairAsync(CancellationToken cancellationToken)
        {
            TaskCompletionSource current;
            var completePair = false;
            lock (gate)
            {
                current = pairReady;
                arrivals++;
                if (arrivals == 2)
                {
                    arrivals = 0;
                    completedRequestPairs++;
                    pairReady = NewPair();
                    completePair = true;
                }
            }

            if (completePair) current.TrySetResult();
            await current.Task.WaitAsync(TimeSpan.FromSeconds(5), cancellationToken);
        }

        private static TaskCompletionSource NewPair() => new(TaskCreationOptions.RunContinuationsAsynchronously);
    }

    private sealed class ParallelGraphFunctionChatClient(ParallelActivationBarrier session) : IChatClient
    {
        private int requestCount;

        public async Task<ChatResponse> GetResponseAsync(IEnumerable<ChatMessage> messages, ChatOptions? options = null,
            CancellationToken cancellationToken = default)
        {
            if (Interlocked.Increment(ref requestCount) > 1)
                return new ChatResponse(new ChatMessage(ChatRole.Assistant, "Function completed."))
                { FinishReason = ChatFinishReason.Stop };

            var input = messages.Last(message => message.Role == ChatRole.User).Text!;
            await session.WaitForConcurrentPairAsync(cancellationToken);
            return new ChatResponse(new ChatMessage(ChatRole.Assistant,
                [new FunctionCallContent(Guid.NewGuid().ToString("N"), "graph_function_0",
                    new Dictionary<string, object?> { ["text"] = input })]))
            { FinishReason = ChatFinishReason.ToolCalls };
        }

        public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(IEnumerable<ChatMessage> messages,
            ChatOptions? options = null, CancellationToken cancellationToken = default) =>
            throw new NotSupportedException();

        public object? GetService(Type serviceType, object? serviceKey = null) => null;

        public void Dispose() { }
    }

    private sealed class ParallelFunctionInputAgentExecutor(ParallelActivationBarrier barrier) : IAgentNodeExecutor
    {
        private readonly ConcurrentQueue<(string NodeId, string Input)> invocations = new();

        public ParallelActivationBarrier Barrier => barrier;
        public (string NodeId, string Input)[] Invocations => [.. invocations];

        public Task<IReadOnlyList<AgentProviderDescriptor>> ListProvidersAsync() =>
            Task.FromResult<IReadOnlyList<AgentProviderDescriptor>>(
                [new("proof.parallel-function-input", "Parallel function input proof", "proof", true)]);

