        public TaskCompletionSource DispatchStarted { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public TaskCompletionSource ReleaseOutcome { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);

        public Task<IReadOnlyList<ToolBindingDescriptor>> ListBindingsAsync(CancellationToken cancellationToken = default) =>
            Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

        public INodeToolScope OpenScope(NodeInvocationContext invocation) => new Scope(this, invocation);

        private sealed class Scope(ControlledUnknownOutcomeToolBroker owner, NodeInvocationContext invocation) : INodeToolScope
        {
            public Task<IReadOnlyList<ToolBindingDescriptor>> ListToolsAsync(CancellationToken cancellationToken = default) =>
                Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

            public Task<string> InvokeAsync(string bindingId, string input, CancellationToken cancellationToken = default) =>
                Task.FromException<string>(new NotSupportedException("The proof expects structured MCP arguments."));

            public async Task<string> InvokeJsonAsync(string bindingId, JsonElement arguments,
                CancellationToken cancellationToken = default)
            {
                if (bindingId != owner.registeredBindingId)
                    throw new InvalidOperationException("The workflow requested an unexpected MCP binding.");
                var toolCallId = Guid.NewGuid();
                var requested = JsonSerializer.Serialize(new { toolCallId, bindingId });
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolRequested, requested);
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolAuthorized,
                    JsonSerializer.Serialize(new { toolCallId, bindingId, input = arguments }));
                owner.DispatchStarted.TrySetResult();
                await owner.ReleaseOutcome.Task.WaitAsync(cancellationToken);
                const string reason = "The controlled MCP dispatch has an unknown outcome.";
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolUncertain, JsonSerializer.Serialize(new
                {
                    toolCallId,
                    bindingId,
                    failureCode = "tool.outcome_unknown",
                    disposition = ToolInvocationFailureDisposition.OutcomeUnknown.ToString(),
                    reason
                }));
                throw new ToolInvocationException(reason, ToolInvocationFailureDisposition.OutcomeUnknown);
            }

            public ValueTask DisposeAsync() => ValueTask.CompletedTask;
        }
    }

    private sealed class FirstSuccessSecondUnknownToolBroker(string expectedBindingId) : INodeToolBroker
    {
        private readonly string registeredBindingId = expectedBindingId;
        private int invocationCount;

        public TaskCompletionSource FirstCallCompleted { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public TaskCompletionSource SecondCallStarted { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public TaskCompletionSource ReleaseSecondCall { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);

        public Task<IReadOnlyList<ToolBindingDescriptor>> ListBindingsAsync(CancellationToken cancellationToken = default) =>
            Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

        public INodeToolScope OpenScope(NodeInvocationContext invocation) => new Scope(this, invocation);

        private sealed class Scope(FirstSuccessSecondUnknownToolBroker owner, NodeInvocationContext invocation)
            : INodeToolScope
        {
            public Task<IReadOnlyList<ToolBindingDescriptor>> ListToolsAsync(CancellationToken cancellationToken = default) =>
                Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

            public Task<string> InvokeAsync(string bindingId, string input, CancellationToken cancellationToken = default) =>
                Task.FromException<string>(new NotSupportedException("The proof expects structured MCP arguments."));

            public async Task<string> InvokeJsonAsync(string bindingId, JsonElement arguments,
                CancellationToken cancellationToken = default)
            {
                if (bindingId != owner.registeredBindingId)
                    throw new InvalidOperationException("The workflow requested an unexpected MCP binding.");

                var callNumber = Interlocked.Increment(ref owner.invocationCount);
                var toolCallId = Guid.NewGuid();
                var requested = JsonSerializer.Serialize(new { toolCallId, bindingId });
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolRequested, requested);
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolAuthorized,
                    JsonSerializer.Serialize(new { toolCallId, bindingId, input = arguments }));

                if (callNumber == 1)
                {
                    owner.FirstCallCompleted.TrySetResult();
                    return arguments.GetRawText();
                }

                owner.SecondCallStarted.TrySetResult();
                await owner.ReleaseSecondCall.Task.WaitAsync(cancellationToken);
                const string reason = "The controlled sibling MCP dispatch has an unknown outcome.";
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolUncertain, JsonSerializer.Serialize(new
                {
                    toolCallId,
                    bindingId,
                    failureCode = "tool.outcome_unknown",
                    disposition = ToolInvocationFailureDisposition.OutcomeUnknown.ToString(),
                    reason
                }));
                throw new ToolInvocationException(reason, ToolInvocationFailureDisposition.OutcomeUnknown);
            }

            public ValueTask DisposeAsync() => ValueTask.CompletedTask;
        }
    }

    public enum ControlledToolOutcome { Success, Failure, Unknown }

    private sealed class ControlledSettlementToolBroker(string expectedBindingId, ControlledToolOutcome outcome,
        int expectedDispatches = 1)
        : INodeToolBroker
    {
        private readonly string registeredBindingId = expectedBindingId;
        private readonly ControlledToolOutcome selectedOutcome = outcome;
        private readonly int expectedDispatchCount = expectedDispatches;
        public TaskCompletionSource DispatchStarted { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public TaskCompletionSource AllDispatchesStarted { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public TaskCompletionSource ReleaseOutcome { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        private int dispatchCount;

        public Task<IReadOnlyList<ToolBindingDescriptor>> ListBindingsAsync(CancellationToken cancellationToken = default) =>
            Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

        public INodeToolScope OpenScope(NodeInvocationContext invocation) => new Scope(this, invocation);

        private sealed class Scope(ControlledSettlementToolBroker owner, NodeInvocationContext invocation) : INodeToolScope
        {
            public Task<IReadOnlyList<ToolBindingDescriptor>> ListToolsAsync(CancellationToken cancellationToken = default) =>
                Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

            public Task<string> InvokeAsync(string bindingId, string input, CancellationToken cancellationToken = default) =>
                Task.FromException<string>(new NotSupportedException("The proof expects structured MCP arguments."));

            public async Task<string> InvokeJsonAsync(string bindingId, JsonElement arguments,
                CancellationToken cancellationToken = default)
            {
                if (bindingId != owner.registeredBindingId)
                    throw new InvalidOperationException("The workflow requested an unexpected MCP binding.");

                var toolCallId = Guid.NewGuid();
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolRequested,
                    JsonSerializer.Serialize(new { toolCallId, bindingId }));
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolAuthorized,
                    JsonSerializer.Serialize(new { toolCallId, bindingId, input = arguments }));
                owner.DispatchStarted.TrySetResult();
                if (Interlocked.Increment(ref owner.dispatchCount) == owner.expectedDispatchCount)
                    owner.AllDispatchesStarted.TrySetResult();
                await owner.ReleaseOutcome.Task.WaitAsync(cancellationToken);

                if (owner.selectedOutcome == ControlledToolOutcome.Success)
                {
                    await invocation.RecordEventAsync(ExecutionEventKinds.ToolCompleted,
                        JsonSerializer.Serialize(new { toolCallId, bindingId, output = "controlled-result" }));
                    return "controlled-result";
                }

                var isUnknown = owner.selectedOutcome == ControlledToolOutcome.Unknown;
                var reason = isUnknown
                    ? "The controlled MCP dispatch has an unknown outcome."
                    : "The controlled MCP dispatch failed definitively.";
                await invocation.RecordEventAsync(isUnknown
                    ? ExecutionEventKinds.ToolUncertain
                    : ExecutionEventKinds.ToolFailed, JsonSerializer.Serialize(new
                    {
                        toolCallId,
                        bindingId,
                        failureCode = isUnknown ? "tool.outcome_unknown" : "mcp.server_declared_failure",
                        disposition = (isUnknown ? ToolInvocationFailureDisposition.OutcomeUnknown :
                            ToolInvocationFailureDisposition.Fatal).ToString(),
                        reason
                    }));
                throw new ToolInvocationException(reason, isUnknown
                    ? ToolInvocationFailureDisposition.OutcomeUnknown
                    : ToolInvocationFailureDisposition.Fatal);
            }

            public ValueTask DisposeAsync() => ValueTask.CompletedTask;
        }
    }

    private sealed class TwoBranchBlockingAgentExecutor : IAgentNodeExecutor
    {
        private readonly ConcurrentDictionary<string, byte> started = new(StringComparer.Ordinal);

        public TaskCompletionSource BothBranchesStarted { get; } =
            new(TaskCreationOptions.RunContinuationsAsynchronously);

        public Task<IReadOnlyList<AgentProviderDescriptor>> ListProvidersAsync() =>
            Task.FromResult<IReadOnlyList<AgentProviderDescriptor>>(
                [new("proof.parallel-cancellation", "Parallel cancellation proof", "proof", true)]);

        public async Task<string> ExecuteAsync(NodeInvocationContext invocation, string input,
            CancellationToken cancellationToken = default)
        {
            if (invocation.NodeId is not ("agent-left" or "agent-right"))
                throw new InvalidOperationException($"Unexpected proof Agent node '{invocation.NodeId}'.");

            started.TryAdd(invocation.NodeId, 0);
            if (started.Count == 2) BothBranchesStarted.TrySetResult();
            await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken);
            throw new InvalidOperationException("The cancelled branch unexpectedly resumed.");
        }
    }

    private sealed class CoordinatedBranchFailureAgentExecutor : IAgentNodeExecutor
    {
        private readonly ConcurrentQueue<string> enteredNodes = new();
        private readonly TaskCompletionSource rightEntered = new(TaskCreationOptions.RunContinuationsAsynchronously);

        public string[] EnteredNodes => [.. enteredNodes];

        public Task<IReadOnlyList<AgentProviderDescriptor>> ListProvidersAsync() =>
            Task.FromResult<IReadOnlyList<AgentProviderDescriptor>>(
                [new("proof.coordinated", "Coordinated proof", "proof", true)]);

        public async Task<string> ExecuteAsync(NodeInvocationContext invocation, string input,
            CancellationToken cancellationToken = default)
        {
            enteredNodes.Enqueue(invocation.NodeId);
            if (invocation.NodeId == "agent-right")
            {
                rightEntered.TrySetResult();
                await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken);
            }

            if (invocation.NodeId == "agent-left")
            {
                await rightEntered.Task.WaitAsync(cancellationToken);
                throw new InvalidOperationException("Deterministic coordinated branch failure.");
            }

            throw new InvalidOperationException($"Unexpected proof Agent node '{invocation.NodeId}'.");
        }
    }

