    private sealed class CapturingIterationApprovalGate : IWorkflowExecutionGate, IWorkflowApprovalGate
    {
        private readonly ConcurrentQueue<WorkflowApprovalAction> actions = new();
        private readonly ConcurrentQueue<WorkflowApprovalPermit> permits = new();

        public WorkflowApprovalAction[] Actions => [.. actions];
        public WorkflowApprovalPermit[] Permits => [.. permits];

        public ValueTask WaitForBoundaryAsync(string? nextNodeId, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            return ValueTask.CompletedTask;
        }

        public ValueTask<WorkflowApprovalPermit> WaitForApprovalAsync(WorkflowApprovalAction action,
            string prompt, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            Assert.Equal("Approve this exact search.", prompt);
            actions.Enqueue(action);
            var permit = new WorkflowApprovalPermit(Guid.NewGuid(), action.ComputeHash(), action.TargetInvocationId);
            permits.Enqueue(permit);
            return ValueTask.FromResult(permit);
        }
    }

    private sealed class BlockingIterationApprovalGate : IWorkflowExecutionGate, IWorkflowApprovalGate
    {
        public TaskCompletionSource<WorkflowApprovalAction> Requested { get; } =
            new(TaskCreationOptions.RunContinuationsAsynchronously);

        public ValueTask WaitForBoundaryAsync(string? nextNodeId, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            return ValueTask.CompletedTask;
        }

        public async ValueTask<WorkflowApprovalPermit> WaitForApprovalAsync(WorkflowApprovalAction action,
            string prompt, CancellationToken cancellationToken)
        {
            Assert.Equal("Approve this exact search.", prompt);
            Requested.TrySetResult(action);
            await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken);
            throw new OperationCanceledException(cancellationToken);
        }
    }

    private sealed class RejectingIterationApprovalGate : IWorkflowExecutionGate, IWorkflowApprovalGate
    {
        private readonly ConcurrentQueue<WorkflowApprovalAction> actions = new();

        public WorkflowApprovalAction[] Actions => [.. actions];

        public ValueTask WaitForBoundaryAsync(string? nextNodeId, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            return ValueTask.CompletedTask;
        }

        public ValueTask<WorkflowApprovalPermit> WaitForApprovalAsync(WorkflowApprovalAction action,
            string prompt, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            Assert.Equal("Approve this exact search.", prompt);
            actions.Enqueue(action);
            return ValueTask.FromException<WorkflowApprovalPermit>(new WorkflowApprovalRejectedException());
        }
    }

    private sealed class RecordingFailedToolBroker(string bindingId) : INodeToolBroker
    {
        private int dispatchAttempts;
        private int failureEvidenceAttempted;

        public int DispatchAttempts => Volatile.Read(ref dispatchAttempts);
        public bool FailureEvidenceAttempted => Volatile.Read(ref failureEvidenceAttempted) != 0;

        public Task<IReadOnlyList<ToolBindingDescriptor>> ListBindingsAsync(
            CancellationToken cancellationToken = default) =>
            Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

        public INodeToolScope OpenScope(NodeInvocationContext invocation) => new Scope(bindingId, invocation, this);

        private sealed class Scope(string expectedBindingId, NodeInvocationContext invocation,
            RecordingFailedToolBroker owner) : INodeToolScope
        {
            public Task<IReadOnlyList<ToolBindingDescriptor>> ListToolsAsync(
                CancellationToken cancellationToken = default) =>
                Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

            public Task<string> InvokeAsync(string requestedBindingId, string input,
                CancellationToken cancellationToken = default) =>
                Task.FromException<string>(new NotSupportedException("The proof expects structured tool arguments."));

            public async Task<string> InvokeJsonAsync(string requestedBindingId, JsonElement arguments,
                CancellationToken cancellationToken = default)
            {
                if (requestedBindingId != expectedBindingId)
                    throw new InvalidOperationException("The workflow requested an unexpected custom tool.");

                var toolCallId = Guid.NewGuid();
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolRequested,
                    JsonSerializer.Serialize(new { toolCallId, bindingId = requestedBindingId }));
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolAuthorized,
                    JsonSerializer.Serialize(new { toolCallId, bindingId = requestedBindingId, input = arguments }));
                Interlocked.Increment(ref owner.dispatchAttempts);
                Volatile.Write(ref owner.failureEvidenceAttempted, 1);
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolFailed,
                    JsonSerializer.Serialize(new
                    {
                        toolCallId,
                        bindingId = requestedBindingId,
                        failureCode = "tool.host_failure",
                        disposition = ToolInvocationFailureDisposition.Fatal.ToString(),
                        reason = "The controlled tool failed before completing its operation."
                    }));
                throw new ToolInvocationException("The controlled tool failed before completing its operation.");
            }

            public ValueTask DisposeAsync() => ValueTask.CompletedTask;
        }
    }

    private sealed class OrderedMixedOutcomeParallelMcpBroker(bool unknownFirst, bool holdOutcomes = false,
        string researchNodeId = "tool-research", string reviewNodeId = "tool-review")
        : INodeToolBroker
    {
        private readonly bool holdOutcomesForBroker = holdOutcomes;
        private readonly string researchNodeIdForBroker = researchNodeId;
        private readonly string reviewNodeIdForBroker = reviewNodeId;
        private readonly TaskCompletionSource bothAuthorized =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private readonly TaskCompletionSource reviewOutcomeRecorded =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private readonly TaskCompletionSource researchFailureRecorded =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private readonly TaskCompletionSource outcomesReleased =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private int authorizations;

        public int Authorizations => Volatile.Read(ref authorizations);
        public bool HoldOutcomes => holdOutcomesForBroker;
        public string ResearchNodeId => researchNodeIdForBroker;
        public string ReviewNodeId => reviewNodeIdForBroker;
        public Task BothAuthorized => bothAuthorized.Task;
        public TaskCompletionSource ReleaseOutcomes => outcomesReleased;

        public Task<IReadOnlyList<ToolBindingDescriptor>> ListBindingsAsync(
            CancellationToken cancellationToken = default) =>
            Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

        public INodeToolScope OpenScope(NodeInvocationContext invocation) =>
            new Scope(this, invocation, unknownFirst);

        private sealed class Scope(OrderedMixedOutcomeParallelMcpBroker owner, NodeInvocationContext invocation,
            bool unknownFirst)
            : INodeToolScope
        {
            public Task<IReadOnlyList<ToolBindingDescriptor>> ListToolsAsync(
                CancellationToken cancellationToken = default) =>
                Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

            public Task<string> InvokeAsync(string bindingId, string input,
                CancellationToken cancellationToken = default) =>
                Task.FromException<string>(new NotSupportedException(
                    "The proof expects structured MCP arguments."));

            public async Task<string> InvokeJsonAsync(string bindingId, JsonElement arguments,
                CancellationToken cancellationToken = default)
            {
                var toolCallId = Guid.NewGuid();
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolRequested,
                    JsonSerializer.Serialize(new { toolCallId, bindingId }));
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolAuthorized,
                    JsonSerializer.Serialize(new { toolCallId, bindingId, input = arguments }));
                if (Interlocked.Increment(ref owner.authorizations) == 2)
                    owner.bothAuthorized.TrySetResult();
                await owner.bothAuthorized.Task.WaitAsync(TimeSpan.FromSeconds(5));
                if (owner.HoldOutcomes)
                    await owner.outcomesReleased.Task.WaitAsync(TimeSpan.FromSeconds(10));

                if (invocation.NodeId == owner.ReviewNodeId)
                {
                    if (!unknownFirst)
                        await owner.researchFailureRecorded.Task.WaitAsync(TimeSpan.FromSeconds(5));
                    const string reason = "The dispatched review call has an unresolved external outcome.";
                    await invocation.RecordEventAsync(ExecutionEventKinds.ToolUncertain,
                        JsonSerializer.Serialize(new
                        {
                            toolCallId,
                            bindingId,
                            failureCode = "tool.outcome_unknown",
                            disposition = ToolInvocationFailureDisposition.OutcomeUnknown.ToString(),
                            reason
                        }));
                    owner.reviewOutcomeRecorded.TrySetResult();
                    throw new ToolInvocationException(reason, ToolInvocationFailureDisposition.OutcomeUnknown);
                }

                if (invocation.NodeId != owner.ResearchNodeId)
                    throw new InvalidOperationException($"Unexpected MCP node '{invocation.NodeId}'.");

                if (unknownFirst)
                    await owner.reviewOutcomeRecorded.Task.WaitAsync(TimeSpan.FromSeconds(5));
                const string failure = "The research call failed definitively after review outcome became unknown.";
                await invocation.RecordEventAsync(ExecutionEventKinds.ToolFailed,
                    JsonSerializer.Serialize(new
                    {
                        toolCallId,
                        bindingId,
                        failureCode = "mcp.server_declared_failure",
                        disposition = ToolInvocationFailureDisposition.Fatal.ToString(),
                        reason = failure
                    }));
                owner.researchFailureRecorded.TrySetResult();
                throw new ToolInvocationException(failure, ToolInvocationFailureDisposition.Fatal);
            }

            public ValueTask DisposeAsync() => ValueTask.CompletedTask;
        }
    }

    private sealed class ConcurrentSequenceFailureMcpBroker(Func<Guid, string?> scopeForInvocation,
        Task siblingSequenceCompleted) : INodeToolBroker
    {
        private readonly ConcurrentQueue<ParallelToolCall> calls = new();
        private readonly TaskCompletionSource allAuthorizationsRecorded =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private int authorizationCount;
        private int activeCalls;
        private int maximumConcurrentCalls;

        public ParallelToolCall[] Calls => [.. calls];
        public int MaximumConcurrentCalls => maximumConcurrentCalls;
        public Task<IReadOnlyList<ToolBindingDescriptor>> ListBindingsAsync(
            CancellationToken cancellationToken = default) =>
            Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

        public INodeToolScope OpenScope(NodeInvocationContext invocation) =>
            new Scope(this, invocation, scopeForInvocation, siblingSequenceCompleted);

        private sealed class Scope(ConcurrentSequenceFailureMcpBroker owner,
            NodeInvocationContext invocation, Func<Guid, string?> scopeForInvocation,
            Task siblingSequenceCompleted) : INodeToolScope
        {
            public Task<IReadOnlyList<ToolBindingDescriptor>> ListToolsAsync(
                CancellationToken cancellationToken = default) =>
                Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);

            public Task<string> InvokeAsync(string bindingId, string input,
                CancellationToken cancellationToken = default) =>
                Task.FromException<string>(new NotSupportedException());

            public async Task<string> InvokeJsonAsync(string bindingId, JsonElement arguments,
                CancellationToken cancellationToken = default)
            {
                var active = Interlocked.Increment(ref owner.activeCalls);
                UpdateMaximum(owner, active);
                try
                {
                    var query = arguments.GetProperty("query").GetString()!;
                    owner.calls.Enqueue(new(invocation.NodeId, invocation.InvocationId, query));
                    var toolCallId = Guid.NewGuid();
                    await invocation.RecordEventAsync(ExecutionEventKinds.ToolAuthorized,
                        JsonSerializer.Serialize(new { toolCallId, bindingId, input = arguments }));
                    if (Interlocked.Increment(ref owner.authorizationCount) == 4)
                        owner.allAuthorizationsRecorded.TrySetResult();
                    await owner.allAuthorizationsRecorded.Task.WaitAsync(TimeSpan.FromSeconds(5),
                        cancellationToken);

                    if (scopeForInvocation(invocation.InvocationId) == "array-loop/0" &&
                        invocation.NodeId == "inventory-tool")
                    {
                        await siblingSequenceCompleted.WaitAsync(TimeSpan.FromSeconds(5), cancellationToken);
                        await invocation.RecordEventAsync(ExecutionEventKinds.ToolFailed,
                            JsonSerializer.Serialize(new
                            {
                                toolCallId,
                                bindingId,
                                failureCode = "tool.host_failure",
                                disposition = ToolInvocationFailureDisposition.Fatal.ToString(),
                                reason = "Deterministic first-item Sequence failure."
                            }));
                        throw new ToolInvocationException("Deterministic first-item Sequence failure.",
                            ToolInvocationFailureDisposition.Fatal);
                    }

                    var result = $"result:{query}";
                    await invocation.RecordEventAsync(ExecutionEventKinds.ToolCompleted,
                        JsonSerializer.Serialize(new { toolCallId, bindingId, output = result }));
                    return result;
                }
                finally
                {
                    Interlocked.Decrement(ref owner.activeCalls);
                }
            }

            public ValueTask DisposeAsync() => ValueTask.CompletedTask;
        }

        private static void UpdateMaximum(ConcurrentSequenceFailureMcpBroker owner, int candidate)
        {
            var current = Volatile.Read(ref owner.maximumConcurrentCalls);
            while (candidate > current)
            {
                var previous = Interlocked.CompareExchange(ref owner.maximumConcurrentCalls, candidate, current);
                if (previous == current) return;
                current = previous;
            }
        }
    }

    private sealed class ParallelMcpBroker(string? denyNode = null, string? failNode = null,
        bool holdUntilCancelled = false, string? resultPayload = null,
        Task? releaseAfterReservationRejected = null, bool waitForBothAuthorizations = false,
        bool denyAll = false, bool recordReservationIds = false, int expectedCallCount = 2,
        Task? waitBeforeOutcome = null, bool preserveHostCancellation = false) : INodeToolBroker
    {
        private readonly ConcurrentQueue<ParallelToolCall> calls = new();
        private readonly TaskCompletionSource branchesStarted = new(TaskCreationOptions.RunContinuationsAsynchronously);
        private readonly TaskCompletionSource bothAuthorizationsRecorded = new(TaskCreationOptions.RunContinuationsAsynchronously);
        private int authorizationCount;
        private int activeCalls;
        private int maximumConcurrentCalls;
        private int dispatchedCalls;
        private readonly TaskCompletionSource dispatchStarted =
            new(TaskCreationOptions.RunContinuationsAsynchronously);

        public int MaximumConcurrentCalls => maximumConcurrentCalls;
        public int DispatchedCalls => dispatchedCalls;
        public ParallelToolCall[] Calls => [.. calls];
        public Task BothBranchesStarted => branchesStarted.Task;
        public Task DispatchStarted => dispatchStarted.Task;
        public Task WaitBeforeOutcome => waitBeforeOutcome ?? Task.CompletedTask;
        public bool PreserveHostCancellation => preserveHostCancellation;
        public Task<IReadOnlyList<ToolBindingDescriptor>> ListBindingsAsync(CancellationToken cancellationToken = default) =>
            Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);
        public INodeToolScope OpenScope(NodeInvocationContext invocation) =>
            new Scope(this, invocation.NodeId, invocation.InvocationId, invocation.Record,
                denyNode, failNode, holdUntilCancelled, resultPayload, releaseAfterReservationRejected,
                waitForBothAuthorizations, denyAll, recordReservationIds, expectedCallCount);

        private sealed class Scope(ParallelMcpBroker owner, string nodeId, Guid invocationId,
            Func<string, string?, ValueTask> record, string? denyNode, string? failNode,
            bool holdUntilCancelled, string? resultPayload, Task? releaseAfterReservationRejected,
            bool waitForBothAuthorizations, bool denyAll, bool recordReservationIds,
            int expectedCallCount) : INodeToolScope
        {
            public Task<IReadOnlyList<ToolBindingDescriptor>> ListToolsAsync(CancellationToken cancellationToken = default) =>
                Task.FromResult<IReadOnlyList<ToolBindingDescriptor>>([]);
            public Task<string> InvokeAsync(string bindingId, string input, CancellationToken cancellationToken = default) =>
                Task.FromException<string>(new NotSupportedException());
            public async Task<string> InvokeJsonAsync(string bindingId, JsonElement arguments, CancellationToken cancellationToken = default)
            {
                var active = Interlocked.Increment(ref owner.activeCalls);
                UpdateMaximum(owner, active);
                var query = arguments.GetProperty("query").GetString()!;
                owner.calls.Enqueue(new(nodeId, invocationId, query));
                var toolCallId = Guid.NewGuid();
                if (owner.calls.Count >= expectedCallCount) owner.branchesStarted.TrySetResult();
                try
                {
                    if (owner.calls.Count >= expectedCallCount) owner.branchesStarted.TrySetResult();
                    await owner.branchesStarted.Task.WaitAsync(TimeSpan.FromSeconds(5), cancellationToken);
                    if (denyAll || nodeId == denyNode)
                    {
                        await record(ExecutionEventKinds.ToolDenied, "No effective node grant.");
                        throw new ToolAccessDeniedException();
                    }
                    await record(ExecutionEventKinds.ToolAuthorized, recordReservationIds
                        ? JsonSerializer.Serialize(new { toolCallId, bindingId, input = arguments })
                        : query);
                    await owner.WaitBeforeOutcome.WaitAsync(cancellationToken);
                    if (waitForBothAuthorizations && Interlocked.Increment(ref owner.authorizationCount) == expectedCallCount)
                        owner.bothAuthorizationsRecorded.TrySetResult();
                    if (waitForBothAuthorizations)
                        await owner.bothAuthorizationsRecorded.Task.WaitAsync(TimeSpan.FromSeconds(5), cancellationToken);
                    Interlocked.Increment(ref owner.dispatchedCalls);
                    owner.dispatchStarted.TrySetResult();
                    if (releaseAfterReservationRejected is not null)
                        await releaseAfterReservationRejected;
                    if (nodeId == failNode || failNode == "*")
                    {
                        await record(ExecutionEventKinds.ToolFailed, recordReservationIds
                            ? JsonSerializer.Serialize(new
                            {
                                toolCallId, bindingId, failureCode = "tool.host_failure",
                                reason = "Deterministic branch tool failure."
                            })
                            : "Deterministic branch tool failure.");
                        throw new ToolInvocationException("Deterministic branch tool failure.");
                    }
                    if (holdUntilCancelled)
                    {
                        try { await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken); }
                        catch (OperationCanceledException) when (recordReservationIds)
                        {
                            await record(ExecutionEventKinds.ToolUncertain, JsonSerializer.Serialize(new
                            {
                                toolCallId, parentToolCallId = (Guid?)null, bindingId,
                                failureCode = "tool.outcome_unknown",
                                reason = "The dispatched sibling call was cancelled before its outcome was observed."
                            }));
                            if (owner.PreserveHostCancellation) throw;
                            throw new ToolInvocationException(
                                "The dispatched sibling call has an unknown outcome.",
                                ToolInvocationFailureDisposition.OutcomeUnknown);
                        }
                    }
                    var result = resultPayload ?? $"result:{query}";
                    await record(ExecutionEventKinds.ToolCompleted, JsonSerializer.Serialize(new
                    {
                        toolCallId = recordReservationIds ? toolCallId : Guid.NewGuid(),
                        parentToolCallId = (Guid?)null, bindingId, output = result
                    }));
                    return result;
                }
                finally { Interlocked.Decrement(ref owner.activeCalls); }
            }
            public ValueTask DisposeAsync() => ValueTask.CompletedTask;
        }

        private static void UpdateMaximum(ParallelMcpBroker owner, int candidate)
        {
            var current = Volatile.Read(ref owner.maximumConcurrentCalls);
            while (candidate > current)
            {
                var previous = Interlocked.CompareExchange(ref owner.maximumConcurrentCalls, candidate, current);
                if (previous == current) return;
                current = previous;
            }
        }
    }

    private sealed class ParallelDelegateEvidenceModel(string parentInstructions, string researcherInstructions,
        string reviewerInstructions, string task, int delegateOutputCharacters, bool failResearcher = false,
        bool failParentFollowup = false, bool blockDelegatesUntilCancelled = false,
        int? researcherFailureStatusCode = null, bool holdReviewerUntilOutcomeRejected = false)
    {
        private readonly ConcurrentQueue<DelegatedPrompt> prompts = new();
        private readonly TaskCompletionSource bothDelegatesStarted = new(TaskCreationOptions.RunContinuationsAsynchronously);
        private int parentTurns;
        private int activeDelegates;
        private int maximumConcurrentDelegateCalls;

        public DelegatedPrompt[] Prompts => [.. prompts];
        public int MaximumConcurrentDelegateCalls => maximumConcurrentDelegateCalls;
        public Task BothDelegateCallsStarted => bothDelegatesStarted.Task;

        public async Task<ChatResponse> RespondAsync(IEnumerable<ChatMessage> messages, ChatOptions? options,
            CancellationToken cancellationToken)
        {
            var instructions = options?.Instructions ?? string.Empty;
            var inputCharacters = messages.Where(message => message.Role == ChatRole.User)
                .SelectMany(message => message.Contents.OfType<TextContent>())
                .Sum(content => content.Text.Length);
            prompts.Enqueue(new(instructions.Length, inputCharacters));

            if (instructions == parentInstructions)
            {
                if (Interlocked.Increment(ref parentTurns) == 1)
                    return new ChatResponse(new ChatMessage(ChatRole.Assistant,
                        [new FunctionCallContent("team-call", "team_0",
                            new Dictionary<string, object?> { ["task"] = task })]))
                    { ModelId = "proof-chat-v1", FinishReason = ChatFinishReason.ToolCalls };

                if (failParentFollowup)
                    throw new InvalidOperationException("Deterministic parent model failure after team failure.");
                return new ChatResponse(new ChatMessage(ChatRole.Assistant, "Team review complete."))
                { ModelId = "proof-chat-v1", FinishReason = ChatFinishReason.Stop };
            }

            var output = instructions == researcherInstructions
                ? new string('r', delegateOutputCharacters)
                : instructions == reviewerInstructions
                    ? new string('v', delegateOutputCharacters)
                    : throw new InvalidOperationException("Unexpected delegated model instructions.");
            var active = Interlocked.Increment(ref activeDelegates);
            UpdateMaximum(active);
            if (active >= 2) bothDelegatesStarted.TrySetResult();
            try
            {
                await bothDelegatesStarted.Task.WaitAsync(TimeSpan.FromSeconds(5), cancellationToken);
                if (holdReviewerUntilOutcomeRejected && instructions == reviewerInstructions)
                    await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken);
                if (blockDelegatesUntilCancelled)
                    await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken);
                if (failResearcher && instructions == researcherInstructions)
                {
                    if (researcherFailureStatusCode is { } statusCode)
                        throw new AgentProviderRequestException(AgentProviderFailureKind.Unavailable, statusCode);
                    throw new InvalidOperationException("Deterministic researcher failure.");
                }
                if (failResearcher && instructions == reviewerInstructions)
                    await Task.Delay(Timeout.InfiniteTimeSpan, cancellationToken);
                return new ChatResponse(new ChatMessage(ChatRole.Assistant, output))
                { ModelId = "proof-chat-v1", FinishReason = ChatFinishReason.Stop };
            }
            finally
            {
                Interlocked.Decrement(ref activeDelegates);
            }
        }

        private void UpdateMaximum(int candidate)
        {
            var current = Volatile.Read(ref maximumConcurrentDelegateCalls);
            while (candidate > current)
            {
                var previous = Interlocked.CompareExchange(ref maximumConcurrentDelegateCalls, candidate, current);
                if (previous == current) return;
                current = previous;
            }
        }
    }

